
            window.AGNES_CLOUD_PUBLIC_CONFIG = {
                endpoint: 'https://agnes-ai-studio-02306.app.workbuddy.host',
                publishableKey: 'wbpk_NEb03qsW9BggucocR7IKYd_tqZrXeBZbjkCNFhxuVOEkrPzLnvw5UWj'
            };
        

// ===== split =====


            (function () {
                let _inflight = 0;
                let _debounce = null;
                function paint() {
                    if (!document.body) return; // 🔴 IIFE 在 <head> 里跑，body 还没解析时直接跳过
                    if (_debounce) { clearTimeout(_debounce); _debounce = null; }
                    if (_inflight > 0) {
                        _debounce = setTimeout(function () { document.body.classList.add('has-gen'); }, 180);
                    } else {
                        document.body.classList.remove('has-gen');
                    }
                }
                const _origFetch = window.fetch;
                window.fetch = function (url, opts) {
                    _inflight++;
                    paint(); // 🔴 必须在 +1 后立刻 paint，否则 debounce 永远不调度（只在 .finally 里 paint 的话，.finally 跑完 _inflight 已归零）
                    return _origFetch.call(this, url, opts).finally(function () {
                        _inflight = Math.max(0, _inflight - 1);
                        paint();
                    });
                };
                if (document.body) paint(); else window.addEventListener('DOMContentLoaded', paint);
            })();
        

// ===== split =====


        /* ==================== 云服务（WorkBuddy Cloud）V1.8.139 ====================
           客户端只初始化一次，Auth / Database / Storage / LLM 共用同一个实例。
           endpoint 与 publishableKey 均取自开通时返回的 publicConfig（见 <head> 里的
           AGNES_CLOUD_PUBLIC_CONFIG），绝不由 location / 环境变量推导。 */
        var _agnesCloud = null;
        var _pendingEmailOtp = null;
        var _pendingReset = null;
        var _cloudConvId = null;
        var _cloudAbortCtl = null;
        var _cloudVideoUrl = null;   // 待发送视频直链（免密钥大模型聊天窗口附件）
        var _cloudVideoName = null;  // 待发送视频文件名（仅展示）

        function cloudSetMsg(id, text, ok) {
            var el = document.getElementById(id);
            if (!el) return;
            el.textContent = text || '';
            el.style.color = (ok === false) ? '#d33' : ((ok === true) ? '#1a9d5c' : 'var(--text2)');
        }

        function cloudClient() {
            if (_agnesCloud) return _agnesCloud;
            var cfg = window.AGNES_CLOUD_PUBLIC_CONFIG;
            if (!cfg || !window.WorkBuddyCloud || !window.WorkBuddyCloud.createWorkBuddyCloud) return null;
            try {
                _agnesCloud = window.WorkBuddyCloud.createWorkBuddyCloud({
                    endpoint: cfg.endpoint,
                    publishableKey: cfg.publishableKey
                });
            } catch (e) {
                cloudSetMsg('cloudMsg', '云服务初始化失败：' + (e && e.message ? e.message : e), false);
                return null;
            }
            return _agnesCloud;
        }

        // 鉴权门：任何用户级 Database / Storage 操作之前必须先拿到会话
        async function cloudSession(quiet) {
            var c = cloudClient();
            if (!c) {
                if (!quiet) cloudSetMsg('cloudMsg', '云服务未就绪：SDK 未加载（CDN 不可达）或配置缺失', false);
                return null;
            }
            try {
                var r = await c.auth.getSession();
                if (r.error || !r.data) {
                    if (!quiet) cloudSetMsg('cloudMsg', '请先登录云账号（邮箱登录）', false);
                    return null;
                }
                return r.data;
            } catch (e) {
                if (!quiet) cloudSetMsg('cloudMsg', '会话检查失败：' + (e && e.message ? e.message : e), false);
                return null;
            }
        }

        function cloudSwitchForm(which) {
            [['pwd', 'cloudFormPwd', 'cloudTabPwd'], ['otp', 'cloudFormOtp', 'cloudTabOtp'], ['reset', 'cloudFormReset', 'cloudTabReset']]
                .forEach(function (t) {
                    var box = document.getElementById(t[1]); if (box) box.style.display = (which === t[0]) ? '' : 'none';
                    var btn = document.getElementById(t[2]); if (btn) btn.classList.toggle('active', which === t[0]);
                });
        }

        function _val(id) { var el = document.getElementById(id); return el ? String(el.value || '').trim() : ''; }

        async function cloudRefreshStatus() {
            var badge = document.getElementById('cloudState');
            var c = cloudClient();
            if (!c) { if (badge) badge.textContent = 'SDK 未加载'; cloudSetMsg('cloudMsg', '云服务 SDK 未加载：CDN 不可达或被拦截，本页功能暂不可用', false); return; }
            var s = await cloudSession(true);
            if (s && s.user) {
                if (badge) badge.textContent = '已登录';
                // 只显示邮箱的脱敏形式，不打印身份 ID / 令牌
                var mail = s.user.email || '';
                var masked = mail ? mail.replace(/^(.{1,2}).*(@.*)$/, '$1***$2') : '（无邮箱）';
                cloudSetMsg('cloudMsg', '已登录：' + masked, true);
            } else {
                if (badge) badge.textContent = '未登录';
                cloudSetMsg('cloudMsg', '未登录。Web 应用仅支持邮箱登录。');
            }
        }

        async function cloudLoginPassword() {
            var email = _val('cloudEmail'), pwd = _val('cloudPassword');
            if (!email || !pwd) { cloudSetMsg('cloudMsg', '请填写邮箱和密码', false); return; }
            var c = cloudClient(); if (!c) { cloudSetMsg('cloudMsg', '云服务未就绪', false); return; }
            cloudSetMsg('cloudMsg', '登录中…');
            try {
                var r = await c.auth.signInWithPassword({ email: email, password: pwd });
                if (r.error) { cloudSetMsg('cloudMsg', '邮箱或密码错误', false); return; }
                cloudSetMsg('cloudMsg', '登录成功', true);
                cloudRefreshStatus();
            } catch (e) { cloudSetMsg('cloudMsg', '登录失败：' + (e && e.message ? e.message : e), false); }
        }

        async function cloudSendEmailCode() {
            var email = _val('cloudOtpEmail');
            if (!email) { cloudSetMsg('cloudMsg', '请填写邮箱', false); return; }
            var c = cloudClient(); if (!c) { cloudSetMsg('cloudMsg', '云服务未就绪', false); return; }
            var btn = document.getElementById('cloudSendBtn');
            if (btn) { btn.disabled = true; btn.textContent = '发送中…'; }
            try {
                var sent = await c.auth.sendOtp({ email: email });
                if (sent.error) { cloudSetMsg('cloudMsg', '验证码发送失败：' + (sent.error.message || ''), false); return; }
                _pendingEmailOtp = { email: email, verificationId: sent.data.verificationId, isExistingUser: sent.data.isExistingUser };
                cloudSetMsg('cloudMsg', '验证码已发送，请查收邮件后填入', true);
            } catch (e) { cloudSetMsg('cloudMsg', '发送失败：' + (e && e.message ? e.message : e), false); }
            finally { if (btn) { btn.disabled = false; btn.textContent = '获取验证码'; } }
        }

        async function cloudSubmitEmailOtp() {
            var email = _val('cloudOtpEmail'), code = _val('cloudOtpCode'), pwd = _val('cloudOtpPassword');
            var pending = _pendingEmailOtp;
            if (!pending || pending.email !== email) { cloudSetMsg('cloudMsg', '请先为当前邮箱获取验证码', false); return; }
            if (!code) { cloudSetMsg('cloudMsg', '请填入验证码', false); return; }
            // 新账号必须带密码，否则以后无法用密码登录
            if (!pending.isExistingUser && !pwd) { cloudSetMsg('cloudMsg', '该邮箱尚未注册，请填写要设置的密码', false); return; }
            var c = cloudClient(); if (!c) { cloudSetMsg('cloudMsg', '云服务未就绪', false); return; }
            cloudSetMsg('cloudMsg', '验证中…');
            try {
                var done = await c.auth.verifyOtp({
                    email: pending.email,
                    verificationId: pending.verificationId,
                    isExistingUser: pending.isExistingUser,
                    token: code,
                    password: pending.isExistingUser ? undefined : pwd
                });
                if (done.error) { cloudSetMsg('cloudMsg', '验证失败：' + (done.error.message || ''), false); return; }
                _pendingEmailOtp = null;
                cloudSetMsg('cloudMsg', '登录成功', true);
                cloudRefreshStatus();
            } catch (e) { cloudSetMsg('cloudMsg', '验证失败：' + (e && e.message ? e.message : e), false); }
        }

        async function cloudStartReset() {
            var email = _val('cloudResetEmail');
            if (!email) { cloudSetMsg('cloudMsg', '请填写邮箱', false); return; }
            var c = cloudClient(); if (!c) { cloudSetMsg('cloudMsg', '云服务未就绪', false); return; }
            try {
                var started = await c.auth.resetPasswordForEmail(email);
                if (started.error) { cloudSetMsg('cloudMsg', '重置邮件发送失败：' + (started.error.message || ''), false); return; }
                _pendingReset = started.data;
                cloudSetMsg('cloudMsg', '重置邮件已发送，请填入邮件里的验证码与新密码', true);
            } catch (e) { cloudSetMsg('cloudMsg', '发送失败：' + (e && e.message ? e.message : e), false); }
        }

        async function cloudFinishReset() {
            if (!_pendingReset) { cloudSetMsg('cloudMsg', '请先发送重置邮件', false); return; }
            var code = _val('cloudResetCode'), npwd = _val('cloudResetNewPwd');
            if (!code || !npwd) { cloudSetMsg('cloudMsg', '请填入验证码与新密码', false); return; }
            try {
                var r = await _pendingReset.updateUser({ nonce: code, password: npwd });
                if (r.error) { cloudSetMsg('cloudMsg', '重置失败：' + (r.error.message || ''), false); return; }
                _pendingReset = null;
                cloudSetMsg('cloudMsg', '密码已重置并已登录', true);
                cloudRefreshStatus();
            } catch (e) { cloudSetMsg('cloudMsg', '重置失败：' + (e && e.message ? e.message : e), false); }
        }

        async function cloudSignOut() {
            var c = cloudClient(); if (!c) return;
            try { await c.auth.signOut(); } catch (e) {}
            _pendingEmailOtp = null; _pendingReset = null;
            cloudSetMsg('cloudMsg', '已退出登录');
            cloudRefreshStatus();
        }

        async function cloudCanvasSave() {
            var s = await cloudSession(); if (!s) return;
            var c = cloudClient();
            var raw = '';
            try { raw = localStorage.getItem('agnesCanvasData') || ''; } catch (e) {}
            if (!raw) { cloudSetMsg('cloudCanvasMsg', '本地没有画布数据，请先去「🕸 无限画布」画点东西', false); return; }
            cloudSetMsg('cloudCanvasMsg', '保存中…');
            try {
                var exist = await c.database.from('canvas_docs').select('id').eq('doc_key', 'default').limit(1);
                if (exist.error) { cloudSetMsg('cloudCanvasMsg', '读取失败：' + (exist.error.message || exist.error.code || ''), false); return; }
                var res;
                if (exist.data && exist.data.length) {
                    // 必须带 .select()：RLS 拦下时返回空数组而不是报错，靠它区分「没改到」和「改到了」
                    res = await c.database.from('canvas_docs')
                        .update({ payload: raw, title: '我的画布', updated_at: new Date().toISOString() })
                        .eq('id', exist.data[0].id).select();
                } else {
                    res = await c.database.from('canvas_docs')
                        .insert({ doc_key: 'default', title: '我的画布', payload: raw }).select();
                }
                if (res.error) {
                    var code = res.error.code || '';
                    if (code === '42501') cloudSetMsg('cloudCanvasMsg', '没有权限写入（请确认已登录）', false);
                    else if (code === '42P01') cloudSetMsg('cloudCanvasMsg', '云端画布表尚未创建', false);
                    else cloudSetMsg('cloudCanvasMsg', '保存失败：' + (res.error.message || code), false);
                    return;
                }
                if (!res.data || !res.data.length) { cloudSetMsg('cloudCanvasMsg', '没有写入任何行 —— 该记录可能不属于当前账号', false); return; }
                cloudSetMsg('cloudCanvasMsg', '已保存到云端（' + raw.length + ' 字节）', true);
            } catch (e) { cloudSetMsg('cloudCanvasMsg', '保存异常：' + (e && e.message ? e.message : e), false); }
        }

        async function cloudCanvasLoad() {
            var s = await cloudSession(); if (!s) return;
            var c = cloudClient();
            cloudSetMsg('cloudCanvasMsg', '读取中…');
            try {
                var r = await c.database.from('canvas_docs').select('payload,updated_at')
                    .eq('doc_key', 'default').order('updated_at', { ascending: false }).limit(1);
                if (r.error) { cloudSetMsg('cloudCanvasMsg', '读取失败：' + (r.error.message || r.error.code || ''), false); return; }
                if (!r.data || !r.data.length) { cloudSetMsg('cloudCanvasMsg', '云端还没有你的画布草稿', false); return; }
                var payload = r.data[0].payload;
                try { localStorage.setItem('agnesCanvasData', payload); } catch (e) {}
                // 复用现有渲染入口，不在这里手搓画布
                if (typeof loadCanvasData === 'function') {
                    await loadCanvasData();
                    cloudSetMsg('cloudCanvasMsg', '已从云端读取并载入画布（' + payload.length + ' 字节）', true);
                } else {
                    cloudSetMsg('cloudCanvasMsg', '已下载到本地，请切到「🕸 无限画布」查看', true);
                }
            } catch (e) { cloudSetMsg('cloudCanvasMsg', '读取异常：' + (e && e.message ? e.message : e), false); }
        }

        async function cloudUpload() {
            var s = await cloudSession(); if (!s) return;
            var c = cloudClient();
            var input = document.getElementById('cloudFile');
            if (!input || !input.files || !input.files[0]) { cloudSetMsg('cloudMsg', '请先选择文件', false); return; }
            var file = input.files[0];
            var ext = (file.name || '').split('.').pop() || 'bin';
            ext = ext.replace(/[^a-zA-Z0-9]/g, '').slice(0, 8) || 'bin';
            // 不信任客户端文件名：用随机名构造安全路径
            var rid = (window.crypto && crypto.randomUUID) ? crypto.randomUUID() : String(Date.now()) + Math.random().toString(36).slice(2);
            var path;
            try { path = c.storage.userPath(s.user.id, 'uploads/' + rid + '.' + ext); }
            catch (e) { cloudSetMsg('cloudMsg', '路径非法：' + (e && e.message ? e.message : e), false); return; }
            cloudSetMsg('cloudMsg', '上传中…');
            try {
                var up = await c.storage.upload(path, file, { contentType: file.type || 'application/octet-stream', upsert: false });
                if (up.error) { cloudSetMsg('cloudMsg', '上传失败：' + (up.error.message || ''), false); return; }
                cloudSetMsg('cloudMsg', '上传成功', true);
                cloudListFiles();
            } catch (e) { cloudSetMsg('cloudMsg', '上传异常：' + (e && e.message ? e.message : e), false); }
        }

        async function cloudListFiles() {
            var s = await cloudSession(); if (!s) return;
            var c = cloudClient();
            var box = document.getElementById('cloudFileList');
            try {
                var r = await c.storage.list('users/' + s.user.id, { limit: 20 });
                if (r.error) { if (box) box.textContent = '列举失败：' + (r.error.message || ''); return; }
                var items = r.data || [];
                if (!items.length) { if (box) box.textContent = '（还没有文件）'; return; }
                if (box) box.textContent = '';
                items.forEach(function (it) {
                    var row = document.createElement('div');
                    row.style.cssText = 'display:flex;gap:8px;align-items:center;';
                    var name = document.createElement('span');
                    name.textContent = String(it.name || '').replace(/^.*\//, '');
                    name.style.cssText = 'flex:1;overflow:hidden;text-overflow:ellipsis;';
                    var a = document.createElement('button');
                    a.className = 'btn btn-sm';
                    a.textContent = '⬇ 下载';
                    a.onclick = function () { cloudDownload(it.key || it.name); };
                    row.appendChild(name); row.appendChild(a);
                    if (box) box.appendChild(row);
                });
            } catch (e) { if (box) box.textContent = '列举异常：' + (e && e.message ? e.message : e); }
        }

        async function cloudDownload(key) {
            var s = await cloudSession(); if (!s) return;
            var c = cloudClient();
            try {
                var r = await c.storage.createSignedUrl(key, 600);
                if (r.error) { cloudSetMsg('cloudMsg', '生成下载链接失败：' + (r.error.message || ''), false); return; }
                var url = r.data && (r.data.signedUrl || r.data.url);
                if (!url) { cloudSetMsg('cloudMsg', '下载链接为空', false); return; }
                window.open(url, '_blank');
            } catch (e) { cloudSetMsg('cloudMsg', '下载异常：' + (e && e.message ? e.message : e), false); }
        }

        async function cloudLoadModels() {
            var c = cloudClient();
            if (!c) { cloudSetMsg('cloudLlmMsg', '云服务未就绪', false); return; }
            var sel = document.getElementById('cloudModelSel');
            cloudSetMsg('cloudLlmMsg', '拉取模型列表…');
            try {
                var models = await c.llm.models.list();
                var list = models || [];
                if (!list.length) { cloudSetMsg('cloudLlmMsg', '当前环境没有可用模型', false); if (sel) sel.innerHTML = ''; return; }
                if (sel) {
                    sel.innerHTML = '';
                    list.forEach(function (m) {
                        var op = document.createElement('option');
                        op.value = m.id;
                        op.textContent = (m.name || m.id) + (m.disabled === true ? '（不可用）' : '');
                        if (m.disabled === true) op.disabled = true;
                        sel.appendChild(op);
                    });
                }
                cloudSetMsg('cloudLlmMsg', '共 ' + list.length + ' 个模型', true);
            } catch (e) { cloudSetMsg('cloudLlmMsg', '拉取失败：' + (e && e.message ? e.message : e), false); }
        }

        var _cloudMsgs = [];          // [{role:'user'|'assistant', content}] —— 多轮上下文来源

        function cloudEsc(s) {
            return String(s == null ? '' : s)
                .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
        }

        // 气泡：用户靠右（主色底），AI 靠左（描边底）—— 与 hcHistory 的观感一致
        function cloudBubble(role, html) {
            var wrap = document.createElement('div');
            wrap.style.cssText = 'display:flex;margin-bottom:10px;'
                + (role === 'user' ? 'justify-content:flex-end;' : 'justify-content:flex-start;');
            var inner = document.createElement('div');
            inner.style.cssText = 'max-width:78%;padding:10px 12px;border-radius:10px;font-size:13px;'
                + 'line-height:1.8;white-space:pre-wrap;word-break:break-word;'
                + (role === 'user'
                    ? 'background:var(--accent);color:var(--on-accent);'
                    : 'background:var(--surface);color:var(--text);border:1px solid var(--border);');
            inner.innerHTML = html;
            wrap.appendChild(inner);
            return { wrap: wrap, inner: inner };
        }

        // AI 气泡操作条：直接复用对话页那套（hcCopyText / hcReadToggle），不另造一套语音逻辑
        function cloudAddActions(inner, text) {
            var bar = document.createElement('div');
            bar.style.cssText = 'display:flex;gap:14px;margin-top:8px;padding-top:6px;'
                + 'border-top:1px dashed var(--border);font-size:11px;';
            var mk = function (label, fn) {
                var a = document.createElement('span');
                a.textContent = label;
                a.style.cssText = 'cursor:pointer;color:var(--text2);user-select:none;transition:color .15s;';
                a.onmouseenter = function () { a.style.color = '#6366f1'; };
                a.onmouseleave = function () { a.style.color = 'var(--text2)'; };
                a.onclick = fn;
                return a;
            };
            bar.appendChild(mk('📋 复制', function () { hcCopyText(text); }));
            bar.appendChild(mk('🔊 朗读', function () { hcReadToggle(text, this); }));
            inner.appendChild(bar);
        }

        function cloudRender() {
            var box = document.getElementById('cloudHistory');
            if (!box) return;
            box.innerHTML = '';
            if (!_cloudMsgs.length) {
                return;
            }
            _cloudMsgs.forEach(function (m) {
                var html = '';
                if (m.role === 'user' && m.video) html += cloudVideoBlock(m.video);
                html += cloudEsc(m.content);
                var b = cloudBubble(m.role, html);
                if (m.role === 'assistant' && m.content) cloudAddActions(b.inner, m.content);
                box.appendChild(b.wrap);
            });
            box.scrollTop = box.scrollHeight;
        }

        // Enter 发送 / Shift+Enter 换行。⚠️ 必须判 isComposing / keyCode 229：
        // 中文输入法敲 Enter 选候选词时也会触发 keydown，不判会把候选词直接发出去。
        function cloudInputKey(e) {
            if (e.key === 'Enter' && !e.shiftKey && !(e.isComposing || e.keyCode === 229)) {
                e.preventDefault();
                cloudAsk();
            }
        }

        function cloudLastAnswer() {
            for (var i = _cloudMsgs.length - 1; i >= 0; i--) {
                if (_cloudMsgs[i].role === 'assistant') return _cloudMsgs[i].content;
            }
            return '';
        }

        function cloudCopyLast() {
            var t = cloudLastAnswer();
            if (!t) { cloudSetMsg('cloudLlmMsg', '还没有可复制的回答', false); return; }
            hcCopyText(t);
        }

        // 播报：直接复用对话页那套 TTS（优先 MOSS-TTS-Nano，未就绪退浏览器语音）。
        // 传按钮自身当 span → 播报过程中按钮会显示「⏳ 合成中… / ⏹ 停止朗读」，再点一次即停；
        // 结束后统一把标签写回「🔊 播报」（hcSpeakAuto 内部收尾写的是「🔊 朗读」，这里改回本页口径）。
        async function cloudSpeakLast() {
            var t = cloudLastAnswer();
            if (!t) { cloudSetMsg('cloudLlmMsg', '还没有可播报的回答', false); return; }
            var btn = document.getElementById('cloudSpeakBtn');
            if (!btn) return;
            if (hcTtsSpan === btn) { hcTtsStop(); btn.textContent = '🔊 播报'; return; }
            hcTtsStop();
            try { await hcSpeakAuto(t, btn); } finally { btn.textContent = '🔊 播报'; }
        }

        function cloudClear() {
            _cloudMsgs = [];
            _cloudConvId = null;     // 换会话 id：云端上下文一并断开，不是只清屏
            cloudRemoveVideo();
            cloudRender();
            cloudSetMsg('cloudLlmMsg', '已清空会话');
        }

        // —— 免密钥大模型聊天窗口：视频附件 ——
        function cloudPickVideo() {
            var input = document.getElementById('cloudVideoFile');
            if (input) input.click();
        }

        // 附件行渲染：有视频显示文件名 + 预览 + 移除；无则隐藏
        function cloudRenderVideoAttach() {
            var box = document.getElementById('cloudVideoAttach');
            if (!box) return;
            box.innerHTML = '';
            if (!_cloudVideoUrl) { box.style.display = 'none'; return; }
            box.style.display = 'flex';
            var name = document.createElement('span');
            name.textContent = '🎬 ' + (_cloudVideoName || '视频');
            name.style.cssText = 'overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:220px;';
            box.appendChild(name);
            var a = document.createElement('button');
            a.className = 'btn btn-sm';
            a.textContent = '✕ 移除';
            a.onclick = cloudRemoveVideo;
            box.appendChild(a);
        }

        async function cloudVideoChosen(input) {
            if (!input || !input.files || !input.files[0]) return;
            var file = input.files[0];
            input.value = '';
            var s = await cloudSession(); if (!s) return;   // 上传走存储，必须先登录
            var c = cloudClient();
            cloudSetMsg('cloudLlmMsg', '视频上传中…');
            try {
                var ext = (file.name || '').split('.').pop() || 'mp4';
                ext = ext.replace(/[^a-zA-Z0-9]/g, '').slice(0, 8) || 'mp4';
                // 不信任客户端文件名：用随机名构造安全路径
                var rid = (window.crypto && crypto.randomUUID) ? crypto.randomUUID()
                    : String(Date.now()) + Math.random().toString(36).slice(2);
                var path;
                try { path = c.storage.userPath(s.user.id, 'chat/videos/' + rid + '.' + ext); }
                catch (e) { cloudSetMsg('cloudLlmMsg', '路径非法：' + (e && e.message ? e.message : e), false); return; }
                var up = await c.storage.upload(path, file, { contentType: file.type || 'video/mp4', upsert: false });
                if (up.error) { cloudSetMsg('cloudLlmMsg', '上传失败：' + (up.error.message || up.error.code || ''), false); return; }
                // 直链签名有效期 600s：发出去后模型若在有效期内取，能直接读
                var key = up.key || up.data && up.data.key || path;
                var su = await c.storage.createSignedUrl(key, 600);
                if (su.error) { cloudSetMsg('cloudLlmMsg', '生成链接失败：' + (su.error.message || ''), false); return; }
                _cloudVideoUrl = su.data.url;
                _cloudVideoName = file.name;
                cloudRenderVideoAttach();
                cloudSetMsg('cloudLlmMsg', '已上传视频，发送后把链接带给模型', true);
            } catch (e) { cloudSetMsg('cloudLlmMsg', '上传异常：' + (e && e.message ? e.message : e), false); }
        }

        function cloudRemoveVideo() {
            _cloudVideoUrl = null;
            _cloudVideoName = null;
            cloudRenderVideoAttach();
        }

        // 视频在用户气泡里的内嵌渲染（≤240px 高播放器 + 链接）
        function cloudVideoBlock(url) {
            return '<video src="' + cloudEsc(url) + '" controls preload="metadata" style="max-width:100%;max-height:240px;'
                + 'border-radius:8px;display:block;margin-bottom:6px;"></video>'
                + '<a href="' + cloudEsc(url) + '" target="_blank" rel="noopener" style="font-size:11px;color:var(--text2);">'
                + '打开视频链接</a>';
        }

        async function cloudAsk() {
            var c = cloudClient();
            if (!c) { cloudSetMsg('cloudLlmMsg', '云服务未就绪', false); return; }
            var sel = document.getElementById('cloudModelSel');
            var model = sel ? sel.value : '';
            var ta = document.getElementById('cloudPrompt');
            var prompt = _val('cloudPrompt');
            if (!model) { cloudSetMsg('cloudLlmMsg', '请先拉取并选择模型', false); return; }
            if (!prompt && !_cloudVideoUrl) { cloudSetMsg('cloudLlmMsg', '请输入问题或上传视频', false); return; }
            if (ta) ta.value = '';

            if (!_cloudConvId) {
                _cloudConvId = (window.crypto && crypto.randomUUID) ? crypto.randomUUID()
                    : 'c' + Date.now().toString(36) + Math.random().toString(36).slice(2);
            }

            // ① 用户气泡 ② AI 占位气泡（流式往里写）
            var userMsg = { role: 'user', content: prompt };
            if (_cloudVideoUrl) { userMsg.video = _cloudVideoUrl; userMsg.videoName = _cloudVideoName; }
            _cloudMsgs.push(userMsg);
            var ai = { role: 'assistant', content: '' };
            _cloudMsgs.push(ai);
            cloudRender();
            var hist = document.getElementById('cloudHistory');
            var aiInner = (hist && hist.lastElementChild) ? hist.lastElementChild.firstChild : null;

            var btn = document.getElementById('cloudAskBtn');
            if (btn) btn.disabled = true;
            _cloudAbortCtl = new AbortController();
            cloudSetMsg('cloudLlmMsg', '生成中…');
            var text = '';
            try {
                // 多轮上下文：system + 全部非空历史（占位那条 content 为空，自动跳过）
                var msgs = [{ role: 'system', content: '你是临智AI 的创作助手，回答简洁、专业、可直接用于创作。' }];
                _cloudMsgs.forEach(function (m) {
                    // 用户消息带视频：把视频直链作为可见文本拼进上下文（模型若支持视频理解可读画面，否则也能拿到链接）
                    var body = m.content || '';
                    if (m.role === 'user' && m.video) {
                        body = '[用户上传了一个视频，链接：' + m.video + (m.videoName ? '（' + m.videoName + '）' : '') + ']\n' + body;
                    }
                    if (body) msgs.push({ role: m.role, content: body });
                });
                // stream:true 是唯一的调用方式；messages[0] 必须是 system
                var stream = await c.llm.chat.completions.create({
                    model: model,
                    messages: msgs,
                    stream: true,
                    temperature: 1,
                    conversationId: _cloudConvId,
                    signal: _cloudAbortCtl.signal
                });
                for await (const chunk of stream) {
                    var d = chunk && chunk.choices && chunk.choices[0] && chunk.choices[0].delta;
                    if (d && d.content) {
                        text += d.content;
                        ai.content = text;
                        if (aiInner) aiInner.textContent = text;
                    }
                }
                ai.content = text;
                cloudRender();      // 收尾重渲染 → 挂上 📋 复制 / 🔊 朗读
                cloudRemoveVideo(); // 已发送的视频附件清空（历史消息里的 video 字段已固化在 _cloudMsgs）
                cloudSetMsg('cloudLlmMsg', text ? ('完成（' + text.length + ' 字）') : '没有返回内容', text ? true : false);
            } catch (e) {
                var code = e && e.error && e.error.code ? e.error.code : '';
                if (text) { ai.content = text; cloudRender(); }   // 中断时保留已生成内容
                else { _cloudMsgs.pop(); cloudRender(); }         // 一个字都没有 → 撤掉占位气泡
                if (code === 'request_stream_required') cloudSetMsg('cloudLlmMsg', '调用参数错误：必须使用流式调用', false);
                else if (code && code.indexOf('auth_') === 0) cloudSetMsg('cloudLlmMsg', '云服务鉴权未通过（需在本应用的发布域名下访问）', false);
                else if (code && code.indexOf('quota_') === 0) cloudSetMsg('cloudLlmMsg', '额度已用尽或触发限流，请稍后再试', false);
                else if (code && (code.indexOf('gateway_') === 0 || code.indexOf('model_') === 0)) cloudSetMsg('cloudLlmMsg', '模型服务暂时不可用，请重试', false);
                else if (e && e.name === 'AbortError') cloudSetMsg('cloudLlmMsg', '已停止');
                else cloudSetMsg('cloudLlmMsg', '调用失败：' + (e && e.message ? e.message : e), false);
            } finally {
                if (btn) btn.disabled = false;
                _cloudAbortCtl = null;
            }
        }

        function cloudAbort() {
            if (_cloudAbortCtl) { try { _cloudAbortCtl.abort(); } catch (e) {} }
            else { cloudSetMsg('cloudLlmMsg', '当前没有正在进行的请求'); }
        }

        // 进入页面时自动拉一次状态（SDK 若未加载会给出明确提示，不静默降级）
        setTimeout(function () { cloudRefreshStatus(); cloudRender(); }, 300);
        

// ===== split =====


(function(){

        // ========== 全局状态 ==========
        let docContent = '';       // 上传的文档内容
        let promptFiles = {        // 各功能的提示词内容
            review: '',
            screenplay: '',
            polish: '',
            rewrite: ''
        };
        let currentController = null;  // 用于中断请求
        let isGenerating = false;

        // ========== 页面初始化 ==========
        document.addEventListener('DOMContentLoaded', () => {
            loadFromLocal();
            updateCharCount();
        });

        

        // ========== API Key 显示/隐藏 ==========
        function toggleApiKeyVisibility() {
            const input = document.getElementById('jyApiKeyInput');
            const icon = document.getElementById('eyeIcon');
            if (input.type === 'password') {
                input.type = 'text';
                icon.innerHTML = '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.59 3.59m0 0A9.953 9.953 0 0112 5c4.478 0 8.268 2.943 9.543 7a10.025 10.025 0 01-4.132 5.411m0 0L21 21"/>';
            } else {
                input.type = 'password';
                icon.innerHTML = '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/>';
            }
        }

        // ========== 连接测试 ==========
        async function testConnection() {
            const apiKey = document.getElementById('jyApiKeyInput').value.trim();
            if (!apiKey) {
                showToast('请先输入 API Key', 'warning');
                return;
            }
            
            const statusEl = document.getElementById('connectionStatus');
            statusEl.innerHTML = '<span class="w-2 h-2 rounded-full bg-yellow-400 animate-pulse"></span> 测试中...';
            statusEl.className = 'flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-full bg-yellow-50 text-yellow-600';

            try {
                const response = await fetch('https://api.deepseek.com/chat/completions', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': `Bearer ${apiKey}`
                    },
                    body: JSON.stringify({
                        model: document.getElementById('modelSelect').value,
                        messages: [{ role: 'user', content: 'Hi' }],
                        max_tokens: 5
                    })
                });

                if (response.ok) {
                    statusEl.innerHTML = '<span class="w-2 h-2 rounded-full bg-green-400"></span> 已连接';
                    statusEl.className = 'flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-full bg-green-50 text-green-600';
                    showToast('API 连接成功！', 'success');
                } else {
                    const errData = await response.json().catch(() => ({}));
                    throw new Error(errData.error?.message || `HTTP ${response.status}`);
                }
            } catch (e) {
                statusEl.innerHTML = '<span class="w-2 h-2 rounded-full bg-red-400"></span> 连接失败';
                statusEl.className = 'flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-full bg-red-50 text-red-600';
                showToast(`连接失败: ${e.message}`, 'error');
            }
        }

        // ========== 文件读取工具函数 ==========
        
        let _mammothLoading = null;
        function ensureMammoth(){
            if (window.mammoth) return Promise.resolve();
            if (!_mammothLoading) {
                _mammothLoading = new Promise((res, rej) => {
                    const sc = document.createElement('script');
                    sc.src = 'https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.6.0/mammoth.browser.min.js';
                    sc.onload = () => res();
                    sc.onerror = () => { _mammothLoading = null; rej(new Error('mammoth.js 加载失败')); };
                    document.head.appendChild(sc);
                });
            }
            return _mammothLoading;
        }

        async function readFileContent(file) {
            return new Promise((resolve, reject) => {
                const ext = file.name.split('.').pop().toLowerCase();
                
                if (ext === 'txt') {
                    const reader = new FileReader();
                    reader.onload = (e) => resolve(e.target.result);
                    reader.onerror = () => reject(new Error('文件读取失败'));
                    reader.readAsText(file, 'UTF-8');
                } else if (ext === 'docx') {
                    const reader = new FileReader();
                    reader.onload = async (e) => { await ensureMammoth();
                        mammoth.extractRawText({ arrayBuffer: e.target.result })
                            .then(result => resolve(result.value))
                            .catch(() => reject(new Error('DOCX 解析失败')));
                    };
                    reader.onerror = () => reject(new Error('文件读取失败'));
                    reader.readAsArrayBuffer(file);
                } else if (ext === 'doc') {
                    // .doc 格式尝试以文本读取 (有限支持)
                    const reader = new FileReader();
                    reader.onload = (e) => {
                        // 尝试提取可读文本
                        let text = e.target.result;
                        // 过滤掉不可见字符
                        text = text.replace(/[^\x20-\x7E\u4e00-\u9fff\u3000-\u303f\uff00-\uffef\n\r\t]/g, '');
                        if (text.trim().length > 0) {
                            resolve(text);
                        } else {
                            reject(new Error('DOC 格式解析受限，建议转换为 DOCX 或 TXT 格式'));
                        }
                    };
                    reader.onerror = () => reject(new Error('文件读取失败'));
                    reader.readAsText(file, 'UTF-8');
                } else {
                    reject(new Error('不支持的文件格式'));
                }
            });
        }

        // ========== 拖拽上传处理 ==========
        function handleDragOver(e, zoneId) {
            e.preventDefault();
            document.getElementById(zoneId).classList.add('dragover');
        }

        function handleDragLeave(e, zoneId) {
            e.preventDefault();
            document.getElementById(zoneId).classList.remove('dragover');
        }

        function handleDrop(e, inputId) {
            e.preventDefault();
            const zone = e.currentTarget;
            zone.classList.remove('dragover');
            const files = e.dataTransfer.files;
            if (files.length > 0) {
                const input = document.getElementById(inputId);
                // 创建新的 DataTransfer 来设置 input 的 files
                const dt = new DataTransfer();
                dt.items.add(files[0]);
                input.files = dt.files;
                input.dispatchEvent(new Event('change'));
            }
        }

        // ========== 文档上传处理 ==========
        async function handleDocUpload(event) {
            const file = event.target.files[0];
            if (!file) return;

            try {
                showToast('正在读取文档...', 'info');
                docContent = await readFileContent(file);
                document.getElementById('docFileName').textContent = file.name;
                document.getElementById('docFileInfo').classList.remove('hidden');
                showToast(`文档 "${file.name}" 读取成功 (${docContent.length} 字)`, 'success');
            } catch (e) {
                showToast(e.message, 'error');
                docContent = '';
            }
        }

        function loadDocToOutput() {
            if (!docContent) {
                showToast('没有可加载的文档内容', 'warning');
                return;
            }
            document.getElementById('outputArea').value = docContent;
            updateCharCount();
            showToast('文档内容已加载到编辑区', 'success');
        }

        function clearDocFile() {
            docContent = '';
            document.getElementById('docFileInput').value = '';
            document.getElementById('docFileInfo').classList.add('hidden');
            showToast('文档已清除', 'info');
        }

        // ========== 提示词文件上传处理 ==========
        async function handlePromptUpload(event, type) {
            const file = event.target.files[0];
            if (!file) return;

            try {
                const content = await readFileContent(file);
                promptFiles[type] = content;
                document.getElementById(`${type}PromptName`).textContent = file.name;
                document.getElementById(`${type}PromptInfo`).classList.remove('hidden');
                document.getElementById(`${type}PromptEmpty`).classList.add('hidden');
                showToast(`提示词文件 "${file.name}" 已加载`, 'success');
            } catch (e) {
                showToast(e.message, 'error');
            }
        }

        function clearPrompt(type) {
            promptFiles[type] = '';
            document.getElementById(`${type}PromptInfo`).classList.add('hidden');
            document.getElementById(`${type}PromptEmpty`).classList.remove('hidden');
            showToast('提示词已清除', 'info');
        }

        // ========== 字数统计 ==========
        function updateCharCount() {
            const text = document.getElementById('outputArea').value;
            const count = text.length;
            document.getElementById('jyCharCount').textContent = `${count.toLocaleString()} 字`;
        }

        // ========== 进度条控制 ==========
        function showProgress(percent) {
            const bar = document.getElementById('progressBar');
            bar.style.width = percent + '%';
        }

        function startProgressAnimation() {
            let progress = 0;
            const bar = document.getElementById('progressBar');
            bar.style.width = '0%';
            
            const interval = setInterval(() => {
                if (progress < 90) {
                    progress += Math.random() * 3;
                    bar.style.width = Math.min(progress, 90) + '%';
                }
            }, 500);
            
            return interval;
        }

        function finishProgress(interval) {
            clearInterval(interval);
            const bar = document.getElementById('progressBar');
            bar.style.width = '100%';
            setTimeout(() => { bar.style.width = '0%'; }, 800);
        }

        // ========== 核心 API 调用（流式） ==========
        async function callDeepSeekAPI(systemPrompt, userContent, loadingMsg = 'AI 生成中...') {
            const apiKey = document.getElementById('jyApiKeyInput').value.trim();
            if (!apiKey) {
                showToast('请先输入 API Key', 'warning');
                return;
            }

            if (!userContent.trim()) {
                showToast('没有可处理的文本内容', 'warning');
                return;
            }

            // 显示加载状态
            isGenerating = true;
            document.getElementById('loadingIndicator').classList.remove('hidden');
            document.getElementById('jyLoadingText').textContent = loadingMsg;
            document.getElementById('stopBtn').classList.remove('hidden');
            setButtonsDisabled(true);

            const progressInterval = startProgressAnimation();
            const outputArea = document.getElementById('outputArea');
            outputArea.value = '';
            updateCharCount();

            currentController = new AbortController();

            try {
                const messages = [];
                if (systemPrompt) {
                    messages.push({ role: 'system', content: systemPrompt });
                }
                messages.push({ role: 'user', content: userContent });

                const response = await fetch('https://api.deepseek.com/chat/completions', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': `Bearer ${apiKey}`
                    },
                    body: JSON.stringify({
                        model: document.getElementById('modelSelect').value,
                        messages: messages,
                        stream: true,
                        temperature: 0.7,
                        max_tokens: 8192
                    }),
                    signal: currentController.signal
                });

                if (!response.ok) {
                    const errData = await response.json().catch(() => ({}));
                    throw new Error(errData.error?.message || `API 请求失败 (HTTP ${response.status})`);
                }

                // 流式读取
                const reader = response.body.getReader();
                const decoder = new TextDecoder();
                let buffer = '';

                while (true) {
                    const { done, value } = await reader.read();
                    if (done) break;

                    buffer += decoder.decode(value, { stream: true });
                    const lines = buffer.split('\n');
                    buffer = lines.pop() || '';

                    for (const line of lines) {
                        const trimmed = line.trim();
                        if (!trimmed || !trimmed.startsWith('data: ')) continue;
                        
                        const data = trimmed.slice(6);
                        if (data === '[DONE]') continue;

                        try {
                            const json = JSON.parse(data);
                            const content = json.choices?.[0]?.delta?.content;
                            if (content) {
                                outputArea.value += content;
                                outputArea.scrollTop = outputArea.scrollHeight;
                                updateCharCount();
                            }
                        } catch (e) {
                            // 跳过无法解析的行
                        }
                    }
                }

                showToast('生成完成！', 'success');

            } catch (e) {
                if (e.name === 'AbortError') {
                    showToast('生成已停止', 'info');
                } else {
                    showToast(`错误: ${e.message}`, 'error');
                }
            } finally {
                isGenerating = false;
                document.getElementById('loadingIndicator').classList.add('hidden');
                document.getElementById('stopBtn').classList.add('hidden');
                setButtonsDisabled(false);
                finishProgress(progressInterval);
                currentController = null;
            }
        }

        function stopGeneration() {
            if (currentController) {
                currentController.abort();
            }
        }

        function setButtonsDisabled(disabled) {
            const btns = ['btnRewrite', 'btnReview', 'btnScreenplay', 'btnPolish'];
            btns.forEach(id => {
                const btn = document.getElementById(id);
                btn.disabled = disabled;
                btn.style.opacity = disabled ? '0.6' : '1';
                btn.style.pointerEvents = disabled ? 'none' : 'auto';
            });
        }

        // ========== 各功能调用 ==========
        
        // 改写功能
        function callRewrite() {
            const outputText = document.getElementById('outputArea').value.trim();
            const instruction = document.getElementById('instructionInput').value.trim();
            
            if (!outputText && !docContent) {
                showToast('请先输入文本或上传文档', 'warning');
                return;
            }

            let systemPrompt = promptFiles.rewrite || '你是一位专业的小说改写专家。请根据用户的要求对提供的文本进行改写，保持原文核心情节和人物不变，优化文笔、结构和表达，使文章更加生动、流畅、有文学性。请直接输出改写后的完整文本。';
            
            let userMessage = '';
            if (instruction) {
                userMessage += `【改写要求】\n${instruction}\n\n`;
            }
            userMessage += `【原文内容】\n${outputText || docContent}`;

            callDeepSeekAPI(systemPrompt, userMessage, '正在改写中...');
        }

        // 审稿功能
        function callReview() {
            const outputText = document.getElementById('outputArea').value.trim();
            
            if (!outputText && !docContent) {
                showToast('请先输入文本或上传文档', 'warning');
                return;
            }

            let systemPrompt = promptFiles.review || `你是一位资深的小说审稿编辑。请对以下文本进行全面审稿，包括但不限于：
1. 错别字、标点符号、语法错误纠正
2. 语句不通顺、逻辑不连贯的地方标注修改
3. 人物性格前后一致性检查
4. 情节合理性审查
5. 叙事节奏和结构建议
6. 文笔优化建议

请先列出发现的问题清单，然后给出修改后的完整文本。`;

            const instruction = document.getElementById('instructionInput').value.trim();
            let userMessage = '';
            if (instruction) {
                userMessage += `【额外审稿要求】\n${instruction}\n\n`;
            }
            userMessage += `【待审稿文本】\n${outputText || docContent}`;

            callDeepSeekAPI(systemPrompt, userMessage, '正在审稿中...');
        }

        // 改编剧本功能
        function callScreenplay() {
            const outputText = document.getElementById('outputArea').value.trim();
            
            if (!outputText && !docContent) {
                showToast('请先输入文本或上传文档', 'warning');
                return;
            }

            let systemPrompt = promptFiles.screenplay || `你是一位专业的编剧。请将以下小说文本改编为标准剧本格式，要求：
1. 使用标准剧本格式（场景描述、角色对白、动作指示、转场等）
2. 保留原文核心情节和人物关系
3. 将内心独白转化为可视化的动作或对话
4. 添加必要的场景描述（时间、地点、环境）
5. 人物对话自然生动，符合角色性格
6. 合理安排场景转换和节奏

请直接输出完整的剧本内容。`;

            const instruction = document.getElementById('instructionInput').value.trim();
            let userMessage = '';
            if (instruction) {
                userMessage += `【改编要求】\n${instruction}\n\n`;
            }
            userMessage += `【原文内容】\n${outputText || docContent}`;

            callDeepSeekAPI(systemPrompt, userMessage, '正在改编剧本中...');
        }

        // 消痕功能
        function callPolish() {
            const outputText = document.getElementById('outputArea').value.trim();
            
            if (!outputText && !docContent) {
                showToast('请先输入文本或上传文档', 'warning');
                return;
            }

            let systemPrompt = promptFiles.polish || `你是一位专业的文本润色专家。请对以下文本进行"消痕"处理，具体包括：
1. 消除AI写作痕迹：去除过于模板化、公式化的表达
2. 减少重复：消除语义重复、词汇重复、句式重复
3. 去除冗余：删除不必要的修饰、重复的描写、拖沓的叙述
4. 风格自然化：使文本读起来更像人类自然写作的风格
5. 词汇丰富化：替换过于常见和重复使用的词汇
6. 句式多样化：避免相似句式的频繁使用

请在保持原文内容和情感不变的前提下，直接输出润色后的完整文本。`;

            const instruction = document.getElementById('instructionInput').value.trim();
            let userMessage = '';
            if (instruction) {
                userMessage += `【消痕要求】\n${instruction}\n\n`;
            }
            userMessage += `【待处理文本】\n${outputText || docContent}`;

            callDeepSeekAPI(systemPrompt, userMessage, '正在消痕处理中...');
        }

        // ========== 下载功能 ==========
        function downloadOutput() {
            const content = document.getElementById('outputArea').value;
            if (!content.trim()) {
                showToast('没有可下载的内容', 'warning');
                return;
            }

            const timestamp = new Date().toISOString().slice(0, 19).replace(/[:-]/g, '').replace('T', '_');
            const filename = `novel_output_${timestamp}.txt`;
            
            const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = filename;
            a.click();
            URL.revokeObjectURL(url);
            
            showToast(`已下载: ${filename}`, 'success');
        }

        // ========== 本地存储 ==========
        function saveToLocal() {
            const data = {
                apiKey: document.getElementById('jyApiKeyInput').value,
                model: document.getElementById('modelSelect').value,
                output: document.getElementById('outputArea').value,
                instruction: document.getElementById('instructionInput').value,
                docContent: docContent,
                promptFiles: promptFiles,
                timestamp: new Date().toISOString()
            };
            
            try {
                localStorage.setItem('deepseek_novel_workspace', JSON.stringify(data));
                showToast('已保存到本地存储', 'success');
            } catch (e) {
                showToast('保存失败: ' + e.message, 'error');
            }
        }

        function loadFromLocal() {
            try {
                const data = JSON.parse(localStorage.getItem('deepseek_novel_workspace'));
                if (!data) return;

                if (data.apiKey) document.getElementById('jyApiKeyInput').value = data.apiKey;
                if (data.model) document.getElementById('modelSelect').value = data.model;
                if (data.output) document.getElementById('outputArea').value = data.output;
                if (data.instruction) document.getElementById('instructionInput').value = data.instruction;
                if (data.docContent) docContent = data.docContent;
                if (data.promptFiles) {
                    Object.keys(data.promptFiles).forEach(key => {
                        if (data.promptFiles[key]) {
                            promptFiles[key] = data.promptFiles[key];
                            document.getElementById(`${key}PromptName`).textContent = '已保存的提示词';
                            document.getElementById(`${key}PromptInfo`).classList.remove('hidden');
                            document.getElementById(`${key}PromptEmpty`).classList.add('hidden');
                        }
                    });
                }

                if (docContent) {
                    document.getElementById('docFileName').textContent = '已保存的文档';
                    document.getElementById('docFileInfo').classList.remove('hidden');
                }

                updateCharCount();
            } catch (e) {
                // 静默处理加载错误
            }
        }

        // ========== 清空/重置 ==========
        function clearAll() {
            if (!confirm('确定要清空所有内容吗？此操作不可撤销。')) return;
            
            document.getElementById('outputArea').value = '';
            document.getElementById('instructionInput').value = '';
            docContent = '';
            promptFiles = { review: '', screenplay: '', polish: '', rewrite: '' };
            
            document.getElementById('docFileInput').value = '';
            document.getElementById('docFileInfo').classList.add('hidden');
            
            ['review', 'screenplay', 'polish', 'rewrite'].forEach(type => {
                document.getElementById(`${type}PromptInfo`).classList.add('hidden');
                document.getElementById(`${type}PromptEmpty`).classList.remove('hidden');
            });
            
            updateCharCount();
            localStorage.removeItem('deepseek_novel_workspace');
            showToast('已清空所有内容', 'info');
        }
    

        // 内联属性引用的函数集中导出
        window.JY = { callPolish, callScreenplay, callRewrite, callReview, clearAll, clearDocFile, clearPrompt, downloadOutput, handleDocUpload, handleDragLeave, handleDragOver, handleDrop, handlePromptUpload, loadDocToOutput, saveToLocal, stopGeneration, testConnection, toggleApiKeyVisibility, updateCharCount };

})();
            

// ===== split =====


(function(){

const $ = (id) => document.getElementById(id);
const state = { mode: "t2v", files: [], cfg: null, timer: null, watching: new Set() };

function xgToastFn(msg, kind) {
  const t = $("xgToast");
  t.textContent = msg;
  t.className = "show" + (kind ? " " + kind : "");
  clearTimeout(t._h);
  t._h = setTimeout(() => { t.className = ""; }, 3200);
}

async function api(path, opts) {
  const res = await fetch(path, opts);
  let data = null;
  try { data = await res.json(); } catch (e) { data = { ok: false, error: "响应解析失败" }; }
  return data;
}

function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, (c) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
  }[c]));
}

/* 复制文本框内容（兼容非安全上下文） */
async function copyTextarea(ta) {
  const text = ta.value || "";
  if (!text.trim()) { xgToastFn("内容为空，没有可复制的内容", "err"); return; }
  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
    } else {
      const prev = ta.selectionStart;
      ta.focus(); ta.select();
      document.execCommand("copy");
      ta.setSelectionRange(prev, prev);
    }
    xgToastFn("已复制到剪贴板", "ok");
  } catch (e) {
    xgToastFn("复制失败，请手动选择复制", "err");
  }
}

/* ---------- 初始化 ---------- */
async function loadConfig() {
  const cfg = await api("/api/xg/config");
  if (!cfg.ok) return;
  state.cfg = cfg;

  const saved = localStorage.getItem("xg_api_url");
  $("apiUrl").value = saved || cfg.api_url;
  const savedToken = localStorage.getItem("xg_token");
  if (savedToken) $("token").value = savedToken;

  $("positive").value = cfg.positive;
  $("negative").value = cfg.negative;

  const sec = Math.min(30, Math.max(5, cfg.seconds || 6));
  $("seconds").value = sec;
  $("secondsNum").value = sec;

  $("resPreset").innerHTML = cfg.res_presets.map((p, i) => {
    const sel = (p.w === cfg.width && p.h === cfg.height) ? " selected" : "";
    return '<option value="' + i + '"' + sel + ">" + esc(p.label) + "</option>";
  }).join("");
}

/* ---------- 连接 ---------- */
async function testConnect() {
  const api_url = $("apiUrl").value.trim();
  const token = $("token").value.trim();
  if (!api_url || !token) { xgToastFn("请填写地址与 Token", "err"); return; }

  $("connNote").textContent = "连接中…";
  $("connNote").className = "inline-note";
  $("btnConnect").disabled = true;

  const d = await api("/api/xg/connect", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ api_url, token }),
  });

  $("btnConnect").disabled = false;

  if (!d.ok) {
    $("connNote").textContent = d.error || "连接失败";
    $("connNote").className = "inline-note err";
    $("connBadge").textContent = "连接失败";
    $("connBadge").className = "badge bad";
    return;
  }

  const bits = ["节点 " + d.node_count, "引擎 " + d.engine];
  if (!d.i2v_supported) bits.push("（该容器不支持图生视频）");
  $("connNote").textContent = "已连接：" + bits.join(" · ");
  $("connNote").className = "inline-note ok";
  $("connBadge").textContent = "已连接";
  $("connBadge").className = "badge ok";
  $("engineBadge").textContent = d.engine;

  if (!d.i2v_supported) xgToastFn("该容器未启用图生视频节点", "err");
}

/* ---------- 模式切换 ---------- */
function setMode(mode) {
  state.mode = mode;
  document.querySelectorAll("#modeSeg button").forEach((b) => {
    b.classList.toggle("active", b.dataset.mode === mode);
  });
  $("uploadBox").style.display = mode === "i2v" ? "block" : "none";
}

/* ---------- 参考图 ---------- */
function wireUpload() {
  const dz = $("dropZone");
  const fi = $("fileInput");

  dz.addEventListener("click", () => fi.click());
  fi.addEventListener("change", () => { addFiles(fi.files); fi.value = ""; });

  ["dragenter", "dragover"].forEach((ev) =>
    dz.addEventListener(ev, (e) => { e.preventDefault(); dz.classList.add("drag"); }));
  ["dragleave", "drop"].forEach((ev) =>
    dz.addEventListener(ev, (e) => { e.preventDefault(); dz.classList.remove("drag"); }));
  dz.addEventListener("drop", (e) => {
    if (e.dataTransfer && e.dataTransfer.files) addFiles(e.dataTransfer.files);
  });

  // 时长滑杆与数字框双向同步
  $("seconds").addEventListener("input", () => { $("secondsNum").value = $("seconds").value; });
  $("secondsNum").addEventListener("input", () => {
    let v = parseInt($("secondsNum").value, 10);
    if (isNaN(v)) return;
    v = Math.min(30, Math.max(5, v));
    $("seconds").value = v;
  });
}

function addFiles(list) {
  for (const f of Array.from(list || [])) {
    if (!f.type.startsWith("image/")) { xgToastFn("已跳过非图片文件：" + f.name, "err"); continue; }
    if (state.files.length >= 2) { xgToastFn("最多上传 2 张参考图", "err"); break; }
    state.files.push(f);
  }
  renderPreviews();
}

function removeFile(i) {
  state.files.splice(i, 1);
  renderPreviews();
}

function renderPreviews() {
  const tags = ["参考图 1 · 首帧（必选）", "参考图 2 · 尾帧（可选）"];
  $("previewList").innerHTML = state.files.map((f, i) => {
    const url = URL.createObjectURL(f);
    return '<div class="pv">' +
      '<img src="' + url + '" alt="preview" />' +
      '<div class="meta">' +
        '<div class="tag">' + tags[i] + '</div>' +
        '<div class="name">' + esc(f.name) + '</div>' +
        '<div class="size">' + (f.size / 1024).toFixed(0) + ' KB</div>' +
      '</div>' +
      '<button class="ghost" data-i="' + i + '">移除</button>' +
    '</div>';
  }).join("");
  $("previewList").querySelectorAll("button").forEach((b) => {
    b.addEventListener("click", () => removeFile(parseInt(b.dataset.i, 10)));
  });
  $("dropZone").style.display = state.files.length >= 2 ? "none" : "block";
  $("dropZone").querySelector(".t1").textContent =
    state.files.length === 1 ? "还可再选 1 张尾帧图（可选）" : "点击选择参考图（最多 2 张），或把图片拖到这里";
}

/* ---------- 提交 ---------- */
async function submit() {
  const api_url = $("apiUrl").value.trim();
  const token = $("token").value.trim();
  if (!api_url || !token) { xgToastFn("请先填写地址与 Token", "err"); return; }
  if (!$("positive").value.trim()) { xgToastFn("请填写正向提示词", "err"); return; }
  if (state.mode === "i2v" && !state.files.length) { xgToastFn("图生视频需要至少上传 1 张参考图", "err"); return; }

  const presets = state.cfg.res_presets;
  const p = presets[parseInt($("resPreset").value, 10)] || presets[0];

  const fd = new FormData();
  fd.append("api_url", api_url);
  fd.append("token", token);
  fd.append("mode", state.mode);
  fd.append("positive", $("positive").value.trim());
  fd.append("negative", $("negative").value.trim());
  fd.append("seconds", $("seconds").value);
  fd.append("fps", $("fps").value || "24");
  fd.append("width", String(p.w));
  fd.append("height", String(p.h));
  fd.append("seed", $("seed").value || "");
  if (state.mode === "i2v") {
    state.files.forEach((f, i) => fd.append("image" + (i + 1), f, f.name));
  }

  $("btnSubmit").disabled = true;
  $("submitNote").textContent = "";
  $("btnSubmit").innerHTML = '<span class="spin"></span>提交中…';

  const d = await api("/api/xg/submit", { method: "POST", body: fd });

  $("btnSubmit").disabled = false;
  $("btnSubmit").textContent = "开始生成";

  if (!d.ok) {
    $("submitNote").textContent = d.error + (d.detail ? "：" + d.detail.slice(0, 220) : "");
    $("submitNote").className = "inline-note err";
    xgToastFn(d.error, "err");
    return;
  }

  $("submitNote").textContent = "已提交，prompt_id " + d.task.prompt_id.slice(0, 8) + "…（云端生成中）";
  $("submitNote").className = "inline-note ok";
  xgToastFn("任务已提交", "ok");
  loadTasks();
}

/* ---------- 任务列表 ---------- */
function viewUrl(t, o) {
  const q = new URLSearchParams({
    api_url: t.api_url, token: $("token").value.trim(),
    filename: o.filename, subfolder: o.subfolder || "", type: o.type_ || "output",
  });
  return "/api/xg/view?" + q.toString();
}

function renderTasks(tasks) {
  if (!tasks || !tasks.length) {
    $("xgTaskList").innerHTML = '<div class="empty">还没有任务。</div>';
    return;
  }
  $("xgTaskList").innerHTML = tasks.map((t) => {
    const out = (t.outputs || []).map((o) => {
      const u = viewUrl(t, o);
      if (o.type === "video") {
        return '<video src="' + esc(u) + '" controls preload="metadata"></video>';
      }
      return '<img class="out" src="' + esc(u) + '" alt="output" />';
    }).join("");

    const acts = [];
    (t.outputs || []).forEach((o) => {
      acts.push('<a href="' + esc(viewUrl(t, o)) + '" download="' + esc(o.filename) + '">下载 ' + esc(o.filename.slice(0, 18)) + '</a>');
    });

    const stName = { queued: "排队中", running: "生成中", completed: "已完成", error: "失败", unknown: "状态未知" }[t.status] || t.status;

    return '<div class="task">' +
      '<div class="top">' +
        '<span class="st ' + esc(t.status) + '">' + esc(stName) + '</span>' +
        '<span class="badge" style="font-size:11px">' + (t.mode === "i2v" ? "图生视频" : "文生视频") + '</span>' +
        '<span class="time">' + esc(t.created_at || "") + '</span>' +
      '</div>' +
      '<div class="kv">' +
        '<span>' + esc(t.width) + '×' + esc(t.height) + '</span>' +
        '<span>' + esc(t.seconds) + ' 秒</span>' +
        '<span>' + esc(t.fps) + ' fps</span>' +
        '<span>种子 ' + esc(t.seed) + '</span>' +
      '</div>' +
      (out || '') +
      (t.error ? '<div class="inline-note err">' + esc(t.error.slice(0, 200)) + '</div>' : '') +
      (acts.length ? '<div class="acts">' + acts.join("") + '</div>' : '') +
      '<div class="desc-line" style="margin-top:8px">' + esc((t.positive || "").slice(0, 220)) + '</div>' +
    '</div>';
  }).join("");
}

async function loadTasks() {
  const d = await api("/api/xg/tasks");
  if (!d.ok) return;
  renderTasks(d.tasks);

  // 自动轮询未完成任务
  const pending = d.tasks.filter((t) => t.status === "queued" || t.status === "running" || t.status === "unknown");
  state.watching = new Set(pending.map((t) => t.id));
  if (pending.length && !state.timer) startPoll();
}

function startPoll() {
  state.timer = setInterval(async () => {
    const ids = Array.from(state.watching);
    if (!ids.length) { clearInterval(state.timer); state.timer = null; return; }
    const token = $("token").value.trim();

    for (const id of ids) {
      const d = await api("/api/xg/status", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ api_url: $("apiUrl").value.trim(), token, task_id: id }),
      });
      if (d.ok && d.task && (d.task.status === "completed" || d.task.status === "error")) {
        state.watching.delete(id);
        if (d.task.status === "completed") xgToastFn("出片完成：" + (d.task.outputs[0] ? d.task.outputs[0].filename : ""), "ok");
      }
    }
    const r = await api("/api/xg/tasks");
    if (r.ok) renderTasks(r.tasks);
  }, 8000);
}

async function statusNow() {
  const token = $("token").value.trim();
  const d = await api("/api/xg/tasks");
  if (!d.ok) return;
  for (const t of d.tasks) {
    if (t.status === "completed" || t.status === "error") continue;
    await api("/api/xg/status", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ api_url: $("apiUrl").value.trim(), token, task_id: t.id }),
    });
  }
  const r = await api("/api/xg/tasks");
  if (r.ok) { renderTasks(r.tasks); xgToastFn("已刷新", "ok"); }
}

/* ---------- 绑定 ---------- */
function bind() {
  $("btnConnect").addEventListener("click", testConnect);
  $("btnSaveConn").addEventListener("click", () => {
    localStorage.setItem("xg_api_url", $("apiUrl").value.trim());
    localStorage.setItem("xg_token", $("token").value.trim());
    xgToastFn("地址与 Token 已保存到本机", "ok");
  });

  document.querySelectorAll("#modeSeg button").forEach((b) => {
    b.addEventListener("click", () => setMode(b.dataset.mode));
  });

  $("btnResetPrompt").addEventListener("click", () => {
    if (!state.cfg) return;
    $("positive").value = state.cfg.positive;
    $("negative").value = state.cfg.negative;
    xgToastFn("已恢复默认提示词", "ok");
  });

  $("btnCopyPos").addEventListener("click", () => copyTextarea($("positive")));
  $("btnClearPos").addEventListener("click", () => {
    $("positive").value = "";
    xgToastFn("正向提示词已清空");
  });
  $("btnCopyNeg").addEventListener("click", () => copyTextarea($("negative")));
  $("btnClearNeg").addEventListener("click", () => {
    $("negative").value = "";
    xgToastFn("负向提示词已清空");
  });

  $("btnSubmit").addEventListener("click", submit);
  $("btnRefresh").addEventListener("click", statusNow);
  $("btnClear").addEventListener("click", async () => {
    if (!confirm("确定清空全部任务历史？")) return;
    await api("/api/xg/tasks", { method: "DELETE" });
    loadTasks();
  });
}

(async function init() {
  bind();
  wireUpload();
  setMode("t2v");
  await loadConfig();
  await loadTasks();
})();

// 🔴 V1.8.296：api() / esc() 定义在本 IIFE 内，外部 script 块（复刻版块 / 豆包配音）
// 直接调用会 ReferenceError: api is not defined。挂到 window 上让它们全局可见。
window.api = api;
window.esc = esc;

})();
            

