const $ = id => document.getElementById(id);
function fillSelect(el, arr, selected){
  el.innerHTML = arr.map(v=>`<option${v===selected?' selected':''}>${v}</option>`).join("");
}

fillSelect($("dwera"), ERAS, "仙侠纪元");
