        let storyConfirmed = false;  // 用户已确认故事，防止轮询重新显示确认弹窗

        function importDramaStoryFile(input) {
            const file = input.files && input.files[0];
            if (!file) return;
            
            if (!/\.(txt|md)$/i.test(file.name)) {
                showToast('仅支持 .txt 或 .md 文件', 'error');
                input.value = '';
                return;
            }
            
            const reader = new FileReader();
            reader.onload = e => {
                const text = (e.target.result || '').trim();
                const area = document.getElementById('dramaStoryContent');
                
                if (area.value.trim()) {
                    if (confirm('故事框已有内容，点击「确定」替换为文件内容，点击「取消」不做任何修改')) {
                        area.value = text;
                    }
                } else {
                    area.value = text;
                }
                
                showToast(`已导入 ${file.name}（${text.length} 字符）`, 'success');
            };
            reader.readAsText(file, 'utf-8');
            input.value = '';  // 重置，允许重复选择同一文件
        }

        function importDramaScriptFile(input) {
            const file = input.files && input.files[0];
            if (!file) return;

            if (!/\.(txt|md)$/i.test(file.name)) {
                showToast('仅支持 .txt 或 .md 文件', 'error');
                input.value = '';
                return;
            }

            const reader = new FileReader();
            reader.onload = e => {
                const text = (e.target.result || '').trim();
                const area = document.getElementById('dramaScriptContent');

                if (area.value.trim()) {
                    if (confirm('剧本框已有内容，点击「确定」替换为文件内容，点击「取消」不做任何修改')) {
                        area.value = text;
                    }
                } else {
                    area.value = text;
                }

                showToast(`已导入 ${file.name}（${text.length} 字符）`, 'success');
            };
            reader.onerror = () => showToast('文件读取失败', 'error');
            reader.readAsText(file, 'utf-8');
            input.value = '';  // 重置，允许重复选择同一文件
        }

        async function regenerateDramaScript() {
            if (!currentDramaId) { showToast('请先启动短剧任务', 'error'); return; }
            const story = document.getElementById('dramaStoryContent').value.trim();
            if (!story) { showToast('故事梗概不能为空', 'error'); return; }
            if (!confirm('将根据当前故事梗概重新生成剧本，现有剧本将被覆盖，是否继续？')) return;
            try {
                const resp = await fetch('/api/drama/script/regenerate', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ drama_id: currentDramaId, story: story })
                });
                const data = await resp.json();
                if (data.success) {
                    showToast('已开始重新生成剧本，请稍候...', 'success');
                } else {
                    showToast(data.error || '重新生成剧本失败', 'error');
                }
            } catch (e) {
                showToast('请求失败: ' + e.message, 'error');
            }
        }

        let mergeSelectedShots = [];  // 已选镜头顺序 [shot_index, ...]

        function updateMergeSelection() {
            // 收集所有勾选的镜头，保持当前顺序
            const allChecks = document.querySelectorAll('[id^="shot-check-"]');
            const newSelected = [];
            // 先保留已存在的顺序
            for (const si of mergeSelectedShots) {
                const cb = document.getElementById(`shot-check-${si}`);
                if (cb && cb.checked) newSelected.push(si);
            }
            // 添加新勾选的（按镜头编号排序）
            allChecks.forEach(cb => {
                const si = parseInt(cb.id.replace('shot-check-', ''));
                if (cb.checked && !newSelected.includes(si)) {
                    newSelected.push(si);
                }
            });
            newSelected.sort((a, b) => a - b);
            mergeSelectedShots = newSelected;
            renderMergeSelectedList();
        }

        function renderMergeSelectedList() {
            const el = document.getElementById('mergeSelectedList');
            if (!el) return;
            if (mergeSelectedShots.length === 0) {
                el.innerHTML = '<span style="font-size:11px;color:var(--text2);">未选择镜头，请在下方视频中勾选</span>';
                return;
            }
            el.innerHTML = '<div style="font-size:11px;font-weight:600;margin-bottom:4px;">合并顺序 (' + mergeSelectedShots.length + ' 个镜头):</div>' +
                '<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;">' +
                mergeSelectedShots.map((si, idx) => `
                    <div style="display:flex;align-items:center;gap:2px;background:var(--surface2);border-radius:4px;padding:3px 6px;border:1px solid var(--border);">
                        <span style="font-size:11px;font-weight:600;">镜头${si}</span>
                        ${idx > 0 ? `<button onclick="moveMergeShot(${idx}, -1)" style="font-size:10px;background:none;border:none;cursor:pointer;color:var(--accent);padding:0 2px;" title="左移">◀</button>` : ''}
                        ${idx < mergeSelectedShots.length - 1 ? `<button onclick="moveMergeShot(${idx}, 1)" style="font-size:10px;background:none;border:none;cursor:pointer;color:var(--accent);padding:0 2px;" title="右移">▶</button>` : ''}
                        <button onclick="removeMergeShot(${idx})" style="font-size:10px;background:none;border:none;cursor:pointer;color:var(--error);padding:0 2px;" title="移除">✕</button>
                    </div>
                    ${idx < mergeSelectedShots.length - 1 ? '<span style="color:var(--text2);font-size:10px;">→</span>' : ''}
                `).join('') +
                '</div>';
        }

        function moveMergeShot(idx, direction) {
            const newIdx = idx + direction;
            if (newIdx < 0 || newIdx >= mergeSelectedShots.length) return;
            [mergeSelectedShots[idx], mergeSelectedShots[newIdx]] = [mergeSelectedShots[newIdx], mergeSelectedShots[idx]];
            renderMergeSelectedList();
        }

        function removeMergeShot(idx) {
            const si = mergeSelectedShots[idx];
            mergeSelectedShots.splice(idx, 1);
            const cb = document.getElementById(`shot-check-${si}`);
            if (cb) cb.checked = false;
            renderMergeSelectedList();
        }

        async function replaceAssetImage(assetIndex, input) {
                    const file = input.files[0];
                    if (!file || !currentDramaId) return;
        
                    const formData = new FormData();
                    formData.append('drama_id', currentDramaId);
                    formData.append('asset_index', assetIndex);
                    formData.append('file', file);
        
                    try {
                        const resp = await fetch('/api/drama/asset/replace', { method: 'POST', body: formData });
                        const data = await resp.json();
                        if (data.success) {
                            // 更新图片显示
                            const imgEl = document.getElementById(`asset-img-${assetIndex}`);
                            if (imgEl) {
                                if (imgEl.tagName === 'IMG') {
                                    imgEl.src = data.image_url + '?t=' + Date.now();
                                } else {
                                    const newImg = document.createElement('img');
                                    newImg.src = data.image_url;
                                    newImg.id = `asset-img-${assetIndex}`;
                                    newImg.style.cssText = 'width:100%;height:160px;object-fit:cover;';
                                    imgEl.replaceWith(newImg);
                                }
                            }
                            showToast('参考图替换成功', 'success');
                        } else {
                            showToast('替换失败: ' + (data.error || '未知错误'), 'error');
                        }
                    } catch (e) {
                        showToast('替换失败: ' + e.message, 'error');
                    }
                    input.value = '';
                }

        async function regenerateAssetImage(assetIndex) {
            if (!currentDramaId) return;
            const btn = document.getElementById(`asset-retry-${assetIndex}`);
            if (btn) { btn.disabled = true; btn.textContent = '生成中...'; }

            try {
                const resp = await fetch('/api/drama/asset/regenerate', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ drama_id: currentDramaId, asset_index: assetIndex })
                });
                const data = await resp.json();
                if (data.success) {
                    const imgEl = document.getElementById(`asset-img-${assetIndex}`);
                    if (imgEl) {
                        const newImg = document.createElement('img');
                        newImg.src = data.image_url;
                        newImg.id = `asset-img-${assetIndex}`;
                        newImg.style.cssText = 'width:100%;height:160px;object-fit:cover;';
                        imgEl.replaceWith(newImg);
                    }
                    if (btn) btn.style.display = 'none';
                    // 更新提示词显示
                    if (data.img_prompt) {
                        const ta = document.getElementById(`asset-prompt-${assetIndex}`);
                        if (ta) ta.value = data.img_prompt;
                    }
                    showToast('参考图重新生成成功', 'success');
                } else {
                    showToast('重新生成失败: ' + (data.error || ''), 'error');
                    if (btn) { btn.disabled = false; btn.textContent = '重新生成'; }
                }
            } catch (e) {
                showToast('重新生成失败: ' + e.message, 'error');
                if (btn) { btn.disabled = false; btn.textContent = '重新生成'; }
            }
        }

