        async function regenerateShotVideo(shotIndex) {
            if (!currentDramaId) return;
            const btn = document.getElementById(`shot-regen-${shotIndex}`) || document.getElementById(`shot-retry-${shotIndex}`);
            if (btn) { btn.disabled = true; btn.textContent = '提交中...'; }

            try {
                const resp = await fetch('/api/drama/shot/regenerate', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ drama_id: currentDramaId, shot_index: shotIndex })
                });
                const data = await resp.json();
                if (data.success) {
                    showToast(`镜头 ${shotIndex} 开始重新生成`, 'success');
                    if (btn) btn.textContent = '生成中...';
                    // 启动临时轮询更新该镜头状态
                    const pollTimer = setInterval(async () => {
                        try {
                            const pollResp = await fetch(`/api/drama/status/${currentDramaId}`);
                            const pollData = await pollResp.json();
                            if (pollData.video_results) {
                                const shotResult = pollData.video_results.find(v => v.shot_index === shotIndex);
                                if (shotResult && shotResult.status === 'completed') {
                                    clearInterval(pollTimer);
                                    showToast(`镜头 ${shotIndex} 重新生成完成`, 'success');
                                    pollDramaStatus();
                                } else if (shotResult && shotResult.status === 'failed') {
                                    clearInterval(pollTimer);
                                    showToast(`镜头 ${shotIndex} 重新生成失败`, 'error');
                                    pollDramaStatus();
                                }
                            }
                        } catch (e) { console.error(e); }
                    }, 10000);
                } else {
                    showToast('重新生成失败: ' + (data.error || ''), 'error');
                    if (btn) { btn.disabled = false; btn.textContent = '🔄 重新生成'; }
                }
            } catch (e) {
                showToast('重新生成失败: ' + e.message, 'error');
                if (btn) { btn.disabled = false; btn.textContent = '🔄 重新生成'; }
            }
        }

