        async function pollDramaStatus() {
            if (!currentDramaId) return;
            try {
                const resp = await fetch(`/api/drama/status/${currentDramaId}`);
                const data = await resp.json();
                if (!data.success) return;

                // 防重渲染：计算当前数据哈希，如果与上次相同则跳过 DOM 更新
                const hashParts = [
                    data.status,
                    data.message || '',
                    data.story ? data.story.substring(0, 100) : '',
                    data.script ? (typeof data.script === 'string' ? data.script.substring(0, 100) : JSON.stringify(data.script).substring(0, 100)) : '',
                    JSON.stringify(data.storyboard || {}).substring(0, 200),
                    JSON.stringify(data.assets || []).substring(0, 200),
                    JSON.stringify(data.video_results || []).substring(0, 300),
                    data.merged_video || ''
                ];
                const currentHash = hashParts.join('|');
                if (currentHash === _lastDramaRenderHash) {
                    // 数据未变化，只更新进度条和步骤标签
                    const stepMap = { 'step1': 15, 'paused_story': 18, 'step2': 35, 'step3': 55, 'paused': 60, 'paused_video': 65, 'step4': 75, 'completed': 100, 'failed': 100, 'stopped': 100 };
                    const progress = stepMap[data.status] || 5;
                    document.getElementById('dramaProgressBar').style.width = progress + '%';
                    if (data.status === 'failed') document.getElementById('dramaProgressBar').style.background = 'var(--error)';
                    if (data.status === 'completed') document.getElementById('dramaProgressBar').style.background = 'var(--success)';
                    if (data.status === 'stopped') document.getElementById('dramaProgressBar').style.background = 'var(--text2)';
                    const stepLabels = {
                        'pending': '等待中', 'step1': '① 生成故事+剧本...', 'paused_story': '⏸ 请确认故事梗概', 'step2': '② 生成分镜...',
                        'step3': '③ 提取素材...', 'paused': '⏸ 请确认参考图', 'paused_video': '⏸ 请逐个启动视频生成', 'step4': '④ 生成视频...', 'completed': '✅ 完成', 'failed': '❌ 失败', 'stopped': '⏹ 已停止'
                    };
                    document.getElementById('dramaStepBadge').textContent = stepLabels[data.status] || data.status;
                    document.getElementById('dramaMessage').textContent = data.message || '';
                    // 完成或失败时停止轮询
                    if (data.status === 'completed' || data.status === 'failed') {
                        clearInterval(dramaPollingTimer);
                        localStorage.removeItem('currentDramaId');
                        showToast(data.status === 'completed' ? '短剧生成完成！' : '短剧生成失败', data.status === 'completed' ? 'success' : 'error');
                    }
                    return;
                }
                _lastDramaRenderHash = currentHash;

                // 防编辑中断：如果用户正在编辑任何 textarea 或 input，跳过本次 DOM 重渲染
                const activeEl = document.activeElement;
                if (activeEl && (activeEl.tagName === 'TEXTAREA' || activeEl.tagName === 'INPUT')) {
                    return;
                }

                // 更新进度条
                const stepMap = { 'step1': 15, 'paused_story': 18, 'step2': 35, 'step3': 55, 'paused': 60, 'paused_video': 65, 'step4': 75, 'completed': 100, 'failed': 100, 'stopped': 100 };
                const progress = stepMap[data.status] || 5;
                document.getElementById('dramaProgressBar').style.width = progress + '%';
                if (data.status === 'failed') document.getElementById('dramaProgressBar').style.background = 'var(--error)';
                if (data.status === 'completed') document.getElementById('dramaProgressBar').style.background = 'var(--success)';
                if (data.status === 'stopped') document.getElementById('dramaProgressBar').style.background = 'var(--text2)';

                // 完成/失败/停止时隐藏停止按钮
                if (['completed', 'failed', 'stopped'].includes(data.status)) {
                    document.getElementById('btnStopDrama').style.display = 'none';
                }

                // 显示故事确认按钮
                if (data.status === 'paused_story' && !storyConfirmed) {
                    document.getElementById('dramaStoryConfirmSection').style.display = 'block';
                    document.getElementById('dramaStoryDirectBtn').disabled = false;
                } else {
                    document.getElementById('dramaStoryConfirmSection').style.display = 'none';
                }

                // 显示确认按钮
                if (data.status === 'paused') {
                    document.getElementById('dramaResumeSection').style.display = 'block';
                } else {
                    document.getElementById('dramaResumeSection').style.display = 'none';
                }

                // 显示视频区域（包含每个镜头的独立生成按钮）
                if (data.status === 'paused_video') {
                    document.getElementById('dramaVideosSection').style.display = 'block';
                }

                // 更新步骤标签
                const stepLabels = {
                    'pending': '等待中', 'step1': '① 生成故事+剧本...', 'paused_story': '⏸ 请确认故事梗概', 'step2': '② 生成分镜...',
                    'step3': '③ 提取素材...', 'paused': '⏸ 请确认参考图', 'paused_video': '⏸ 请逐个启动视频生成', 'step4': '④ 生成视频...', 'completed': '✅ 完成', 'failed': '❌ 失败', 'stopped': '⏹ 已停止'
                };
                document.getElementById('dramaStepBadge').textContent = stepLabels[data.status] || data.status;
                document.getElementById('dramaMessage').textContent = data.message || '';

                // 显示故事
                if (data.story) {
                    document.getElementById('dramaStorySection').style.display = 'block';
                    const storyArea = document.getElementById('dramaStoryContent');
                    // 仅在服务端故事与本地不同时更新，保护用户正在编辑/已修改的内容
                    if (storyArea.value !== data.story && document.activeElement !== storyArea) {
                        storyArea.value = data.story;
                    }
                }

                // 显示剧本（现在是纯文本格式，可编辑）
                if (data.script) {
                    document.getElementById('dramaScriptSection').style.display = 'block';
                    const scriptText = typeof data.script === 'string' ? data.script : JSON.stringify(data.script, null, 2);
                    const scriptArea = document.getElementById('dramaScriptContent');
                    // 仅在服务端剧本与本地不同时更新，保护用户正在编辑/已修改的内容
                    if (scriptArea.value !== scriptText && document.activeElement !== scriptArea) {
                        scriptArea.value = scriptText;
                    }
                }

                // 显示分镜
                if (data.storyboard && data.storyboard.shots) {
                    document.getElementById('dramaStoryboardSection').style.display = 'block';
                    const el = document.getElementById('dramaStoryboardContent');
                    el.innerHTML = data.storyboard.shots.map(s => `
                        <div style="padding:10px;background:var(--bg);border-radius:var(--radius-sm);border:1px solid var(--border);">
                            <div style="font-weight:600;font-size:13px;">镜头 ${s.shot_index} <span style="color:var(--text2);font-weight:400;">[${s.camera || ''}]</span></div>
                            <div style="font-size:12px;color:var(--text2);margin-top:4px;">${s.scene_desc || ''}</div>
                            <div style="font-size:11px;color:var(--accent);margin-top:4px;font-family:'Source Han Sans SC',monospace;">${(s.prompt_en || '').substring(0, 120)}...</div>
                        </div>
                    `).join('');
                }

                // 显示素材三视图（按类型分组到各自显示窗口）
                if (data.assets && data.assets.length > 0) {
                    document.getElementById('dramaAssetsSection').style.display = 'block';
                    const el = document.getElementById('dramaAssetsContent');
                    const isGenerating = data.status === 'step3'; // Step 3 还在生成中
                    // 单个素材卡片渲染（idx 为原始数组索引，供替换/重试/重新生成使用）
                    const renderAssetCard = (a, idx) => {
                        const imgSrc = a.local_file ? `/dramas/${currentDramaId}/images/${a.local_file}` : (a.image_url || '');
                        const hasImage = !!imgSrc;
                        // 显示中文描述
                        const imgPrompt = (a.desc || a.img_prompt || '').replace(/"/g, '&quot;');
                        // 判定是否"真正还在生成中"：必须全局仍在 step3/pending，
                        // 且**该素材**本就没有图（已完成的素材会带 image_url，绝不会卡在生成中）
                        const statusKey = data.status || '';
                        const isStillRunning = ['step3', 'pending', 'running'].includes(statusKey);
                        const isGenerating = isStillRunning && !hasImage;
                        // 只有在流水线已结束（paused/failed/completed/stopped）且无图片时才显示失败
                        const isFailed = !hasImage && !isStillRunning;
                        const retryBtn = isFailed ? `<button style="font-size:11px;color:var(--on-accent);background:var(--error);border:none;border-radius:4px;padding:2px 8px;cursor:pointer;" onclick="regenerateAssetImage(${idx})" id="asset-retry-${idx}">重新生成</button>` : '';
                        let imgHtml;
                        if (hasImage) {
                            // onerror 兜底：图片 404/跨域/链接失效时直接显示失败占位，避免空白
                            imgHtml = `<img src="${imgSrc}" alt="${a.name}（点击放大查看）" title="点击放大查看原图" style="width:100%;height:160px;object-fit:contain;background:#fff;cursor:zoom-in;" onclick="openDramaImageViewer(this)" id="asset-img-${idx}" onerror="(function(el){const d=document.createElement('div');d.id='asset-img-${idx}';d.style.cssText='height:160px;display:flex;align-items:center;justify-content:center;color:var(--error);font-size:12px;';d.textContent='❌ 图片加载失败';el.replaceWith(d);})(this)">`;
                        } else if (isGenerating) {
                            imgHtml = `<div style="height:160px;display:flex;align-items:center;justify-content:center;color:var(--text2);font-size:12px;" id="asset-img-${idx}"><span class="loading-spinner" style="margin-right:6px;"></span>生成中...</div>`;
                        } else {
                            imgHtml = `<div style="height:160px;display:flex;align-items:center;justify-content:center;color:var(--error);font-size:12px;" id="asset-img-${idx}">❌ 生成失败</div>`;
                        }
                        return `
                            <div style="background:var(--bg);border-radius:var(--radius-sm);border:1px solid var(--border);overflow:hidden;position:relative;" id="asset-card-${idx}">
                                ${imgHtml}
                                <div style="padding:8px;">
                                    <div style="font-size:12px;font-weight:600;display:flex;justify-content:space-between;align-items:center;">
                                        <span>${a.name}</span>
                                        <div style="display:flex;gap:4px;">
                                            ${retryBtn}
                                            <label style="cursor:pointer;font-size:11px;color:var(--accent);font-weight:400;padding:2px 6px;border:1px solid var(--accent);border-radius:4px;" onclick="document.getElementById('asset-file-${idx}').click()">替换</label>
                                            <input type="file" id="asset-file-${idx}" accept="image/*" style="display:none;" onchange="replaceAssetImage(${idx}, this)">
                                        </div>
                                    </div>
                                    <div style="margin-top:6px;">
                                        <div style="font-size:11px;font-weight:600;margin-bottom:3px;">📝 角色描述（可编辑后重新生成）</div>
                                        <textarea id="asset-prompt-${idx}" style="width:100%;min-height:80px;height:auto;font-size:13px;font-family:'Source Han Sans SC',monospace;background:var(--surface2);color:var(--text);border:1px solid var(--border);border-radius:4px;padding:6px;resize:vertical;line-height:1.4;overflow:hidden;" oninput="this.style.height='auto';this.style.height=this.scrollHeight+'px'">${imgPrompt}</textarea>
                                        <button onclick="regenerateWithPrompt(${idx})" style="font-size:12px;color:var(--on-accent);background:var(--accent);border:none;border-radius:4px;padding:3px 10px;cursor:pointer;margin-top:4px;">✏️ 修改并重新生成</button>
                                    </div>
                                </div>
                            </div>
                        `;
                    };
                    // 按类型分组（保留原始索引）
                    const catOrder = ['characters', 'scenes', 'props'];
                    const catLabels = { characters: '👤 角色', scenes: '🏞 场景', props: '📦 道具', other: '🔖 其他' };
                    const groups = {};
                    data.assets.forEach((a, idx) => {
                        const cat = catOrder.includes(a.category) ? a.category : 'other';
                        if (!groups[cat]) groups[cat] = [];
                        groups[cat].push({ a, idx });
                    });
                    const orderedCats = [
                        ...catOrder.filter(c => groups[c]),
                        ...Object.keys(groups).filter(c => !catOrder.includes(c))
                    ];
                    el.innerHTML = orderedCats.map(cat => `
                        <div style="background:var(--surface);border:1px solid var(--border);border-radius:var(--radius-sm);padding:12px;" id="asset-group-${cat}">
                            <div style="font-size:13px;font-weight:600;margin-bottom:10px;color:var(--accent);">${catLabels[cat] || cat}
                                <span style="font-size:11px;color:var(--text2);font-weight:400;margin-left:6px;">共 ${groups[cat].length} 项</span>
                            </div>
                            <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;">
                                ${groups[cat].map(({ a, idx }) => renderAssetCard(a, idx)).join('')}
                            </div>
                        </div>
                    `).join('');
                    // 自动撑高提示词 textarea
                    el.querySelectorAll('textarea[id^="asset-prompt-"]').forEach(ta => {
                        ta.style.height = 'auto';
                        ta.style.height = ta.scrollHeight + 'px';
                    });
                }

                // 显示视频
                if (data.video_results && data.video_results.length > 0) {
                    document.getElementById('dramaVideosSection').style.display = 'block';
                    const el = document.getElementById('dramaVideosContent');

                    // 保存提示词编辑状态（防止轮询重渲染导致内容丢失）
                    const savedShotPromptValues = {};
                    data.video_results.forEach(v => {
                        const si = v.shot_index;
                        const ta = document.getElementById(`shot-prompt-${si}`);
                        if (ta) savedShotPromptValues[si] = ta.value;
                    });
                    
                    // 合并后的完整视频
                    let mergedHtml = '';
                    if (data.merged_video) {
                        const mergedSrc = `/dramas/${currentDramaId}/videos/${data.merged_video}`;
                        mergedHtml = `
                            <div style="background:linear-gradient(135deg, var(--accent) 0%, #6c5ce7 100%);border-radius:var(--radius-sm);padding:16px;margin-bottom:12px;">
                                <div style="font-size:14px;font-weight:700;color:var(--on-accent);margin-bottom:10px;">🎬 完整视频（已合并）</div>
                                <video src="${mergedSrc}" style="width:100%;max-width:600px;border-radius:var(--radius-sm);" controls></video>
                            </div>
                        `;
                    } else if (data.status === 'merging') {
                        mergedHtml = `
                            <div style="background:var(--surface2);border-radius:var(--radius-sm);padding:16px;margin-bottom:12px;border:1px dashed var(--accent);">
                                <div style="font-size:14px;font-weight:600;color:var(--accent);">🎬 正在拼接完整视频... <span class="loading-spinner" style="margin-left:6px;"></span></div>
                            </div>
                        `;
                    }
                    
                    // 分镜视频列表
                    const shotDetails = data.shot_details || {};
                    const shotsHtml = data.video_results.map(v => {
                        const si = v.shot_index;
                        const videoSrc = v.local_file ? `/dramas/${currentDramaId}/videos/${v.local_file}` : (v.video_url || '');
                        const detail = shotDetails[si] || {};
                        const videoPrompt = detail.video_prompt_cn || detail.video_prompt || v.prompt || '';
                        const refImages = detail.reference_images || [];
                        
                        // 参考图缩略图
                        const refImgsHtml = refImages.length > 0 ? refImages.map((img, imgIdx) => {
                            const imgSrc = img.local_file ? `/dramas/${currentDramaId}/images/${img.local_file}` : (img.image_url || '');
                            const catLabel = { characters: '角色', scenes: '场景', props: '道具', custom: '自定义' }[img.category] || '';
                            return `<div style="position:relative;display:inline-block;width:56px;height:56px;" title="${img.asset_name || ''} [${catLabel}]">
                                <img src="${imgSrc}" style="width:56px;height:56px;object-fit:cover;border-radius:4px;border:1px solid var(--border);">
                                <div style="position:absolute;bottom:0;left:0;right:0;background:rgba(0,0,0,0.6);color:var(--on-accent);font-size:8px;text-align:center;border-radius:0 0 4px 4px;padding:1px;">${(img.asset_name || '').substring(0, 6)}</div>
                                <button onclick="deleteShotRefImage(${si}, ${imgIdx})" style="position:absolute;top:-4px;right:-4px;width:16px;height:16px;border-radius:50%;background:var(--error);color:var(--on-accent);border:none;cursor:pointer;font-size:10px;line-height:1;padding:0;display:flex;align-items:center;justify-content:center;" title="删除此参考图">✕</button>
                            </div>`;
                        }).join('') : '';
                        
                        // 右侧信息面板
                        const infoPanel = `
                            <div style="flex:1;min-width:200px;display:flex;flex-direction:column;gap:6px;">
                                ${refImages.length > 0 ? `<div>
                                    <div style="font-size:10px;font-weight:600;margin-bottom:3px;">参考图 (${refImages.length})</div>
                                    <div style="display:flex;flex-wrap:wrap;gap:3px;align-items:center;">
                                        ${refImgsHtml}
                                        <label style="display:inline-flex;align-items:center;justify-content:center;width:56px;height:56px;border:1px dashed var(--border);border-radius:4px;cursor:pointer;color:var(--text2);font-size:16px;" title="上传参考图">
                                            +<input type="file" accept="image/*" style="display:none;" onchange="uploadShotRefImage(${si}, this)">
                                        </label>
                                    </div>
                                </div>` : `<div style="display:flex;align-items:center;gap:6px;">
                                    <label style="display:inline-flex;align-items:center;justify-content:center;width:56px;height:56px;border:1px dashed var(--border);border-radius:4px;cursor:pointer;color:var(--text2);font-size:16px;" title="上传参考图">
                                        +<input type="file" accept="image/*" style="display:none;" onchange="uploadShotRefImage(${si}, this)">
                                    </label>
                                    <span style="font-size:10px;color:var(--text2);">无参考图，可点击+上传</span>
                                </div>`}
                                <div>
                                    <div style="font-size:11px;font-weight:600;margin-bottom:3px;">📝 视频提示词</div>
                                    <div id="shot-prompt-area-${si}">
                                        <textarea id="shot-prompt-${si}" style="width:100%;height:100px;font-size:13px;font-family:'Source Han Sans SC',monospace;background:var(--surface2);color:var(--text);border:1px solid var(--border);border-radius:4px;padding:6px;resize:vertical;line-height:1.5;">${videoPrompt}</textarea>
                                        <button style="font-size:12px;color:var(--on-accent);background:var(--accent);border:none;border-radius:4px;padding:4px 12px;cursor:pointer;margin-top:4px;" onclick="regenerateShotWithPrompt(${si})">✏️ 用修改后的提示词重新生成</button>
                                    </div>
                                </div>
                            </div>
                        `;
                        
                        if (v.status === 'completed' && videoSrc) {
                            return `
                                <div style="background:var(--bg);border-radius:var(--radius-sm);border:1px solid var(--border);padding:12px;" id="shot-card-${si}">
                                    <div style="font-size:13px;font-weight:600;margin-bottom:8px;">
                                        <label style="cursor:pointer;margin-right:6px;" title="勾选加入合并列表">
                                            <input type="checkbox" id="shot-check-${si}" onchange="updateMergeSelection()" style="cursor:pointer;width:15px;height:15px;vertical-align:middle;"> 
                                        </label>
                                        镜头 ${si} <span style="color:var(--success);font-size:11px;">✓ 完成</span>
                                        <button style="float:right;font-size:11px;color:var(--on-accent);background:var(--accent);border:none;border-radius:4px;padding:2px 10px;cursor:pointer;" onclick="regenerateShotVideo(${si})" id="shot-regen-${si}">🔄 重新生成</button>
                                    </div>
                                    <div style="display:flex;gap:12px;flex-wrap:wrap;">
                                        <div style="flex-shrink:0;"><video src="${videoSrc}" style="width:100%;max-width:360px;border-radius:var(--radius-sm);" controls></video></div>
                                        ${infoPanel}
                                    </div>
                                </div>
                            `;
                        } else if (v.status === 'failed') {
                            return `
                                <div style="background:var(--bg);border-radius:var(--radius-sm);border:1px solid var(--border);padding:12px;" id="shot-result-${si}">
                                    <div style="font-size:13px;font-weight:600;margin-bottom:4px;">镜头 ${si} <span style="color:var(--error);font-size:11px;">✗ 失败</span>
                                        <button style="float:right;font-size:11px;color:var(--on-accent);background:var(--error);border:none;border-radius:4px;padding:2px 10px;cursor:pointer;" onclick="regenerateShotVideo(${si})" id="shot-retry-${si}">🔄 重新生成</button>
                                    </div>
                                    <div style="font-size:11px;color:var(--error);margin-bottom:8px;">${v.error || ''}</div>
                                    <div style="display:flex;gap:12px;flex-wrap:wrap;">
                                        ${infoPanel}
                                    </div>
                                </div>
                            `;
                        } else if (v.status === 'generating') {
                            return `
                                <div style="background:var(--bg);border-radius:var(--radius-sm);border:1px solid var(--border);padding:12px;" id="shot-card-${si}">
                                    <div style="font-size:13px;font-weight:600;margin-bottom:8px;">镜头 ${si} <span style="color:var(--accent);font-size:11px;">⟳ 视频生成中...</span></div>
                                    <div style="display:flex;gap:12px;flex-wrap:wrap;margin-top:8px;">
                                        <div style="flex-shrink:0;"><div style="width:100%;max-width:360px;height:200px;display:flex;align-items:center;justify-content:center;background:var(--surface2);border-radius:var(--radius-sm);"><span class="loading-spinner" style="margin-right:8px;"></span><span style="color:var(--text2);font-size:13px;">正在生成视频，请耐心等待...</span></div></div>
                                        ${infoPanel}
                                    </div>
                                </div>
                            `;
                        } else if (v.status === 'pending') {
                            return `
                                <div style="background:var(--bg);border-radius:var(--radius-sm);border:1px solid var(--border);padding:12px;" id="shot-card-${si}">
                                    <div style="font-size:13px;font-weight:600;margin-bottom:8px;">镜头 ${si} <span style="color:var(--text2);font-size:11px;">⏳ 待生成</span>
                                        <button style="float:right;font-size:12px;color:var(--on-accent);background:var(--success);border:none;border-radius:4px;padding:4px 14px;cursor:pointer;font-weight:600;" onclick="startShotVideo(${si})" id="shot-start-${si}">▶ 生成视频</button>
                                    </div>
                                    <div style="display:flex;gap:12px;flex-wrap:wrap;">
                                        ${infoPanel}
                                    </div>
                                </div>
                            `;
                        } else {
                            return `
                                <div style="background:var(--bg);border-radius:var(--radius-sm);border:1px solid var(--border);padding:12px;">
                                    <div style="font-size:13px;">镜头 ${si} <span class="loading-spinner" style="margin-left:6px;"></span></div>
                                </div>
                            `;
                        }
                    }).join('');
                    
                    el.innerHTML = shotsHtml + mergedHtml;

                    // 恢复提示词编辑状态
                    Object.keys(savedShotPromptValues).forEach(si => {
                        const ta = document.getElementById(`shot-prompt-${si}`);
                        if (ta) ta.value = savedShotPromptValues[si];
                    });

                    // 显示自定义合并面板（有完成的视频时）
                    const hasCompleted = data.video_results.some(v => v.status === 'completed' && v.local_file);
                    if (hasCompleted) {
                        document.getElementById('dramaCustomMergeSection').style.display = 'block';
                    }
                    // 显示自定义合并结果
                    if (data.custom_merges && data.custom_merges.length > 0) {
                        const resultsEl = document.getElementById('customMergeResults');
                        resultsEl.innerHTML = data.custom_merges.map(m => {
                            const videoSrc = `/dramas/${currentDramaId}/videos/${m.merged_file}`;
                            return `<div style="background:var(--bg);border-radius:var(--radius-sm);padding:10px;margin-top:8px;border:1px solid var(--border);">
                                <div style="font-size:12px;font-weight:600;margin-bottom:6px;">🎬 ${m.name} (镜头: ${m.shot_indices.join(' → ')})</div>
                                <video src="${videoSrc}" style="width:100%;max-width:500px;border-radius:var(--radius-sm);" controls></video>
                                <a href="${videoSrc}" download style="font-size:11px;color:var(--accent);margin-top:4px;display:inline-block;">⬇️ 下载</a>
                            </div>`;
                        }).join('');
                    }
                }

                // 完成或失败时停止轮询
                if (data.status === 'completed' || data.status === 'failed') {
                    clearInterval(dramaPollingTimer);
                    localStorage.removeItem('currentDramaId');
                    showToast(data.status === 'completed' ? '短剧生成完成！' : '短剧生成失败', data.status === 'completed' ? 'success' : 'error');
                }
            } catch (e) {
                console.error('Drama poll error:', e);
            }
        }
        let anchorPollingTimer = null;
        let currentAnchorTaskId = null;
        let anchorModelsLoaded = false;

        async function loadAnchorModels() {
            if (anchorModelsLoaded) return;
            try {
                const resp = await fetch('/api/anchor/models');
                const data = await resp.json();
                if (!data.success) return;

                fillModelSelect('anchorTextModel', data.text_models, data.defaults.text_model);
                fillModelSelect('anchorImageModel', data.image_models, data.defaults.image_model);
                fillModelSelect('anchorVideoModel', data.video_models, data.defaults.video_model);
                anchorModelsLoaded = true;
            } catch (e) {
                console.error('Failed to load anchor models:', e);
            }
        }

        // 已禁用自动恢复：用户偏好"刷新=干净"，不再在数字人 tab 打开/刷新时复活服务端最近一次任务。
        // 历史任务和正在跑的任务请到「任务列表」tab 查看（那边是后端内存的真实数据，不会被本策略影响）。
        async function restoreLastAnchorTask() {
            return;
        }

        function switchAnchorMode(mode) {
            // 四列版面：点击媒体列即选中该画面模式，点亮对应列（面板常驻，不再显隐）
            const radio = document.querySelector(`input[name="anchorMode"][value="${mode}"]`);
            if (radio) radio.checked = true;
            ['A', 'B', 'C'].forEach(m => {
                const col = document.getElementById(`anchorCol${m}`);
                if (col) col.style.borderColor = m === mode ? 'var(--accent)' : 'var(--border)';
            });
            // 声音来源：模式 A/C 可选，模式 B 恒用视频原声（不显示）
            const audioSourceGroup = document.getElementById('anchorAudioSourceGroup');
            if (audioSourceGroup) audioSourceGroup.style.display = (mode === 'A' || mode === 'C') ? 'block' : 'none';
        }

        let anchorLibPickImage = '';   // 从素材库选中的形象图（已转入 anchor/ 目录的服务端文件名）
        let anchorLibPickVideo = '';   // 从素材库选中的视频素材
        let anchorLibAbort = {};       // 列浏览状态（防止重复渲染闪烁）

        function anchorPreviewLocalImage(input) {
            const box = document.getElementById('anchorAvatarPreview');
            if (!input.files.length || !box) return;
            anchorLibPickImage = '';
            const url = URL.createObjectURL(input.files[0]);
            box.innerHTML = `<img src="${url}" style="max-width:100%;max-height:180px;object-fit:contain;">`;
            box.style.color = '';
            switchAnchorMode('A');
        }

        function anchorPreviewLocalVideo(input) {
            const box = document.getElementById('anchorVideoPreview');
            if (!input.files.length || !box) return;
            anchorLibPickVideo = '';
            const url = URL.createObjectURL(input.files[0]);
            box.innerHTML = `<video src="${url}" controls style="max-width:100%;max-height:180px;"></video>`;
            box.style.color = '';
            switchAnchorMode('B');
        }

        async function anchorBrowseLib(kind, col) {
            // col: A=形象图 / B=视频 / C=AI 历史图。加载素材库到对应预览窗口
            const boxId = col === 'B' ? 'anchorVideoPreview' : (col === 'A' ? 'anchorAvatarPreview' : 'anchorAiPreview');
            const box = document.getElementById(boxId);
            if (!box) return;
            if (anchorLibAbort[col]) return;
            anchorLibAbort[col] = true;
            box.innerHTML = '⏳ 正在加载素材…';
            try {
                const resp = await fetch('/api/files/' + kind);
                const d = await resp.json();
                const files = (d.files || []).slice(0, 24);
                if (!files.length) {
                    box.innerHTML = '<span style="color:var(--text2);font-size:12px;">素材库还是空的，先去生成或上传一些</span>';
                    return;
                }
                box.innerHTML = '';
                if (col === 'C') box.style.justifyContent = 'flex-start';
                files.forEach(f => {
                    const thumb = document.createElement('img');
                    thumb.src = f.url;
                    thumb.title = f.filename + '（' + f.size_display + '）';
                    thumb.style.cssText = 'width:56px;height:56px;object-fit:cover;border-radius:4px;border:2px solid transparent;cursor:pointer;';
                    thumb.onclick = (e) => { e.stopPropagation(); anchorPickLib(f, kind, col, box); };
                    box.appendChild(thumb);
                });
                if (col !== 'C') {
                    const tip = document.createElement('div');
                    tip.style.cssText = 'width:100%;font-size:11px;color:var(--text2);text-align:center;padding:2px 0;';
                    tip.textContent = '点击缩略图选用该素材';
                    box.appendChild(tip);
                }
            } catch (e) {
                box.innerHTML = '<span style="color:var(--err-fg);font-size:12px;">素材库加载失败: ' + escPro(e.message) + '</span>';
            } finally {
                anchorLibAbort[col] = false;
            }
        }

        async function anchorPickLib(file, kind, col, box) {
            // 选用素材库文件：取回 blob → 走 /api/anchor/upload 转存进 anchor/ 目录（复用现有生成管线）
            showToast('正在选用素材 ' + file.filename + ' …', 'info');
            try {
                const blob = await (await fetch(file.url)).blob();
                const fd = new FormData();
                const ext = (file.filename.match(/\.\w+$/) || ['.png'])[0];
                fd.append('file', blob, 'lib_pick_' + Date.now() + ext);
                fd.append('kind', kind === 'videos' ? 'video' : 'image');
                const d = await (await fetch('/api/anchor/upload', { method: 'POST', body: fd })).json();
                if (!d.success) { showToast('选用失败: ' + (d.error || '未知'), 'error'); return; }
                const nameHtml = `<div style="width:100%;font-size:11px;color:var(--text2);text-align:center;">✅ 已选用素材库：${escPro(file.filename)}</div>`;
                if (col === 'A') {
                    anchorLibPickImage = d.filename;
                    box.innerHTML = `<img src="${file.url}" style="max-width:100%;max-height:180px;object-fit:contain;">` + nameHtml;
                    switchAnchorMode('A');
                } else if (col === 'B') {
                    anchorLibPickVideo = d.filename;
                    box.innerHTML = `<video src="${file.url}" controls style="max-width:100%;max-height:180px;"></video>` + nameHtml;
                    switchAnchorMode('B');
                } else {
                    // C 模式：仅预览大图找灵感，不改变提示词
                    box.innerHTML = `<img src="${file.url}" style="max-width:100%;max-height:200px;object-fit:contain;">` + nameHtml;
                }
                showToast('已选用：' + file.filename, 'success');
            } catch (e) {
                showToast('选用异常: ' + e.message, 'error');
            }
        }

        async function anchorImportScript(input) {
            const f = input.files[0];
            if (!f) return;
            const info = document.getElementById('anchorScriptFileInfo');
            if (info) info.textContent = '⏳ 正在解析 ' + f.name + ' …';
            try {
                const fd = new FormData();
                fd.append('file', f);
                const d = await (await fetch('/api/anchor/import_script', { method: 'POST', body: fd })).json();
                if (d.success) {
                    document.getElementById('anchorScript').value = d.text;
                    if (info) info.textContent = '✅ 已导入 ' + f.name + '（' + d.chars + ' 字）';
                    showToast('文稿导入成功（' + d.chars + ' 字）', 'success');
                } else {
                    if (info) info.textContent = '❌ ' + (d.error || '解析失败');
                    showToast(d.error || '文稿解析失败', 'error');
                }
            } catch (e) {
                if (info) info.textContent = '❌ 导入异常: ' + e.message;
                showToast('文稿导入异常: ' + e.message, 'error');
            }
            input.value = '';
        }

        let anchorRefAudioInfo = null; // { filename, duration }

        async function uploadAnchorRefAudio(file) {
            const statusEl = document.getElementById('anchorRefAudioStatus');
            statusEl.textContent = '⏳ 上传中...';
            anchorRefAudioInfo = null;
            try {
                const fd = new FormData();
                fd.append('file', file);
                fd.append('kind', 'audio');
                const resp = await fetch('/api/anchor/upload', { method: 'POST', body: fd });
                const data = await resp.json();
                if (!data.success) {
                    statusEl.textContent = '❌ ' + (data.error || '上传失败');
                    showToast('参考音频上传失败: ' + (data.error || '未知错误'), 'error');
                    return;
                }
                anchorRefAudioInfo = { filename: data.filename, duration: data.duration };
                statusEl.textContent = `✅ 已上传（${data.duration}s，已自动转标准格式）`;
                showToast('参考音频上传成功', 'success');
            } catch (e) {
                statusEl.textContent = '❌ 上传异常: ' + e.message;
                showToast('参考音频上传失败: ' + e.message, 'error');
            }
        }

        function updateAnchorAudioSourceUI() {
            const audioSourceEl = document.getElementById('anchorAudioSource');
            if (!audioSourceEl) return;
            const val = audioSourceEl.value;
            const isRef = val === 'refaudio';
            const hint = document.getElementById('anchorAudioSourceHint');
            const uploadGroup = document.getElementById('anchorRefAudioUploadGroup');
            if (uploadGroup) uploadGroup.style.display = isRef ? 'block' : 'none';
            if (hint) {
                if (isRef) {
                    hint.innerHTML = '参考音频·声音模板：上传一段人声，数字人用该声音的<b>音色/语速/语气</b>念你填的文稿，嘴型自动同步（voice_template 实测）。上传后音色/语速/配音情感随参考音频，无需再选；需选择 Agnes Video 2.5（直连）视频模型';
                } else if (val === 'mat') {
                    hint.textContent = '模型原生声音：直接用视频大模型按配音稿"翻唱"的声音，嘴型与声音天生同步，成片为 1280x704 横屏大画面（模式 A 由形象图驱动、模式 C 需 Agnes Video 2.5 直连，若所选模型不支持会自动回退 TTS）';
                } else {
                    hint.textContent = 'TTS 配音：换回所选音色原声，声音完全可控但嘴型会轻微对不上';
                }
            }
            // 音色/语速/配音情感：refaudio 下禁用（随参考音频，见方案决策）
            ['anchorVoice', 'anchorStyle', 'anchorSpeed'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.disabled = isRef;
            });
        }

        // 绑定声音来源切换与参考音频上传
        (function initAnchorAudioExtras() {
            const sourceEl = document.getElementById('anchorAudioSource');
            if (sourceEl) sourceEl.addEventListener('change', updateAnchorAudioSourceUI);
            const fileInput = document.getElementById('anchorRefAudioFile');
            if (fileInput) {
                fileInput.addEventListener('change', () => {
                    if (fileInput.files.length) uploadAnchorRefAudio(fileInput.files[0]);
                });
            }
            updateAnchorAudioSourceUI();
        })();

        async function startAnchorGeneration() {
            const script = document.getElementById('anchorScript').value.trim();
            if (!script) { showToast('请输入文稿内容', 'error'); return; }

            const mode = document.querySelector('input[name="anchorMode"]:checked').value;
            const voice = document.getElementById('anchorVoice').value;
            const style = document.getElementById('anchorStyle').value;
            const speed = document.getElementById('anchorSpeed').value;
            let avatar_file = '';
            let video_prompt = '';

            // 上传文件
            const btn = document.getElementById('anchorStartBtn');
            btn.disabled = true;
            btn.textContent = '⏳ 处理中...';

            try {
                if (mode === 'A') {
                    const fileInput = document.getElementById('anchorAvatarImage');
                    if (!fileInput.files.length && anchorLibPickImage) {
                        avatar_file = anchorLibPickImage;   // 素材库选用的形象图（已在 anchor/ 目录）
                    } else if (!fileInput.files.length) {
                        showToast('请在「🖼 形象图片」列上传或从素材库选用一张图片', 'error'); btn.disabled = false; btn.textContent = '🎙 开始生成AI 口播视频'; return;
                    } else {
                        const fd = new FormData();
                        fd.append('file', fileInput.files[0]);
                        const uploadResp = await fetch('/api/anchor/upload', { method: 'POST', body: fd });
                        const uploadData = await uploadResp.json();
                        if (!uploadData.success) { showToast('上传失败: ' + uploadData.error, 'error'); btn.disabled = false; btn.textContent = '🎙 开始生成AI 口播视频'; return; }
                        avatar_file = uploadData.filename;
                    }
                } else if (mode === 'B') {
                    const fileInput = document.getElementById('anchorAvatarVideo');
                    if (!fileInput.files.length && anchorLibPickVideo) {
                        avatar_file = anchorLibPickVideo;   // 素材库选用的视频（已在 anchor/ 目录）
                    } else if (!fileInput.files.length) {
                        showToast('请在「🎥 视频素材」列上传或从素材库选用一段视频', 'error'); btn.disabled = false; btn.textContent = '🎙 开始生成AI 口播视频'; return;
                    } else {
                        const fd = new FormData();
                        fd.append('file', fileInput.files[0]);
                        const uploadResp = await fetch('/api/anchor/upload', { method: 'POST', body: fd });
                        const uploadData = await uploadResp.json();
                        if (!uploadData.success) { showToast('上传失败: ' + uploadData.error, 'error'); btn.disabled = false; btn.textContent = '🎙 开始生成AI 口播视频'; return; }
                        avatar_file = uploadData.filename;
                    }
                } else {
                    video_prompt = document.getElementById('anchorVideoPrompt').value.trim();
                    if (!video_prompt) { showToast('请输入画面风格提示词', 'error'); btn.disabled = false; btn.textContent = '🎙 开始生成AI 口播视频'; return; }
                }

                // 提交生成任务
                const minDuration = parseInt(document.getElementById('anchorMinDuration').value);
                const textModel = document.getElementById('anchorTextModel').value;
                const imageModel = document.getElementById('anchorImageModel').value;
                const videoModel = document.getElementById('anchorVideoModel').value;
                // 声音来源：模式 A/C 可选（mat=模型原生声音直出 / tts=TTS 配音 / refaudio=参考音频声音模板），模式 B 无此选项恒走 TTS
                const audioSourceEl = document.getElementById('anchorAudioSource');
                const audio_source = (mode !== 'B' && audioSourceEl) ? audioSourceEl.value : 'tts';
                // 表演风格（动作表情，功能二）：自定义文字优先于下拉
                const motionStyleEl = document.getElementById('anchorMotionStyle');
                const motionCustomEl = document.getElementById('anchorMotionCustom');
                const motion_style = motionStyleEl ? motionStyleEl.value : '';
                const motion_custom = motionCustomEl ? motionCustomEl.value.trim() : '';
                let audio_file = '';
                if (audio_source === 'refaudio') {
                    if (!anchorRefAudioInfo) { showToast('请先上传参考音频（声音模板）', 'error'); return; }
                    audio_file = anchorRefAudioInfo.filename;
                    // refaudio 仅 agnes-video-2.5 系列直连音频通道支持（2.5 与 2.5 Flash 均可，Flash 免费）
                    if (!videoModel.startsWith('agnes-video-2.5')) {
                        showToast('参考音频声音模板需选择 Agnes Video 2.5 或 2.5 Flash（官方直连）视频模型，当前模型不支持', 'error');
                        return;
                    }
                }

                const resp = await fetch('/api/anchor/generate', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ script, mode, voice, style, speed, avatar_file, video_prompt, min_duration: minDuration, text_model: textModel, image_model: imageModel, video_model: videoModel, audio_source, audio_file, motion_style, motion_custom })
                });
                const data = await resp.json();
                if (data.success) {
                    currentAnchorTaskId = data.task_id;
                    showToast('任务已提交，开始生成...', 'success');
                    document.getElementById('anchorProgress').style.display = 'block';
                    startAnchorPolling();
                } else {
                    showToast('提交失败: ' + data.error, 'error');
                }
            } catch (e) {
                showToast('请求失败: ' + e.message, 'error');
            } finally {
                btn.disabled = false;
                btn.textContent = '🎙 开始生成AI 口播视频';
            }
        }

        function startAnchorPolling() {
            if (anchorPollingTimer) clearInterval(anchorPollingTimer);
            anchorPollingTimer = setInterval(pollAnchorStatus, 3000);
            pollAnchorStatus();
        }

        async function pollAnchorStatus() {
            if (!currentAnchorTaskId) return;
            try {
                const resp = await fetch(`/api/anchor/status?task_id=${currentAnchorTaskId}`);
                const data = await resp.json();
                if (!data.success || !data.task) return;

                const task = data.task;
                renderAnchorProgress(task);

                if (task.status === 'completed') {
                    clearInterval(anchorPollingTimer);
                    if (task.retry_result === 'fail') {
                        showToast(task.message || '该段重试失败，已保留上一版成片', 'error');
                    } else {
                        showToast('AI 口播视频生成完成！', 'success');
                    }
                } else if (task.status === 'failed' || task.status === 'cancelled') {
                    clearInterval(anchorPollingTimer);
                    showToast(task.message || '生成失败', 'error');
                }
            } catch (e) {
                console.error('Anchor poll error:', e);
            }
        }

        function renderAnchorProgress(task) {
            const el = document.getElementById('anchorProgressContent');
            const stepMap = {
                'init': '⏳ 初始化',
                'segment': '📝 文稿分段',
                'tts': '🔊 TTS 配音',
                'visual': '🎬 画面生成',
                'compose': '🎞 视频合成',
                'merge': '🔗 最终拼接',
                'completed': '✅ 完成'
            };
            const stepLabels = ['init', 'segment', 'tts', 'visual', 'compose', 'merge', 'completed'];
            const currentIdx = stepLabels.indexOf(task.step);

            let html = '<div style="margin-bottom:12px;">';
            stepLabels.forEach((s, i) => {
                const done = i < currentIdx;
                const current = i === currentIdx;
                const color = done ? 'var(--success)' : current ? 'var(--accent)' : 'var(--text2)';
                const weight = current ? '600' : '400';
                html += `<span style="color:${color};font-weight:${weight};margin-right:12px;font-size:12px;">${stepMap[s] || s}</span>`;
            });
            html += '</div>';
            html += `<div style="color:var(--text2);font-size:12px;margin-bottom:8px;">${task.message || ''}</div>`;

            // 显示分段信息
            if (task.segments && task.segments.length > 0) {
                const isRefTask = task.audio_source === 'refaudio'; // refaudio 段声音随素材，不生成 audio_file
                html += `<div style="font-size:12px;color:var(--text2);margin-bottom:6px;">共 ${task.segments.length} 段</div>`;
                html += '<div style="display:flex;flex-wrap:wrap;gap:8px;">';
                // 单段重试按钮：完成态 + 声音直出任务（mat/refaudio + 2.5 直连）可重试。
                // 含降级段（use_mat_audio=False，限流/失败回退静态画面）——重试=重新排队走 I2V，
                // 队列恢复后很可能生成真·动态素材（2026-09-07 放开该限制）。
                const canRetrySeg = (task.status === 'completed') &&
                    (task.audio_source === 'mat' || task.audio_source === 'refaudio') &&
                    (task.mode === 'A' || task.mode === 'C') &&
                    ((task.video_model || '').indexOf('agnes-video-2.5') === 0);
                task.segments.forEach((seg, i) => {
                    const hasAudio = seg.audio_file ? '✅' : isRefTask ? '🎵' : '⏳';
                    const hasVisual = seg.visual_path ? '✅' : '⏳';
                    const dur = seg.duration ? `${seg.duration}s` : '--';
                    // 完成态 + 成品段存在 → 渲染可点播放的视频卡；否则仅状态文字
                    const segVideo = (task.status === 'completed' && seg.video_url) ?
                        `<video src="${seg.video_url}" controls preload="metadata" playsinline style="width:190px;max-height:120px;border-radius:4px;display:block;background:#000;" title="播放第${i+1}段"></video>` : '';
                    const segIsDegraded = !seg.use_mat_audio;  // 降级段（静态画面，无模型音轨）
                    const retryTip = segIsDegraded ?
                        '该段因限流/生成失败降级为静态画面。点击重新生成，将重新调用 AI 生成动态口播素材（成功后自动重拼全片）' :
                        '第' + (i+1) + '段乱语/掐尾/念错时重新生成该段（新一版语速口型，自动重拼全片）';
                    const retryBtn = canRetrySeg ?
                        `<button onclick="retryAnchorSegment(${i}, ${segIsDegraded})" title="${retryTip}" style="width:100%;background:var(--accent);border:none;color:var(--on-accent);cursor:pointer;font-size:12px;padding:6px 0;border-radius:4px;">🔄 重新生成此段${segIsDegraded ? '（修复静态段）' : ''}</button>` : '';
                    html += `<div style="background:var(--bg);border:1px solid var(--border);border-radius:6px;padding:6px;font-size:11px;width:202px;display:flex;flex-direction:column;gap:4px;">`;
                    if (segVideo) html += segVideo;
                    html += `<div>第${i+1}段 ${dur} | 🎵${hasAudio} 🎬${hasVisual}</div>`;
                    if (retryBtn) html += retryBtn;
                    html += `</div>`;
                });
                html += '</div>';
            }

            el.innerHTML = html;

            // 显示结果视频
            if (task.status === 'completed' && task.output_file) {
                const resultEl = document.getElementById('anchorResult');
                const resultContent = document.getElementById('anchorResultContent');
                resultEl.style.display = 'block';
                const videoUrl = `/anchor/${currentAnchorTaskId}/${task.output_file}`;
                resultContent.innerHTML = `
                    <video controls style="width:100%;max-width:300px;border-radius:var(--radius-sm);" src="${videoUrl}"></video>
                    <div style="margin-top:8px;">
                        <a href="${videoUrl}" download style="color:var(--accent);font-size:13px;">📥 下载视频</a>
                    </div>
                `;
            }
        }

        async function retryAnchorSegment(segIndex, degraded) {
            if (!currentAnchorTaskId) return;
            const tip = degraded
                ? '该段当前是降级静态画面（限流/生成失败时回退）。重新生成将再次调用 AI 生成动态口播素材，' +
                  '若生成成功会自动重拼整片；若再次失败则保留当前版本。'
                : '将用同一形象 + 声音模板重新生成该段素材（新一版语速 / 口型），完成后自动重新拼接整条视频。旧素材与旧成片保留可对照。';
            if (!confirm(`确定重新生成第 ${segIndex + 1} 段吗？\n\n${tip}`)) return;
            try {
                const resp = await fetch('/api/anchor/retry_segment', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ task_id: currentAnchorTaskId, seg_index: segIndex })
                });
                const data = await resp.json();
                if (data.success) {
                    showToast(`已开始重试第 ${segIndex + 1} 段...`, 'success');
                    document.getElementById('anchorResult').style.display = 'none';
                    startAnchorPolling();
                } else {
                    showToast('重试失败: ' + (data.error || '未知错误'), 'error');
                }
            } catch (e) {
                console.error('Retry anchor segment error:', e);
                showToast('重试请求异常: ' + e.message, 'error');
            }
        }

        let canvasModule = {
            nodes: [],          // 节点列表
            links: [],          // 连接线列表
            scale: 1,           // 当前缩放
            viewX: 0,           // 平移 X
            viewY: 0,           // 平移 Y
            selectedId: null,   // 选中的节点 id
            connectFromId: null, // 连线模式起点
            nextId: 1,
            initialized: false,
            modelsLoaded: false,
            textModels: {},
            imageModels: {},
            videoModels: {},
            pollTimers: {},
            autoSaveTimer: null,
            history: [],         // 撤销/重做历史
            historyIndex: -1,    // 当前历史指针
            minimapDrag: null    // 小地图拖拽状态
        };

        function initCanvasModule() {
            const vp = document.getElementById('canvasViewport');
            if (!vp || canvasModule.initialized) return;
            canvasModule.initialized = true;
            bindCanvasViewportEvents();
            bindCanvasKeyEvents();
            loadCanvasModels();
            loadCanvasData();
        }

        async function loadCanvasModels() {
            if (canvasModule.modelsLoaded) return;
            try {
                const resp = await fetch('/api/anchor/models');
                const data = await resp.json();
                if (!data || !data.success) return;
                canvasModule.textModels = data.text_models || {};
                canvasModule.imageModels = data.image_models || {};
                canvasModule.videoModels = data.video_models || {};
                canvasModule.modelsLoaded = true;
            } catch (e) {
                console.error('Canvas load models error:', e);
            }
        }

        function canvasModelOptions(type) {
            const map = type === 'text' ? canvasModule.textModels
                : type === 'image' ? canvasModule.imageModels
                : canvasModule.videoModels;
            return Object.entries(map || {})
                .map(([v, l]) => `<option value="${v}">${l}</option>`)
                .join('');
        }

        function canvasAutoSave() {
            clearTimeout(canvasModule.autoSaveTimer);
            canvasModule.autoSaveTimer = setTimeout(canvasSave, 800);
        }

        async function canvasSave() {
            const payload = {
                nodes: canvasModule.nodes.map(n => ({
                    id: n.id, type: n.type, x: n.x, y: n.y, w: n.w, h: n.h,
                    title: n.title, content: n.content,
                    imageUrl: n.imageUrl || '', imageUrls: n.imageUrls || [],
                    videoUrl: n.videoUrl || '', audioUrl: n.audioUrl || '',
                    model: n.model || '', size: n.size || '', status: n.status || 'idle',
                    prompt: n.prompt || '', refImageId: n.refImageId || '', refAudioId: n.refAudioId || '',
                    frames: n.frames || '', seconds: n.seconds || 5,
                    // 🔴 V1.8.244：videoTaskId / videoStatus / error 必须一起存。
                    // 以前只存 status，刷新后节点带着「生成中」的转圈却没有任务 ID、
                    // 没有轮询 → **永远转下去**（用户报障「编辑视频节点一直在转圈圈」）。
                    videoTaskId: n.videoTaskId || '',
                    videoStatus: n.videoStatus || '',
                    error: n.error || ''
                })),
                links: canvasModule.links,
                scale: canvasModule.scale,
                viewX: canvasModule.viewX,
                viewY: canvasModule.viewY
            };
            try { localStorage.setItem('agnesCanvasData', JSON.stringify(payload)); } catch (e) {}
            try {
                await fetch('/api/canvas/save', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
            } catch (e) { /* 本地保存为主，后端失败不阻塞 */ }
        }

        async function loadCanvasData() {
            let data = null;
            try {
                const local = localStorage.getItem('agnesCanvasData');
                if (local) data = JSON.parse(local);
            } catch (e) {}
            if (!data) {
                try {
                    const resp = await fetch('/api/canvas/load');
                    const j = await resp.json();
                    if (j.success && j.data) data = j.data;
                } catch (e) {}
            }
            if (data && data.nodes) {
                canvasModule.nodes = data.nodes.map(n => ({
                    id: n.id, type: n.type, x: n.x, y: n.y, w: n.w || 220, h: n.h || 120,
                    title: n.title || canvasTypeLabel(n.type), content: n.content || '',
                    imageUrl: n.imageUrl || '', imageUrls: n.imageUrls || [],
                    videoUrl: n.videoUrl || '', audioUrl: n.audioUrl || '',
                    model: n.model || '', size: n.size || '', status: n.status || 'idle',
                    prompt: n.prompt || '', refImageId: n.refImageId || '', refAudioId: n.refAudioId || '',
                    frames: n.frames || '', seconds: n.seconds || 5,
                    videoTaskId: n.videoTaskId || '', videoStatus: n.videoStatus || '',
                    error: n.error || ''
                }));
                canvasModule.nodes.forEach(n => {
                    if (n.type === 'image' && (!n.imageUrls || !n.imageUrls.length) && n.imageUrl) {
                        n.imageUrls = [n.imageUrl];
                    }
                });
                canvasModule.links = data.links || [];
                canvasModule.scale = data.scale || 1;
                canvasModule.viewX = data.viewX || 0;
                canvasModule.viewY = data.viewY || 0;
                canvasModule.nextId = Math.max(1, ...canvasModule.nodes.map(n => parseInt(n.id.replace(/\D/g, '')) || 0)) + 1;
                canvasRenderAll();
                canvasPushHistory();
                // 🔴 V1.8.244：把「生成中」的节点接回轮询。
                // 以前 loadCanvasData 只按原样恢复 status='generating'，却不重启轮询
                // —— 节点永远显示转圈，任务其实早在服务端跑完了（用户报障原话：
                // 「编辑 🎬 视频 节点 不要一直在转圈圈」）。
                canvasResumePolls();
                showToast('已加载保存的画布', 'info');
            } else {
                canvasSeedDemo();
            }
        }

        function canvasSeedDemo() {
            // 首次使用：放置 4 个示例节点演示画布能力
            const w = 220, h = 120;
            const demo = [
                { type: 'note', x: 60, y: 80, title: '📝 剧本节点', content: '一个女孩在雨中的公交站等车，一位老人递给她一把伞，两人相视而笑。\n\n双击节点可编辑内容，点击"AI 续写"可扩展剧情。' },
                { type: 'image', x: 360, y: 80, title: '🖼 分镜/图片节点', content: '雨夜的公交站，昏黄路灯下，女孩撑着透明伞，老人递来一把黑伞，温馨画面', imageUrl: '' },
                { type: 'video', x: 660, y: 80, title: '🎬 视频节点', content: 'The girl smiles as the old man hands her an umbrella at a rainy bus stop at night, warm streetlight, cinematic, gentle motion', imageUrl: '' },
                { type: 'note', x: 360, y: 280, title: '💡 灵感笔记', content: '参考 Toonflow 无限画布：多类型节点自由编排、并行生产、任意回溯。\n\n拖拽节点移动、滚轮缩放、拖拽空白平移。' }
            ];
            demo.forEach(d => {
                    const id = 'cn' + canvasModule.nextId++;
                    d.id = id;   // 让下方连线能取到真实节点 id（原先直接取 demo[i].id 全是 undefined，连线渲染不出来）
                    canvasModule.nodes.push({
                        id, type: d.type,
                        x: d.x, y: d.y, w, h,
                        title: d.title, content: d.content,
                        imageUrl: d.imageUrl, videoUrl: '',
                        model: '', size: '', status: 'idle', prompt: ''
                    });
                });
            canvasModule.links = [
                { id: 'cl' + Date.now(), from: demo[0].id, to: demo[1].id },
                { id: 'cl' + (Date.now() + 1), from: demo[1].id, to: demo[2].id }
            ];
            canvasRenderAll();
            canvasPushHistory();
            canvasSave();
        }

        function canvasTypeLabel(type) {
            return type === 'note' ? '📝 文本' : type === 'image' ? '🖼 图片' : type === 'video' ? '🎬 视频' : '🔊 声音';
        }

        function bindCanvasViewportEvents() {
            const vp = document.getElementById('canvasViewport');
            // 滚轮缩放（以鼠标为中心）
            vp.addEventListener('wheel', (e) => {
                e.preventDefault();
                const rect = vp.getBoundingClientRect();
                const mx = e.clientX - rect.left;
                const my = e.clientY - rect.top;
                const factor = e.deltaY < 0 ? 1.1 : 0.9;
                canvasZoomAt(mx, my, factor);
            }, { passive: false });

            // 鼠标按下：空白处开始平移
            vp.addEventListener('mousedown', (e) => {
                if (e.button === 0 && e.target === vp) {
                    canvasModule.pan = { startX: e.clientX, startY: e.clientY, viewX: canvasModule.viewX, viewY: canvasModule.viewY };
                    vp.classList.add('panning');
                }
            });
            vp.addEventListener('mousemove', (e) => {
                if (canvasModule.pan) {
                    canvasModule.viewX = canvasModule.pan.viewX + (e.clientX - canvasModule.pan.startX);
                    canvasModule.viewY = canvasModule.pan.viewY + (e.clientY - canvasModule.pan.startY);
                    canvasApplyTransform();
                }
            });
            vp.addEventListener('mouseup', () => {
                if (canvasModule.pan) { canvasModule.pan = null; vp.classList.remove('panning'); canvasAutoSave(); }
            });
            vp.addEventListener('mouseleave', () => {
                if (canvasModule.pan) { canvasModule.pan = null; vp.classList.remove('panning'); }
            });
        }

        function bindCanvasKeyEvents() {
            document.addEventListener('keydown', (e) => {
                const canvasTab = document.getElementById('tab-canvas');
                if (!canvasTab || !canvasTab.classList.contains('active')) return;
                if (e.key === 'Escape') {
                    if (canvasModule.connectFromId) { canvasModule.connectFromId = null; canvasUpdateConnectUI(); }
                    if (document.getElementById('canvasNodeModal').style.display !== 'none') canvasCloseNodeModal();
                    else canvasSelectNode(null);
                }
                if ((e.key === 'Delete' || e.key === 'Backspace') && canvasModule.selectedId) {
                    const tag = (e.target && e.target.tagName) || '';
                    if (tag === 'INPUT' || tag === 'TEXTAREA') return;
                    e.preventDefault();
                    canvasDeleteNode(canvasModule.selectedId);
                }
                // Ctrl/Cmd + Z 撤销 · Ctrl/Cmd + Y 或 Ctrl+Shift+Z 重做
                if ((e.ctrlKey || e.metaKey) && (e.key === 'z' || e.key === 'Z' || e.key === 'y' || e.key === 'Y')) {
                    const tag = (e.target && e.target.tagName) || '';
                    if (tag === 'INPUT' || tag === 'TEXTAREA') return;
                    e.preventDefault();
                    if (e.key === 'z' || e.key === 'Z') {
                        if (e.shiftKey) canvasRedo(); else canvasUndo();
                    } else {
                        canvasRedo();
                    }
                }
            });
        }

        function canvasApplyTransform() {
            const grid = document.getElementById('canvasGrid');
            grid.style.transform = `translate(${canvasModule.viewX}px, ${canvasModule.viewY}px) scale(${canvasModule.scale})`;
            const label = document.getElementById('canvasZoomLabel');
            if (label) label.textContent = Math.round(canvasModule.scale * 100) + '%';
        }

        function canvasZoomAt(mx, my, factor) {
            const newScale = Math.min(2.5, Math.max(0.2, canvasModule.scale * factor));
            const k = newScale / canvasModule.scale;
            canvasModule.viewX = mx - (mx - canvasModule.viewX) * k;
            canvasModule.viewY = my - (my - canvasModule.viewY) * k;
            canvasModule.scale = newScale;
            canvasApplyTransform();
        }

        function canvasZoomBy(delta) {
            const vp = document.getElementById('canvasViewport');
            const rect = vp.getBoundingClientRect();
            canvasZoomAt(rect.width / 2, rect.height / 2, 1 + delta);
        }

        function canvasResetView() {
            canvasModule.scale = 1;
            canvasModule.viewX = 0;
            canvasModule.viewY = 0;
            canvasApplyTransform();
        }

        function canvasAddNode(type) {
            const vp = document.getElementById('canvasViewport');
            const rect = vp.getBoundingClientRect();
            // 节点放在视口中心（世界坐标）
            const cx = (rect.width / 2 - canvasModule.viewX) / canvasModule.scale;
            const cy = (rect.height / 2 - canvasModule.viewY) / canvasModule.scale;
            const w = 220, h = type === 'note' ? 140 : 180;
            const defaults = {
                note: { title: '📝 文本节点', content: '' },
                image: { title: '🖼 图片节点', content: '', model: 'sensenova-u1.5-lite', size: '2048x2048', imageUrls: [] },
                video: { title: '🎬 视频节点', content: '', model: 'agnes-video-2.5-flash', size: '16:9', seconds: 5 },
                sound: { title: '🔊 声音节点', content: '', audioUrl: '' }
            };
            const node = {
                id: 'cn' + canvasModule.nextId++,
                type, x: cx - w / 2, y: cy - h / 2, w, h,
                title: defaults[type].title, content: defaults[type].content,
                imageUrl: '', videoUrl: '', audioUrl: defaults[type].audioUrl || '',
                imageUrls: defaults[type].imageUrls || [],
                model: defaults[type].model || '', size: defaults[type].size || '',
                refImageId: '', refAudioId: '',
                // 视频节点：size 存宽高比（'16:9' 等），seconds 存时长秒数
                seconds: defaults[type].seconds || 0,
                status: 'idle', prompt: ''
            };
            canvasModule.nodes.push(node);
            canvasPushHistory();
            canvasRenderAll();
            canvasSelectNode(node.id);
            canvasOpenNodeModal(node.id);
            canvasAutoSave();
        }

        function canvasDeleteNode(id) {
            canvasPushHistory();
            canvasModule.nodes = canvasModule.nodes.filter(n => n.id !== id);
            canvasModule.links = canvasModule.links.filter(l => l.from !== id && l.to !== id);
            if (canvasModule.selectedId === id) canvasModule.selectedId = null;
            if (canvasModule.connectFromId === id) { canvasModule.connectFromId = null; canvasUpdateConnectUI(); }
            canvasRenderAll();
            canvasAutoSave();
        }

        function canvasDeleteSelected() {
            if (!canvasModule.selectedId) { showToast('请先选中一个节点', 'info'); return; }
            canvasDeleteNode(canvasModule.selectedId);
        }

        function canvasClearAll() {
            if (!canvasModule.nodes.length) return;
            if (!confirm('确定要清空画布上的所有节点和连线吗？')) return;
            Object.values(canvasModule.pollTimers).forEach(t => clearInterval(t));
            canvasModule.pollTimers = {};
            canvasPushHistory();
            canvasModule.nodes = [];
            canvasModule.links = [];
            canvasModule.selectedId = null;
            canvasModule.connectFromId = null;
            canvasUpdateConnectUI();
            canvasRenderAll();
            canvasSave();
        }

        function canvasSelectNode(id) {
            canvasModule.selectedId = id;
            document.querySelectorAll('.canvas-node').forEach(el => {
                el.classList.toggle('selected', el.dataset.id === id);
            });
        }

        function canvasToggleConnectMode() {
            if (canvasModule.connectFromId) {
                canvasModule.connectFromId = null;
            } else {
                canvasModule.connectFromId = '__pending__';  // 等待选择起点
                showToast('请点击第一个节点作为连线起点', 'info');
            }
            canvasUpdateConnectUI();
        }

        function canvasNodeDotClick(id) {
            if (!canvasModule.connectFromId || canvasModule.connectFromId === '__pending__') {
                canvasModule.connectFromId = id;
                canvasUpdateConnectUI();
                showToast('已选起点，请点击终点节点', 'info');
                return;
            }
            if (canvasModule.connectFromId === id) {
                showToast('起点和终点不能是同一个节点', 'error');
                return;
            }
            // 防止重复连线
            const dup = canvasModule.links.find(l =>
                (l.from === canvasModule.connectFromId && l.to === id) ||
                (l.from === id && l.to === canvasModule.connectFromId));
if (dup) { showToast('这两个节点已存在连线', 'info'); }
                else {
                    canvasPushHistory();
                    canvasModule.links.push({
                        id: 'cl' + Date.now(),
                        from: canvasModule.connectFromId,
                        to: id
                    });
                    showToast('连线已创建', 'success');
                }
            canvasModule.connectFromId = null;
            canvasUpdateConnectUI();
            canvasRenderLinks();
            canvasAutoSave();
        }

        function canvasUpdateConnectUI() {
            const btn = document.getElementById('canvasConnectBtn');
            const hint = document.getElementById('canvasConnectHint');
            const active = !!canvasModule.connectFromId;
            if (btn) btn.classList.toggle('active', active);
            if (hint) hint.style.display = active ? 'block' : 'none';
        }

        function canvasRenderAll() {
            canvasRenderNodes();
            canvasRenderLinks();
            canvasApplyTransform();
        }

        function canvasRenderNodes() {
            const container = document.getElementById('canvasNodes');
            const selectedId = canvasModule.selectedId;
            container.innerHTML = canvasModule.nodes.map(n => canvasNodeHtml(n, selectedId)).join('');

            // 绑定节点事件
            canvasModule.nodes.forEach(n => {
                const el = document.querySelector(`.canvas-node[data-id="${n.id}"]`);
                if (!el) return;

                // 拖拽移动节点
                el.addEventListener('mousedown', (e) => {
                    if (e.target.closest('.canvas-node-actions') || e.target.closest('.canvas-node-link-dot')) return;
                    if (e.target.closest('video')) return;
                    e.preventDefault();
                    e.stopPropagation();
                    canvasSelectNode(n.id);
                    const startX = e.clientX, startY = e.clientY;
                    const nx = n.x, ny = n.y;
                    el.classList.add('dragging');
                    const onMove = (ev) => {
                        n.x = nx + (ev.clientX - startX) / canvasModule.scale;
                        n.y = ny + (ev.clientY - startY) / canvasModule.scale;
                        el.style.left = n.x + 'px';
                        el.style.top = n.y + 'px';
                        canvasRenderLinks();
                    };
                    const onUp = () => {
                        el.classList.remove('dragging');
                        document.removeEventListener('mousemove', onMove);
                        document.removeEventListener('mouseup', onUp);
                        canvasPushHistory();
                        canvasAutoSave();
                    };
                    document.addEventListener('mousemove', onMove);
                    document.addEventListener('mouseup', onUp);
                });

                // 双击编辑
                el.addEventListener('dblclick', (e) => {
                    if (e.target.closest('.canvas-node-actions')) return;
                    canvasOpenNodeModal(n.id);
                });

                // 点击选中
                el.addEventListener('click', (e) => {
                    if (e.target.closest('.canvas-node-actions') || e.target.closest('.canvas-node-link-dot')) return;
                    canvasSelectNode(n.id);
                });
            });

            // 绑定节点内按钮事件（使用事件委托到容器）
            container.querySelectorAll('[data-act]').forEach(btn => {
                btn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const act = btn.dataset.act;
                    const id = btn.dataset.id;
                    if (act === 'edit') canvasOpenNodeModal(id);
                    else if (act === 'del') canvasDeleteNode(id);
                    else if (act === 'connect') canvasNodeDotClick(id);
                    else if (act === 'gen') canvasNodeGenerate(id);
                    else if (act === 'zoomimg') canvasZoomImage(id);
                });
            });
        }

        function canvasNodeHtml(n, selectedId) {
            const sel = selectedId === n.id ? ' selected' : '';
            let body = '';
            if (n.type === 'note') {
                body = `
                    <div class="cn-text">${escHtml(n.content || '(空)')}</div>
                    <div class="cn-footer">
                        <button class="btn btn-sm" data-act="gen" data-id="${n.id}">🤖 AI 续写</button>
                    </div>`;
            } else if (n.type === 'image') {
                const imgUrls = (n.imageUrls && n.imageUrls.length) ? n.imageUrls : (n.imageUrl ? [n.imageUrl] : []);
                const thumbs = imgUrls.map((u, i) =>
                    `<img src="${escHtml(u)}" data-act="zoomimg" data-id="${n.id}" data-idx="${i}"
                     alt="图片${i + 1}" style="width:100%;height:80px;object-fit:cover;border-radius:4px;cursor:pointer;"
                     title="点击放大 #${i + 1}">`
                ).join('');
                body = `
                    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(90px,1fr));gap:5px;max-height:140px;overflow-y:auto;padding:2px;">
                        ${imgUrls.length ? thumbs : `<div style="height:80px;display:flex;align-items:center;justify-content:center;color:var(--text2);font-size:12px;background:var(--bg);border-radius:6px;">未生成</div>`}
                    </div>
                    ${n.prompt ? `<div class="cn-prompt">${escHtml(n.prompt)}</div>` : ''}
                    ${n.status === 'generating' ? `<div class="cn-status"><span class="cn-spinner"></span> 图片生成中...</div>` : ''}
                    ${n.status === 'failed' ? `<div class="cn-error">❌ ${escHtml(n.error || '生成失败')}</div>` : ''}
                    <div class="cn-footer">
                        <button class="btn btn-sm" data-act="gen" data-id="${n.id}">${imgUrls.length ? '🔄 重新生成' : '✨ 生成图片'}</button>
                    </div>`;
            } else if (n.type === 'video') {
                body = `
                    ${n.videoUrl
                        ? `<video controls src="${n.videoUrl}"></video>`
                        : `<div style="height:100px;display:flex;align-items:center;justify-content:center;color:var(--text2);font-size:12px;background:var(--bg);border-radius:6px;">未生成</div>`}
                    ${n.prompt ? `<div class="cn-prompt">${escHtml(n.prompt)}</div>` : ''}
                    ${n.status === 'generating' ? `<div class="cn-status"><span class="cn-spinner"></span> 视频生成中... ${escHtml(n.videoStatus || '')}</div>` : ''}
                    ${n.status === 'failed' ? `<div class="cn-error">❌ ${escHtml(n.error || '生成失败')}</div>` : ''}
                    <div class="cn-footer">
                        <button class="btn btn-sm" data-act="gen" data-id="${n.id}">${n.videoUrl ? '🔄 重新生成' : '🎬 生成视频'}</button>
                    </div>`;
            } else if (n.type === 'sound') {
                body = `
                    ${n.audioUrl
                        ? `<audio controls src="${n.audioUrl}" style="width:100%;max-height:60px;"></audio>`
                        : `<div style="height:60px;display:flex;align-items:center;justify-content:center;color:var(--text2);font-size:12px;background:var(--bg);border-radius:6px;">未设置声音</div>`}
                    ${n.prompt ? `<div class="cn-prompt">${escHtml(n.prompt)}</div>` : ''}
                    <div class="cn-footer">
                        <button class="btn btn-sm" data-act="edit" data-id="${n.id}">✏️ 编辑</button>
                    </div>`;
            }
            return `
                <div class="canvas-node${sel}" data-id="${n.id}" style="left:${n.x}px;top:${n.y}px;width:${n.w}px;">
                    <div class="canvas-node-header">
                        <span>${escHtml(n.title)}</span>
                        <div class="canvas-node-actions">
                            <button data-act="edit" data-id="${n.id}" title="编辑">✏️</button>
                            <button data-act="del" data-id="${n.id}" title="删除">🗑</button>
                        </div>
                    </div>
                    <div class="canvas-node-body">${body}</div>
                    <div class="canvas-node-link-dot" data-act="connect" data-id="${n.id}" title="建立连线"></div>
                </div>`;
        }

        function canvasRenderLinks() {
            const svg = document.getElementById('canvasLinks');
            const lines = canvasModule.links.map(l => {
                const from = canvasModule.nodes.find(n => n.id === l.from);
                const to = canvasModule.nodes.find(n => n.id === l.to);
                if (!from || !to) return '';
                const x1 = from.x + from.w, y1 = from.y + (from.h || 60) / 2;
                const x2 = to.x, y2 = to.y + (to.h || 60) / 2;
                const mid = (x1 + x2) / 2;
                return `<path class="canvas-link-line" d="M ${x1} ${y1} C ${mid} ${y1}, ${mid} ${y2}, ${x2} ${y2}"></path>`;
            }).join('');
            svg.innerHTML = `<defs></defs>${lines}`;
        }

        function canvasZoomImage(id, idx) {
            const n = canvasModule.nodes.find(x => x.id === id);
            if (!n) return;
            const urls = (n.imageUrls && n.imageUrls.length) ? n.imageUrls : (n.imageUrl ? [n.imageUrl] : []);
            const url = urls[idx || 0];
            if (url) window.open(url, '_blank');
        }

        function canvasOpenNodeModal(id) {
            const n = canvasModule.nodes.find(x => x.id === id);
            if (!n) return;
            const modal = document.getElementById('canvasNodeModal');
            document.getElementById('canvasNodeModalTitle').textContent = `编辑 ${canvasTypeLabel(n.type)} 节点`;
            const body = document.getElementById('canvasNodeModalBody');

            let html = '';
            if (n.type === 'note') {
                html = `
                    <div class="form-group">
                        <label class="form-label">标题</label>
                        <input class="form-input" id="cnModalTitle" value="${escHtml(n.title)}">
                    </div>
                    <div class="form-group">
                        <label class="form-label">内容（剧本 / 描述 / 灵感）</label>
                        <textarea class="form-textarea" id="cnModalContent" rows="8" style="min-height:180px;" placeholder="输入文本内容...">${escHtml(n.content)}</textarea>
                    </div>
                    <div class="form-group">
                        <label class="form-label">🤖 AI 续写指令</label>
                        <input class="form-input" id="cnModalInstruction" placeholder="例如：续写 / 扩写成剧本 / 改写成分镜描述" value="续写">
                    </div>`;
            } else if (n.type === 'image') {
                html = `
                    <div class="form-group">
                        <label class="form-label">标题</label>
                        <input class="form-input" id="cnModalTitle" value="${escHtml(n.title)}">
                    </div>
                    <div class="form-group">
                        <label class="form-label">图片描述 Prompt</label>
                        <textarea class="form-textarea" id="cnModalContent" rows="6" style="min-height:150px;" placeholder="描述你想要生成的图片...">${escHtml(n.content)}</textarea>
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label class="form-label">模型</label>
                            <select class="form-select" id="cnModalModel">${canvasModelOptions('image')}</select>
                        </div>
                        <div class="form-group">
                            <label class="form-label">尺寸</label>
                            <select class="form-select" id="cnModalSize">
                                <option value="1024x1024">1024 × 1024</option>
                                <option value="1024x768">1024 × 768</option>
                                <option value="768x1024">768 × 1024</option>
                                <option value="1536x1024">1536 × 1024</option>
                            </select>
                        </div>
                    </div>
                    <div class="form-group">
                        <label class="form-label">🖼 图片来源（上传 / 解析 / AI 生成，最多 5 张）</label>
                        <div id="cnModalImagePreview">${canvasImagePreviewHtml(n)}</div>
                        <input type="file" id="cnModalImageFile" accept="image/*" style="display:none;">
                        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px;">
                            <button class="btn btn-sm" type="button" id="cnModalUploadBtn">📁 本地上传</button>
                            <!-- V1.8.244：弹窗里补回「AI 生图」。上面的标签一直写着
                                 「上传 / 解析 / AI 生成」三条入口，但 V1.8.151 只落地了
                                 上传与解析，AI 生成只剩画布节点底那颗按钮 —— 用户在编辑
                                 弹窗里改完 Prompt 找不到生图入口，以为按钮被吃了。
                                 现在三条入口在同一个弹窗里都能用。 -->
                            <button class="btn btn-sm" type="button" id="cnModalGenBtn"
                                    title="按上面填的 Prompt 与模型生一张图（追加到图片列表，最多 5 张）">🎨 AI 生图</button>
                            <button class="btn btn-sm" type="button" onclick="canvasClearNodeImage('${n.id}')"
                                    title="清掉全部图片，提示词与节点保留">🗑 清除全部</button>
                            <span id="cnModalImageMsg" style="font-size:12px;color:var(--text2);align-self:center;"></span>
                        </div>
                    </div>
                    <div class="form-group">
                        <label class="form-label">🔗 图床 / 直链 URL 解析（追加一张）</label>
                        <div style="display:flex;gap:8px;">
                            <input class="form-input" id="cnModalImageUrl" style="flex:1;"
                                   placeholder="粘贴图床分享页或图片直链（也认 markdown / [img] 标签）"
                                   value="${(() => { const u = (n.imageUrls && n.imageUrls.length) ? n.imageUrls[n.imageUrls.length-1] : n.imageUrl; return (/^https?:/i).test(u || '') ? escHtml(u) : ''; })()}">
                            <button class="btn btn-sm" type="button" onclick="canvasResolveNodeImage('${n.id}')">🔗 解析</button>
                        </div>
                        <div class="form-hint">直链填完直接「✅ 保存」即可追加；图床分享页（imgur / postimages / sm.ms 等）请先点「🔗 解析」，服务端会挖出 og:image 直链。解析在服务端完成，内网与本机地址一律拒绝。已达 5 张时上传/解析/生成按钮会被禁用。</div>
                    </div>`;
            } else if (n.type === 'video') {
                html = `
                    <div class="form-group">
                        <label class="form-label">标题</label>
                        <input class="form-input" id="cnModalTitle" value="${escHtml(n.title)}">
                    </div>
                    <div class="form-group">
                        <label class="form-label">视频描述 Prompt（建议英文）</label>
                        <textarea class="form-textarea" id="cnModalContent" rows="6" style="min-height:150px;" placeholder="[主体] + [动作] + [场景] + [镜头] + [光线] + [风格]">${escHtml(n.content)}</textarea>
                        <div style="display:flex;gap:8px;align-items:center;margin-top:6px;flex-wrap:wrap;">
                            <button class="btn btn-sm" type="button" onclick="canvasReadLinkedText('${n.id}')">📖 读取连线的文本节点</button>
                            <span id="cnModalVideoTextMsg" style="font-size:12px;color:var(--text2);"></span>
                        </div>
                    </div>
                    <div class="form-group">
                        <label class="form-label">🖼 参考图（图生视频，可选）</label>
                        <select class="form-select" id="cnModalRefImage">
                            <option value="">无（纯文本生成）</option>
                            ${canvasModule.nodes.filter(x => (x.imageUrls && x.imageUrls.length) || x.imageUrl).map(x =>
                                `<option value="${x.id}" ${x.id === (n.refImageId || '') ? 'selected' : ''}>${escHtml(x.title)}</option>`
                            ).join('')}
                        </select>
                        <div class="form-hint">选择画布上已生成图片的节点作为首帧参考图；若已连线到图片节点，打开面板时会自动选中，可手动覆盖。</div>
                    </div>
                    <div class="form-group">
                        <label class="form-label">🔊 参考声音（可选，连给视频当配乐）</label>
                        <select class="form-select" id="cnModalRefAudio">
                            <option value="">无（不要配乐）</option>
                            ${canvasModule.nodes.filter(x => x.type === 'sound' && x.audioUrl).map(x =>
                                `<option value="${x.id}" ${x.id === (n.refAudioId || '') ? 'selected' : ''}>${escHtml(x.title)}</option>`
                            ).join('')}
                        </select>
                        <div class="form-hint">选择已设置声音的节点作为配乐；已连线到本节点的声音节点会自动选中，可直接覆盖。</div>
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label class="form-label">模型</label>
                            <select class="form-select" id="cnModalModel">${canvasModelOptions('video')}</select>
                        </div>
                        <div class="form-group">
                            <label class="form-label">⏱ 时长（4–12 秒，无级调速）</label>
                            <div style="display:flex;align-items:center;gap:8px;">
                                <input type="range" id="cnModalSeconds" min="4" max="12" step="1"
                                       value="${n.seconds || 5}" style="flex:1;accent-color:var(--accent);">
                                <span id="cnModalSecondsLabel" style="font-size:13px;color:var(--accent);min-width:32px;text-align:right;">${n.seconds || 5}s</span>
                            </div>
                        </div>
                        <div class="form-group">
                            <label class="form-label">📐 宽高比（官方支持）</label>
                            <select class="form-select" id="cnModalAspect">
                                <option value="16:9" ${(n.size || '') === '16:9' ? 'selected' : ''}>16:9（横屏）</option>
                                <option value="9:16" ${(n.size || '') === '9:16' ? 'selected' : ''}>9:16（竖屏）</option>
                                <option value="4:3" ${(n.size || '') === '4:3' ? 'selected' : ''}>4:3</option>
                                <option value="1:1" ${(n.size || '') === '1:1' ? 'selected' : ''}>1:1</option>
                                <option value="3:4" ${(n.size || '') === '3:4' ? 'selected' : ''}>3:4</option>
                            </select>
                            <div class="form-hint">官方支持 16:9 / 9:16 / 4:3 / 1:1 / 3:4；时长 4–12 秒，服务端会钳制到官方范围。</div>
                        </div>
                    </div>`;
            } else if (n.type === 'sound') {
                html = `
                    <div class="form-group">
                        <label class="form-label">标题</label>
                        <input class="form-input" id="cnModalTitle" value="${escHtml(n.title)}">
                    </div>
                    <div class="form-group">
                        <label class="form-label">🔊 声音素材（上传 / 直链，二选一）</label>
                        <div id="cnModalAudioPreview">${canvasAudioPreviewHtml(n)}</div>
                        <input type="file" id="cnModalAudioFile" accept=".mp3,.wav,.m4a,audio/mpeg,audio/wav,audio/mp4" style="display:none;">
                        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px;">
                            <button class="btn btn-sm" type="button" id="cnModalUploadAudioBtn">📁 本地上传</button>
                            <button class="btn btn-sm" type="button" onclick="canvasOpenAudioTrim('${n.id}')"
                                    title="裁切到 12 秒以内（上游模型只收 ≤12s 音频）">✂️ 剪辑（≤12s）</button>
                            <button class="btn btn-sm" type="button" onclick="canvasClearNodeAudio('${n.id}')"
                                    title="只清掉已设置的声音，节点保留">🗑 清除声音</button>
                            <span id="cnModalAudioMsg" style="font-size:12px;color:var(--text2);align-self:center;"></span>
                        </div>
                    </div>
                    <div class="form-group">
                        <label class="form-label">🔗 音频直链 URL</label>
                        <div style="display:flex;gap:8px;">
                            <input class="form-input" id="cnModalAudioUrl" style="flex:1;"
                                   placeholder="粘贴音频直链（.mp3 / .wav / .m4a），填完直接「✅ 保存」即可"
                                   value="${(/^https?:/i).test(n.audioUrl || '') ? escHtml(n.audioUrl) : ''}">
                        </div>
                        <div class="form-hint">直链填完直接保存即可；本地上传会落到 /SCAU/ 并随视频请求转成 base64 提交。文件名只许英文（字母/数字/._-）。</div>
                    </div>`;
            }

            html += `
                <div style="display:flex;gap:8px;margin-top:16px;">
                    <button class="btn btn-primary" style="flex:1;" id="cnModalSaveBtn">✅ 保存</button>
                    <button class="btn" style="flex:1;" onclick="canvasCloseNodeModal()">取消</button>
                </div>`;
            body.innerHTML = html;

            // 图片节点：本地上传。⚠️ 隐藏 file input 绝不能放进可点区域内部，
            // 否则点按钮会同时命中 input 自己；这里让按钮间接触发它的 click()。
            const cnUpBtn = document.getElementById('cnModalUploadBtn');
            const cnUpFile = document.getElementById('cnModalImageFile');
            if (cnUpBtn && cnUpFile) {
                cnUpBtn.onclick = () => cnUpFile.click();
                cnUpFile.onchange = () => canvasUploadNodeImage(n.id);
            }
            // V1.8.244：弹窗里的「🎨 AI 生图」。先把弹窗里改过的字段**灌回节点**再生成
            // （否则用的是上次保存的旧 Prompt / 旧模型），然后走与画布那颗按钮同一条路。
            const cnGenBtn = document.getElementById('cnModalGenBtn');
            if (cnGenBtn) {
                cnGenBtn.onclick = () => canvasNodeGenerateFromModal(n.id);
            }
            // 声音节点：本地上传（与图片同构 —— 隐藏 input 不放可点区，按钮间接触发）
            const cnAuBtn = document.getElementById('cnModalUploadAudioBtn');
            const cnAuFile = document.getElementById('cnModalAudioFile');
            if (cnAuBtn && cnAuFile) {
                cnAuBtn.onclick = () => cnAuFile.click();
                cnAuFile.onchange = () => canvasUploadNodeAudio(n.id);
            }

            // 预填已保存的值
            const modelSel = document.getElementById('cnModalModel');
            if (modelSel && n.model) modelSel.value = n.model;
            const sizeSel = document.getElementById('cnModalSize');
            if (sizeSel && n.size) sizeSel.value = n.size;
            // 视频节点：时长滑块 + 宽高比
            const secSel = document.getElementById('cnModalSeconds');
            const secLbl = document.getElementById('cnModalSecondsLabel');
            if (secSel) {
                secSel.value = n.seconds || 5;
                if (secLbl) secLbl.textContent = (n.seconds || 5) + 's';
                secSel.oninput = function () { if (secLbl) secLbl.textContent = this.value + 's'; };
            }
            const aspSel = document.getElementById('cnModalAspect');
            if (aspSel && n.size) aspSel.value = n.size;
            // 视频节点：参考图 —— 没保存过就自动选中已连线的图片节点（用户可手动覆盖）
            const refSel = document.getElementById('cnModalRefImage');
            if (refSel) {
                let eff = n.refImageId || '';
                if (!eff) {
const linkedImg = canvasModule.links.find(l => l.to === n.id
                    && canvasModule.nodes.find(x => x.id === l.from && ((x.imageUrls && x.imageUrls.length) || x.imageUrl)));
                    if (linkedImg) eff = linkedImg.from;
                }
                refSel.value = eff;
            }
            // 视频节点：参考声音 —— 没保存过就自动选中已连线的声音节点（用户可手动覆盖）
            const raSel = document.getElementById('cnModalRefAudio');
            if (raSel) {
                let effAu = n.refAudioId || '';
                if (!effAu) {
                    const linkedAud = canvasModule.links.find(l => l.to === n.id
                        && canvasModule.nodes.find(x => x.id === l.from && x.type === 'sound' && x.audioUrl));
                    if (linkedAud) effAu = linkedAud.from;
                }
                raSel.value = effAu;
            }
            // 视频节点：Prompt 还空着时自动读取连线的文本节点（手动按钮仍可追加）
            if (!(n.content || '').trim()) canvasReadLinkedText(n.id);

            // 保存按钮
            document.getElementById('cnModalSaveBtn').onclick = () => {
                n.title = document.getElementById('cnModalTitle').value.trim() || canvasTypeLabel(n.type);
                // 声音节点没有「内容」字段（只有标题/上传/直链），否则保存会崩在 null.value
                const ctEl = document.getElementById('cnModalContent');
                if (ctEl) n.content = ctEl.value.trim();
                const m = document.getElementById('cnModalModel');
                if (m) n.model = m.value;
                const s = document.getElementById('cnModalSize');
                if (s) n.size = s.value;
                // 视频节点：时长与宽高比（旧节点没有这两个字段时取默认值）
                const sec = document.getElementById('cnModalSeconds');
                if (sec) n.seconds = parseInt(sec.value, 10) || 5;
                const asp = document.getElementById('cnModalAspect');
                if (asp) n.size = asp.value;
                const r = document.getElementById('cnModalRefImage');
                if (r) n.refImageId = r.value;
                const ra = document.getElementById('cnModalRefAudio');
                if (ra) n.refAudioId = ra.value;
                // 图片节点：直链直接采用（图床分享页请点「🔗 解析」，解析后会即时写入 imageUrls）
                const u = document.getElementById('cnModalImageUrl');
                if (u && n.type === 'image') {
                    const v = (u.value || '').trim();
                    if (v && /^https?:\/\//i.test(v)) {
                        if (!n.imageUrls) n.imageUrls = [];
                        if (n.imageUrls.length < 5 && n.imageUrls.indexOf(v) < 0) {
                            n.imageUrls.push(v);
                            n.imageUrl = n.imageUrls[0];
                        }
                    }
                }
                // 声音节点：直链直接采用（本地上传的 /SCAU/xxx 与 data: 不受影响）
                const au = document.getElementById('cnModalAudioUrl');
                if (au && n.type === 'sound') {
                    const v = (au.value || '').trim();
                    if (v && /^https?:\/\//i.test(v)) n.audioUrl = v;
                    else if (!v && /^https?:\/\//i.test(n.audioUrl || '')) n.audioUrl = '';
                }
                canvasCloseNodeModal();
                canvasRenderAll();
                canvasAutoSave();
                showToast('节点已保存', 'success');
            };
            modal.style.display = 'flex';
        }

        function canvasCloseNodeModal() {
            document.getElementById('canvasNodeModal').style.display = 'none';
        }

        // 以前图片节点只能「AI 生成」，已有的素材（本地图、图床上的图）塞不进来。
        // 现在三条入口并存：AI 生成（画布按钮）、本地上传、图床链接解析。
        function canvasImagePreviewHtml(n) {
            const urls = (n.imageUrls && n.imageUrls.length) ? n.imageUrls : (n.imageUrl ? [n.imageUrl] : []);
            if (!urls.length) {
                return '<div style="height:96px;display:flex;align-items:center;justify-content:center;'
                    + 'color:var(--text2);font-size:12px;background:var(--surface2);'
                    + 'border:1px dashed var(--border);border-radius:var(--radius-sm);">'
                    + '未设置图片（可本地上传 / 图床解析 / AI 生成，最多 5 张）</div>';
            }
            const maxHint = urls.length >= 5 ? '（已达上限）' : '';
            return '<div style="display:flex;gap:10px;align-items:flex-start;flex-wrap:wrap;">'
                + urls.map((u, i) =>
                    `<div style="position:relative;">
                        <img src="${escHtml(u)}" alt="图片${i + 1}"
                             style="width:100px;height:80px;object-fit:cover;border-radius:6px;border:1px solid var(--border);background:var(--surface2);">
                        <button type="button" class="btn btn-sm"
                            onclick="canvasRemoveNodeImage('${n.id}', ${i})"
                            style="position:absolute;top:-6px;right:-6px;width:20px;height:20px;padding:0;font-size:14px;background:var(--err-fg);color:#fff;border-radius:50%;line-height:1;">×</button>
                        <div style="font-size:10px;color:var(--text2);margin-top:2px;word-break:break-all;max-width:100px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${escHtml(u)}">#${i + 1}</div>
                    </div>`
                ).join('')
                + '<div style="font-size:11px;color:var(--text2);align-self:center;">共 ' + urls.length + '/5 张 ' + maxHint + '</div>'
                + '</div>';
        }

        function canvasRemoveNodeImage(id, idx) {
            const n = canvasModule.nodes.find(x => x.id === id);
            if (!n) return;
            const urls = (n.imageUrls && n.imageUrls.length) ? n.imageUrls : (n.imageUrl ? [n.imageUrl] : []);
            if (idx < 0 || idx >= urls.length) return;
            urls.splice(idx, 1);
            n.imageUrls = urls;
            n.imageUrl = urls.length ? urls[0] : '';
            canvasRefreshImageBlock(n);
            canvasRenderAll();
            canvasAutoSave();
            showToast('已移除一张图片（剩余 ' + urls.length + ' 张）', 'info');
        }

        function canvasImageMsg(text, ok) {
            const el = document.getElementById('cnModalImageMsg');
            if (!el) return;
            el.textContent = text || '';
            el.style.color = ok === false ? 'var(--err-fg)' : (ok === true ? 'var(--ok-fg)' : 'var(--text2)');
        }

        function canvasRefreshImageBlock(n) {
            const box = document.getElementById('cnModalImagePreview');
            if (box) box.innerHTML = canvasImagePreviewHtml(n);
        }

        // 统一出口：改图后必须同时刷新弹窗预览 + 画布缩略 + 落盘
        function canvasSetNodeImage(id, url) {
            const n = canvasModule.nodes.find(x => x.id === id);
            if (!n) return;
            if (!url) {
                n.imageUrls = [];
                n.imageUrl = '';
            } else {
                if (!n.imageUrls) n.imageUrls = [];
                if (n.imageUrls.length >= 5) {
                    canvasImageMsg('已达 5 张上限，无法再添加', false);
                    return;
                }
                n.imageUrls.push(url);
                n.imageUrl = n.imageUrls[0];
            }
            n.status = 'idle';
            n.error = '';
            canvasRefreshImageBlock(n);
            canvasRenderAll();
            canvasAutoSave();
        }

        async function canvasUploadNodeImage(id) {
            const n = canvasModule.nodes.find(x => x.id === id);
            const fileEl = document.getElementById('cnModalImageFile');
            if (!n || !fileEl || !fileEl.files || !fileEl.files.length) return;
            const cur = (n.imageUrls && n.imageUrls.length) ? n.imageUrls.length : (n.imageUrl ? 1 : 0);
            if (cur >= 5) { canvasImageMsg('已达 5 张上限，无法再添加', false); return; }
            canvasImageMsg('上传中…');
            try {
                const fd = new FormData();
                fd.append('file', fileEl.files[0]);
                const res = await fetch('/api/upload/image', { method: 'POST', body: fd });
                const ct = (res.headers.get('content-type') || '');
                if (!res.ok || ct.indexOf('application/json') < 0) {
                    throw new Error('服务器返回异常（HTTP ' + res.status
                        + (ct ? '，非 JSON 响应' : '') + '），请确认服务端已重启到最新版本');
                }
                const data = await res.json();
                if (!data || !data.success) throw new Error((data && data.error) || '上传失败');
                canvasSetNodeImage(id, data.url);
                canvasImageMsg('已上传：' + (data.filename || data.url), true);
            } catch (e) {
                canvasImageMsg('上传失败：' + (e && e.message ? e.message : e), false);
            } finally {
                // 清空 value，否则连选同一张图不会再触发 change
                try { fileEl.value = ''; } catch (e) {}
            }
        }

        async function canvasResolveNodeImage(id) {
            const n = canvasModule.nodes.find(x => x.id === id);
            const input = document.getElementById('cnModalImageUrl');
            if (!n || !input) return;
            const raw = (input.value || '').trim();
            if (!raw) { canvasImageMsg('请先粘贴图床链接或图片直链', false); return; }
            const cur = (n.imageUrls && n.imageUrls.length) ? n.imageUrls.length : (n.imageUrl ? 1 : 0);
            if (cur >= 5) { canvasImageMsg('已达 5 张上限，无法再添加', false); return; }
            canvasImageMsg('解析中…');
            try {
                const res = await fetch('/api/canvas/resolve_image', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ url: raw })
                });
                const ct = (res.headers.get('content-type') || '');
                if (!res.ok || ct.indexOf('application/json') < 0) {
                    throw new Error('服务器返回异常（HTTP ' + res.status
                        + (ct ? '，非 JSON 响应' : '') + '），请确认服务端已重启到最新版本');
                }
                const data = await res.json();
                if (!data || !data.success) throw new Error((data && data.error) || '解析失败');
                input.value = data.url;
                canvasSetNodeImage(id, data.url);
                canvasImageMsg('已解析为直链（' + (data.kind || '直链') + '）', true);
            } catch (e) {
                canvasImageMsg('解析失败：' + (e && e.message ? e.message : e), false);
            }
        }

        function canvasClearNodeImage(id) {
            const n = canvasModule.nodes.find(x => x.id === id);
            if (!n) return;
            const cur = (n.imageUrls && n.imageUrls.length) ? n.imageUrls.length : (n.imageUrl ? 1 : 0);
            if (!cur) { canvasImageMsg('这个节点本来就没图片'); return; }
            canvasSetNodeImage(id, '');
            const input = document.getElementById('cnModalImageUrl');
            if (input) input.value = '';
            canvasImageMsg('已清除全部图片', true);
        }

        // 与图片节点同构：本地上传落 /SCAU/，直链填完直接保存，服务端按需转 base64。
        function canvasAudioPreviewHtml(n) {
            if (!n.audioUrl) {
                return '<div style="height:64px;display:flex;align-items:center;justify-content:center;'
                    + 'color:var(--text2);font-size:12px;background:var(--surface2);'
                    + 'border:1px dashed var(--border);border-radius:var(--radius-sm);">'
                    + '未设置声音（可本地上传 / 填直链）</div>';
            }
            return '<audio controls src="' + escHtml(n.audioUrl) + '" '
                + 'style="width:100%;max-height:64px;border-radius:6px;"></audio>';
        }

        function canvasAudioMsg(text, ok) {
            const el = document.getElementById('cnModalAudioMsg');
            if (el) { el.textContent = text || ''; el.style.color = ok ? 'var(--ok-fg)' : 'var(--err-fg)'; }
        }

        function canvasRefreshAudioBlock(n) {
            const block = document.getElementById('cnModalAudioPreview');
            if (block) block.innerHTML = canvasAudioPreviewHtml(n);
        }

        function canvasSetNodeAudio(id, url) {
            const n = canvasModule.nodes.find(x => x.id === id);
            if (!n) return;
            n.audioUrl = url || '';
            canvasRefreshAudioBlock(n);
            canvasRenderNodes();
            canvasAutoSave();
        }

        async function canvasUploadNodeAudio(id) {
            const n = canvasModule.nodes.find(x => x.id === id);
            const file = document.getElementById('cnModalAudioFile').files[0];
            if (!n || !file) { canvasAudioMsg('未选中文件'); return; }
            const ext = (file.name.split('.').pop() || '').toLowerCase();
            if (!['mp3', 'wav', 'm4a'].includes(ext)) {
                canvasAudioMsg('只支持 mp3 / wav / m4a', false); return;
            }
            canvasAudioMsg('上传中…');
            try {
                const fd = new FormData();
                fd.append('file', file);
                const res = await fetch('/api/canvas/upload/audio', { method: 'POST', body: fd });
                // ⚠️ 服务器异常时返回的是 HTML（405/404/500），直接 .json() 会抛
                //    「Unexpected token '<'」—— 先看 status 与 content-type，提前给友好提示。
                const ct = (res.headers.get('content-type') || '');
                if (!res.ok || ct.indexOf('application/json') < 0) {
                    throw new Error('服务器返回异常（HTTP ' + res.status
                        + (ct ? '，非 JSON 响应' : '') + '），请确认服务端已重启到最新版本');
                }
                const data = await res.json();
                if (!data || !data.success) throw new Error((data && data.error) || '上传失败');
                canvasSetNodeAudio(id, data.url);
                canvasAudioMsg('已上传（' + ext.toUpperCase() + '）', true);
            } catch (e) {
                canvasAudioMsg('上传失败：' + (e && e.message ? e.message : e), false);
            }
        }

        function canvasClearNodeAudio(id) {
            const n = canvasModule.nodes.find(x => x.id === id);
            if (!n) return;
            if (!n.audioUrl) { canvasAudioMsg('这个节点本来就没声音'); return; }
            canvasSetNodeAudio(id, '');
            const input = document.getElementById('cnModalAudioUrl');
            if (input) input.value = '';
            canvasAudioMsg('已清除声音', true);
        }

        let _trimNodeId = null;

        function canvasOpenAudioTrim(nodeId) {
            const n = canvasModule.nodes.find(x => x.id === nodeId);
            if (!n || !n.audioUrl) { canvasAudioMsg('请先上传或填入声音素材', false); return; }
            _trimNodeId = nodeId;
            const panel = document.getElementById('audioTrimPanel');
            const player = document.getElementById('audioTrimPlayer');
            const start = document.getElementById('audioTrimStart');
            const dur = document.getElementById('audioTrimDuration');
            const hint = document.getElementById('audioTrimHint');
            player.src = n.audioUrl;
            start.value = '0';
            dur.value = '12';
            if (hint) hint.textContent = '载入中…';
            panel.style.display = 'flex';
            // 等元数据就绪后按真实总长钳制起止
            player.onloadedmetadata = () => {
                const total = player.duration || 0;
                if (total && isFinite(total)) {
                    if (hint) hint.textContent = '音频总长 ' + total.toFixed(1) + ' 秒，'
                        + '起止之和不能超过总长';
                    const maxDur = Math.min(12, total);
                    dur.max = String(maxDur);
                    dur.step = '0.1';
                    if (parseFloat(dur.value) > maxDur) dur.value = String(maxDur.toFixed(1));
                }
            };
        }

        function canvasCloseAudioTrim() {
            document.getElementById('audioTrimPanel').style.display = 'none';
            _trimNodeId = null;
        }

        function audioTrimPreview() {
            const player = document.getElementById('audioTrimPlayer');
            const start = parseFloat(document.getElementById('audioTrimStart').value) || 0;
            const dur = parseFloat(document.getElementById('audioTrimDuration').value) || 0;
            if (!player.src) return;
            if (player.currentTime > start + dur) player.currentTime = start;
            player.play().catch(() => {});
            if (dur > 0) {
                setTimeout(() => { if (player.currentTime >= start + dur) player.pause(); },
                    Math.max(0, (start + dur - player.currentTime) * 1000) + 200);
            }
        }

        async function canvasApplyAudioTrim() {
            if (!_trimNodeId) return;
            const n = canvasModule.nodes.find(x => x.id === _trimNodeId);
            if (!n || !n.audioUrl) return;
            const start = parseFloat(document.getElementById('audioTrimStart').value) || 0;
            const dur = parseFloat(document.getElementById('audioTrimDuration').value) || 0;
            const msg = document.getElementById('audioTrimMsg');
            if (dur <= 0 || dur > 12) { if (msg) { msg.textContent = '时长须在 0–12 秒'; msg.style.color = 'var(--err-fg)'; } return; }
            if (msg) { msg.textContent = '裁切中…'; msg.style.color = 'var(--text2)'; }
            try {
                const res = await fetch('/api/canvas/trim/audio', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ url: n.audioUrl, start: start, duration: dur })
                });
                const ct = (res.headers.get('content-type') || '');
                if (!res.ok || ct.indexOf('application/json') < 0) {
                    throw new Error('服务器返回异常（HTTP ' + res.status + '）');
                }
                const data = await res.json();
                if (!data || !data.success) throw new Error((data && data.error) || '裁切失败');
                canvasSetNodeAudio(_trimNodeId, data.url);
                if (msg) { msg.textContent = '已裁切为 ' + data.duration + 's'; msg.style.color = 'var(--ok-fg)'; }
                canvasCloseAudioTrim();
            } catch (e) {
                if (msg) { msg.textContent = '裁切失败：' + (e && e.message ? e.message : e); msg.style.color = 'var(--err-fg)'; }
            }
        }

        // 把已连线到本视频节点的文本节点内容拼进 Prompt，省得用户复制粘贴。
        // 只取「指向本节点」的连线（l.to === n.id），避免把下游节点的内容也捞进来。
        function canvasReadLinkedText(videoId) {
            const n = canvasModule.nodes.find(x => x.id === videoId);
            if (!n) return;
            const linked = canvasModule.links
                .filter(l => l.to === videoId)
                .map(l => canvasModule.nodes.find(x => x.id === l.from))
                .filter(x => x && x.type === 'note' && (x.content || '').trim());
            const msg = document.getElementById('cnModalVideoTextMsg');
            if (!linked.length) {
                if (msg) { msg.textContent = '没有连线的文本节点'; msg.style.color = 'var(--err-fg)'; }
                return;
            }
            const ta = document.getElementById('cnModalContent');
            const parts = linked.map(x => (x.content || '').trim());
            const block = parts.join('\n\n---\n\n');
            if (ta) {
                ta.value = ta.value ? ta.value + '\n\n---\n\n' + block : block;
                ta.dispatchEvent(new Event('input'));
            }
            if (msg) { msg.textContent = '已读取 ' + linked.length + ' 个文本节点'; msg.style.color = 'var(--ok-fg)'; }
        }

        // V1.8.244：编辑弹窗里的「🎨 AI 生图 / 🎬 生成视频」。
        // 🔴 必须先把弹窗里改过的字段灌回节点：`canvasGenerateImage()` 读的是
        //    `n.content` / `n.size` / `n.model`，而用户是在弹窗里刚改的 Prompt ——
        //    不灌回去就会拿**上次保存的旧值**去烧额度，界面看着点了新 Prompt，
        //    出来的图却是旧的（用户报障「改了 Prompt 没变化」的同一类坑）。
        function canvasNodeGenerateFromModal(id) {
            const n = canvasModule.nodes.find(x => x.id === id);
            if (!n) return;
            const t = document.getElementById('cnModalTitle');
            if (t) n.title = t.value.trim() || canvasTypeLabel(n.type);
            const c = document.getElementById('cnModalContent');
            if (c) n.content = c.value.trim();
            const m = document.getElementById('cnModalModel');
            if (m) n.model = m.value;
            const s = document.getElementById('cnModalSize');
            if (s) n.size = s.value;
            const asp = document.getElementById('cnModalAspect');
            if (asp) n.size = asp.value;
            const sec = document.getElementById('cnModalSeconds');
            if (sec) n.seconds = parseInt(sec.value, 10) || 5;
            canvasCloseNodeModal();
            canvasRenderAll();
            canvasAutoSave();
            canvasNodeGenerate(id);
        }

        async function canvasNodeGenerate(id) {
            const n = canvasModule.nodes.find(x => x.id === id);
            if (!n) return;
            if (n.status === 'generating') { showToast('该节点正在生成中...', 'info'); return; }

            if (n.type === 'note') {
                await canvasNoteContinue(n);
            } else if (n.type === 'image') {
                if (!n.content) { showToast('请先在节点中填写图片描述', 'error'); canvasOpenNodeModal(id); return; }
                await canvasGenerateImage(n);
            } else if (n.type === 'video') {
                if (!n.content) {
                    // Prompt 还空着：先自动读连线的文本节点，读到就能直接生成
                    const linkedNotes = canvasModule.links
                        .filter(l => l.to === n.id)
                        .map(l => canvasModule.nodes.find(x => x.id === l.from))
                        .filter(x => x && x.type === 'note' && (x.content || '').trim());
                    if (linkedNotes.length) {
                        n.content = linkedNotes.map(x => (x.content || '').trim()).join('\n\n---\n\n');
                        showToast('已自动读取 ' + linkedNotes.length + ' 个连线文本节点作为 Prompt', 'success');
                    }
                }
                if (!n.content) { showToast('请先在节点中填写视频描述', 'error'); canvasOpenNodeModal(id); return; }
                await canvasGenerateVideo(n);
            }
        }

        // 文本节点：AI 续写
        async function canvasNoteContinue(n) {
            if (!n.content) { showToast('节点内容为空，请先输入内容', 'error'); canvasOpenNodeModal(n.id); return; }
            const instruction = (document.getElementById('cnModalInstruction') && document.getElementById('canvasNodeModal').style.display !== 'none')
                ? document.getElementById('cnModalInstruction').value.trim() || '续写' : '续写';
            n.status = 'generating';
            canvasRenderNodes();
            try {
                const resp = await fetch('/api/text/generate', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ content: n.content, instruction, model: '' })
                });
                const data = await resp.json();
                if (data.success) {
                    n.content = n.content + '\n\n' + data.content;
                    n.status = 'idle';
                    showToast('AI 续写完成', 'success');
                } else {
                    n.status = 'failed';
                    n.error = data.error || '续写失败';
                    showToast('续写失败: ' + n.error, 'error');
                }
            } catch (e) {
                n.status = 'failed';
                n.error = e.message;
                showToast('续写失败: ' + e.message, 'error');
            }
            canvasRenderAll();
            canvasAutoSave();
        }

        // 图片节点：文生图
        async function canvasGenerateImage(n) {
            const cur = (n.imageUrls && n.imageUrls.length) ? n.imageUrls.length : (n.imageUrl ? 1 : 0);
            if (cur >= 5) { showToast('已达 5 张上限，无法再生成', 'error'); return; }
            n.status = 'generating';
            n.error = '';
            canvasRenderNodes();
            try {
                // 🔴 V1.8.244：给同步生图加超时。以前没有超时 —— 上游挂住时
                // fetch 永远不返回，节点上的转圈也永远不停（用户只能刷新页面）。
                const ac = (typeof AbortController !== 'undefined') ? new AbortController() : null;
                const to = ac ? setTimeout(() => ac.abort(), 5 * 60 * 1000) : null;
                let resp;
                try {
                    resp = await fetch('/api/image/generate', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            prompt: n.content,
                            size: n.size || '1024x1024',
                            model: n.model || 'sensenova-u1.5-lite',
                            save_local: true
                        }),
                        signal: ac ? ac.signal : undefined
                    });
                } finally { if (to) clearTimeout(to); }
                const data = await resp.json();
                if (data.success) {
                    if (!n.imageUrls) n.imageUrls = [];
                    n.imageUrls.push(data.image_url);
                    n.imageUrl = n.imageUrls[0];
                    n.prompt = n.content;
                    n.status = 'idle';
                    showToast('图片生成成功（共 ' + n.imageUrls.length + ' 张）', 'success');
                } else {
                    n.status = 'failed';
                    n.error = data.error || '生成失败';
                    showToast('生成失败: ' + n.error, 'error');
                }
            } catch (e) {
                n.status = 'failed';
                n.error = e.message;
                showToast('生成失败: ' + e.message, 'error');
            }
            canvasRenderAll();
            canvasAutoSave();
        }

        // 视频节点：文生视频 / 图生视频
        // 宽高比 → 像素尺寸（Agnes Video 2.5 只认 aspect_ratio，不认自定义像素，
        // 这里给一组与官方档位对齐的常用分辨率，后端再按 aspect_ratio 归一化）
        function canvasVideoSizeWH(aspect) {
            const map = {
                '16:9': [1280, 720], '9:16': [720, 1280], '4:3': [1024, 768],
                '1:1': [1024, 1024], '3:4': [768, 1024]
            };
            return map[aspect] || map['16:9'];
        }
        async function canvasGenerateVideo(n) {
            n.status = 'generating';
            n.videoStatus = '提交中...';
            n.error = '';
            canvasRenderNodes();

            // 参考图：优先节点保存的 refImageId，否则尝试使用画布上已连接的图片节点
            let refImageId = n.refImageId || '';
            if (!refImageId) {
                const linked = canvasModule.links.find(l => l.to === n.id);
                if (linked) {
                    const imgNode = canvasModule.nodes.find(x => x.id === linked.from && ((x.imageUrls && x.imageUrls.length) || x.imageUrl));
                    if (imgNode) refImageId = imgNode.id;
                }
            }
            const refNode = refImageId ? canvasModule.nodes.find(x => x.id === refImageId) : null;
            const refUrls = (refNode && refNode.imageUrls && refNode.imageUrls.length) ? refNode.imageUrls
                : (refNode && refNode.imageUrl ? [refNode.imageUrl] : []);
            const imageUrls = refUrls;
            // 参考声音：优先节点保存的 refAudioId，否则用已连线的声音节点
            let audioUrl = '';
            let refAudioId = n.refAudioId || '';
            if (!refAudioId) {
                const linkedAudio = canvasModule.links.find(l => l.to === n.id
                    && canvasModule.nodes.find(x => x.id === l.from && x.type === 'sound' && x.audioUrl));
                if (linkedAudio) refAudioId = linkedAudio.from;
            }
            if (refAudioId) {
                const auNode = canvasModule.nodes.find(x => x.id === refAudioId);
                if (auNode && auNode.audioUrl) audioUrl = auNode.audioUrl;
            }
            // num_frames 仍传，供 MiniMax 等其它模型分支使用。
            const aspect = n.size || '16:9';
            const [vw, vh] = canvasVideoSizeWH(aspect);
            const seconds = n.seconds || 5;

            try {
                const body = {
                    prompt: n.content,
                    model: n.model || 'agnes-video-2.5-flash',
                    image_urls: imageUrls,
                    seconds: seconds,
                    width: vw,
                    height: vh,
                    num_frames: seconds * 24,
                    frame_rate: 24
                };
                if (audioUrl) body.audio_url = audioUrl;
                const resp = await fetch('/api/video/generate', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(body)
                });
                const data = await gwJson(resp, '视频任务');
                if (data.success) {
                    const taskId = data.task_id;
                    n.videoTaskId = taskId;
                    n.videoStatus = '排队中...';
                    canvasRenderNodes();
                    // 轮询视频状态
                    canvasStartVideoPoll(n);
                } else {
                    n.status = 'failed';
                    n.error = data.error || '提交失败';
                    showToast('提交失败: ' + n.error, 'error');
                    canvasRenderAll();
                }
            } catch (e) {
                n.status = 'failed';
                n.error = e.message;
                showToast('提交失败: ' + e.message, 'error');
                canvasRenderAll();
            }
            canvasAutoSave();
        }

        // 🔴 V1.8.244：把「生成中」的节点接回轮询 / 解除卡死的转圈。
        //
        // 为什么需要它：`status='generating'` 是**跟着画布一起存盘**的。以前刷新 /
        // 切页签 / 重新导入后，节点原样带着「生成中」回来，但**没有任何轮询在跑**
        // （`canvasStartVideoPoll` 只在提交那一刻调用）→ 服务端任务早跑完了，
        // 界面上的转圈却永远不停。用户看到的就是「编辑视频节点一直在转圈圈」。
        //
        // 处理规则（宁可见错，不可见无限转圈）：
        //   · 视频节点 + 有 videoTaskId → 重新挂轮询，接着查服务端真实状态；
        //   · 视频节点 + 没有 videoTaskId（老画布 / 旧版本存的）→ 明确判失败，
        //     告诉用户「任务 ID 随旧版本丢了，请重新生成」，别让它假装还在跑；
        //   · 图片 / 文本节点还是 generating → 那是**同步 fetch**，刷新即中断，
        //     服务端可能出了图也可能没出 → 退回 idle 并提示「上次被刷新中断」。
        function canvasResumePolls() {
            let resumed = 0, recovered = 0;
            canvasModule.nodes.forEach(n => {
                if (n.status !== 'generating') return;
                if (n.type === 'video') {
                    if (n.videoTaskId) {
                        canvasStartVideoPoll(n);
                        resumed++;
                    } else {
                        n.status = 'failed';
                        n.error = '生成任务在页面刷新前中断，且任务 ID 未随旧版本画布保存 —— 请点「🔄 重新生成」';
                        recovered++;
                    }
                } else {
                    // 图片 / 文本：同步请求被刷新打断，无法确认服务端结果
                    n.status = 'idle';
                    n.error = '';
                    recovered++;
                }
            });
            if (resumed || recovered) {
                canvasRenderAll();
                canvasAutoSave();
                if (recovered) {
                    showToast('已解除 ' + recovered + ' 个卡在「生成中」的节点（页面刷新会中断生成）', 'info');
                }
                if (resumed) {
                    showToast('已恢复 ' + resumed + ' 个视频节点的进度查询', 'info');
                }
            }
        }

        function canvasStartVideoPoll(n) {
            if (canvasModule.pollTimers[n.id]) clearInterval(canvasModule.pollTimers[n.id]);
            if (!n.videoTaskId) {
                n.status = 'failed';
                n.error = '没有视频任务 ID，无法查询进度';
                canvasRenderAll();
                return;
            }
            n.status = 'generating';
            n.error = '';
            // 🔴 轮询韧性（V1.8.244）：网络抖动 / 服务重启不能变成「永远转圈」。
            // 连续查不动就收口报错；总时长也设上限（视频上游正常几分钟内出，
            // 40 分钟还不结束就当它死了，别让用户对着一颗永动的 spinner）。
            const pollState = { errs: 0, startedAt: Date.now() };
            const MAX_ERRS = 10;              // 连续失败上限
            const MAX_MS = 40 * 60 * 1000;    // 总时长上限 40 分钟
            const stopPoll = (status, err) => {
                if (canvasModule.pollTimers[n.id]) clearInterval(canvasModule.pollTimers[n.id]);
                delete canvasModule.pollTimers[n.id];
                n.status = status;
                if (err) n.error = err;
                canvasRenderAll();
                canvasAutoSave();
            };
            canvasModule.pollTimers[n.id] = setInterval(async () => {
                if (Date.now() - pollState.startedAt > MAX_MS) {
                    stopPoll('failed', '查询超时（超过 40 分钟仍未出片）—— 请到「视频任务」页确认，或重新生成');
                    showToast('视频生成查询超时', 'error');
                    return;
                }
                try {
                    const resp = await fetch(`/api/video/status/${encodeURIComponent(n.videoTaskId)}`);
                    if (!resp.ok) {
                        // 404 = 任务不在内存里（服务重启过 / 任务被清理）→ 明确失败，
                        // 不能再装作还在跑。
                        pollState.errs++;
                        if (pollState.errs >= MAX_ERRS || resp.status === 404) {
                            stopPoll('failed', '查询不到该视频任务（HTTP ' + resp.status
                                + '，服务可能重启过）—— 请重新生成');
                            showToast('视频任务查询失败', 'error');
                        }
                        return;
                    }
                    const data = await resp.json();
                    if (!data.success) {
                        pollState.errs++;
                        if (pollState.errs >= MAX_ERRS) {
                            stopPoll('failed', data.error || '查询失败');
                            showToast('视频查询失败', 'error');
                        }
                        return;
                    }
                    pollState.errs = 0;      // 查通了就清零
                    if (data.status === 'completed') {
                        stopPoll('idle', '');
                        n.videoUrl = data.video_url || '';
                        n.prompt = n.content;
                        showToast('视频生成完成', 'success');
                    } else if (data.status === 'failed') {
                        stopPoll('failed', data.error || '生成失败');
                        showToast('视频生成失败: ' + (n.error || ''), 'error');
                    } else if (data.status === 'submitting' || data.status === 'processing'
                               || data.status === 'pending' || data.status === 'queued') {
                        n.videoStatus = data.status === 'processing' ? '生成中...' : (data.status || '排队中...');
                        canvasRenderNodes();
                    } else {
                        // 🔴 未知终态（cancelled / stopped / timeout …）以前会掉进
                        // 「继续轮询」分支 → 永远转圈。现在一律收口成人话。
                        stopPoll('failed', '视频任务状态异常：' + (data.status || '未知')
                            + ' —— 请重新生成');
                        showToast('视频任务状态异常', 'error');
                    }
                } catch (e) {
                    pollState.errs++;
                    if (pollState.errs >= MAX_ERRS) {
                        stopPoll('failed', '查询失败（网络不通）：' + (e && e.message ? e.message : e));
                        showToast('视频查询失败', 'error');
                    }
                }
                canvasAutoSave();
            }, 5000);
        }

        // 历史快照：只在「结构变化」时压栈（增删节点、移动节点、增删连线、清空、导入）。
        // 生成过程中的 status 变化不压栈 —— 那不是可撤销的结构动作。
        function canvasPushHistory() {
            if (!canvasModule.history) canvasModule.history = [];
            // 截掉当前指针之后的分支（改过再撤销，之后的重做记录应失效）
            if (canvasModule.history.length > 0 && canvasModule.historyIndex < canvasModule.history.length - 1) {
                canvasModule.history = canvasModule.history.slice(0, canvasModule.historyIndex + 1);
            }
            canvasModule.history.push({
                nodes: JSON.parse(JSON.stringify(canvasModule.nodes)),
                links: JSON.parse(JSON.stringify(canvasModule.links)),
                scale: canvasModule.scale,
                viewX: canvasModule.viewX,
                viewY: canvasModule.viewY,
                nextId: canvasModule.nextId
            });
            if (canvasModule.history.length > 50) {
                canvasModule.history.shift();
                canvasModule.historyIndex = canvasModule.history.length - 1;
            } else {
                canvasModule.historyIndex = canvasModule.history.length - 1;
            }
            canvasUpdateUndoUI();
        }

        function canvasRestoreSnapshot(s) {
            // 🔴 V1.8.244：撤销/重做会**整体替换** nodes 数组，而轮询闭包里捕获的是
            // 旧 node 对象 —— 不处理的话旧定时器继续改一个已经不在界面上的对象，
            // 新节点永远停在「生成中」转圈（undo 之后卡死的另一条路径）。
            // 所以先全停，再按快照里的真实状态重新接。
            Object.values(canvasModule.pollTimers).forEach(t => clearInterval(t));
            canvasModule.pollTimers = {};
            canvasModule.nodes = JSON.parse(JSON.stringify(s.nodes));
            canvasModule.links = JSON.parse(JSON.stringify(s.links));
            canvasModule.scale = s.scale;
            canvasModule.viewX = s.viewX;
            canvasModule.viewY = s.viewY;
            canvasModule.nextId = s.nextId;
            canvasModule.selectedId = null;
            canvasModule.connectFromId = null;
            canvasUpdateConnectUI();
            canvasRenderAll();
            canvasResumePolls();
            canvasAutoSave();
        }

        function canvasUndo() {
            if (!canvasModule.history || canvasModule.historyIndex <= 0) {
                showToast('没有可撤销的操作', 'info'); return;
            }
            canvasModule.historyIndex--;
            canvasRestoreSnapshot(canvasModule.history[canvasModule.historyIndex]);
            canvasUpdateUndoUI();
            showToast('已撤销', 'info');
        }

        function canvasRedo() {
            if (!canvasModule.history || canvasModule.historyIndex >= canvasModule.history.length - 1) {
                showToast('没有可重做的操作', 'info'); return;
            }
            canvasModule.historyIndex++;
            canvasRestoreSnapshot(canvasModule.history[canvasModule.historyIndex]);
            canvasUpdateUndoUI();
            showToast('已重做', 'info');
        }

        function canvasUpdateUndoUI() {
            const canUndo = canvasModule.history && canvasModule.historyIndex > 0;
            const canRedo = canvasModule.history && canvasModule.historyIndex < canvasModule.history.length - 1;
            const u = document.getElementById('canvasUndoBtn');
            const r = document.getElementById('canvasRedoBtn');
            if (u) { u.disabled = !canUndo; u.style.opacity = canUndo ? '1' : '0.4'; }
            if (r) { r.disabled = !canRedo; r.style.opacity = canRedo ? '1' : '0.4'; }
        }

        function canvasToggleMinimap() {
            const el = document.getElementById('canvasMinimap');
            const btn = document.getElementById('canvasMinimapBtn');
            const on = el.style.display !== 'none';
            el.style.display = on ? 'none' : 'block';
            if (btn) btn.classList.toggle('active', !on);
            if (!on) canvasRenderMinimap();
        }

        function canvasRenderMinimap() {
            const svg = document.getElementById('canvasMinimapSvg');
            if (!svg) return;
            const vp = document.getElementById('canvasViewport');
            const vpr = vp.getBoundingClientRect();
            const vLeft = canvasModule.viewX;
            const vTop = canvasModule.viewY;
            const vRight = canvasModule.viewX + vpr.width / canvasModule.scale;
            const vBottom = canvasModule.viewY + vpr.height / canvasModule.scale;

            let minX = vLeft, minY = vTop, maxX = vRight, maxY = vBottom;
            canvasModule.nodes.forEach(n => {
                minX = Math.min(minX, n.x); minY = Math.min(minY, n.y);
                maxX = Math.max(maxX, n.x + n.w); maxY = Math.max(maxY, n.y + (n.h || 120));
            });
            const spanX = Math.max(1, maxX - minX);
            const spanY = Math.max(1, maxY - minY);
            const W = 190, H = 120;
            const PAD = 6;
            const s = Math.min((W - PAD * 2) / spanX, (H - PAD * 2) / spanY);
            const ox = PAD + (W - PAD * 2 - spanX * s) / 2;
            const oy = PAD + (H - PAD * 2 - spanY * s) / 2;
            const px = (x) => ox + (x - minX) * s;
            const py = (y) => oy + (y - minY) * s;

            let html = '';
            // 连线
            canvasModule.links.forEach(l => {
                const a = canvasModule.nodes.find(n => n.id === l.from);
                const b = canvasModule.nodes.find(n => n.id === l.to);
                if (!a || !b) return;
                html += `<path class="mm-link" d="M ${px(a.x + a.w/2)} ${py(a.y + (a.h||60)/2)} C ${px((a.x+a.w/2+b.x)/2)} ${py(a.y+(a.h||60)/2)}, ${px((a.x+a.w/2+b.x)/2)} ${py(b.y+(b.h||60)/2)}, ${px(b.x + b.w/2)} ${py(b.y + (b.h||60)/2)}"></path>`;
            });
            // 节点
            canvasModule.nodes.forEach(n => {
                const sel = n.id === canvasModule.selectedId ? 'selected' : '';
                html += `<rect class="mm-node ${sel}" x="${px(n.x)}" y="${py(n.y)}" width="${Math.max(2, n.w * s)}" height="${Math.max(2, (n.h || 120) * s)}" rx="2"></rect>`;
            });
            // 视口框
            html += `<rect class="mm-viewport" x="${px(vLeft)}" y="${py(vTop)}" width="${Math.max(1, (vRight - vLeft) * s)}" height="${Math.max(1, (vBottom - vTop) * s)}"></rect>`;

            svg.setAttribute('width', W);
            svg.setAttribute('height', H);
            svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
            svg.innerHTML = html;

            // 拖拽移动视口
            let start = null;
            const onDown = (e) => {
                const rect = svg.getBoundingClientRect();
                const mx = e.clientX - rect.left, my = e.clientY - rect.top;
                const wx = minX + (mx - ox) / s;
                const wy = minY + (my - oy) / s;
                start = { wx, wy, viewX: canvasModule.viewX, viewY: canvasModule.viewY };
                svg.setCapture && svg.setCapture();
            };
            const onMove = (e) => {
                if (!start) return;
                const rect = svg.getBoundingClientRect();
                const mx = e.clientX - rect.left, my = e.clientY - rect.top;
                const wx = minX + (mx - ox) / s;
                const wy = minY + (my - oy) / s;
                canvasModule.viewX = start.viewX + (wx - start.wx);
                canvasModule.viewY = start.viewY + (wy - start.wy);
                canvasApplyTransform();
                canvasRenderMinimap();
            };
            const onUp = () => { if (start) { start = null; canvasAutoSave(); } };
            svg.onmousedown = onDown;
            document.onmousemove = onMove;
            document.onmouseup = onUp;
        }

        function canvasExportJSON() {
            const payload = {
                nodes: canvasModule.nodes.map(n => ({
                    id: n.id, type: n.type, x: n.x, y: n.y, w: n.w, h: n.h,
                    title: n.title, content: n.content,
                    imageUrl: n.imageUrl || '', imageUrls: n.imageUrls || [],
                    videoUrl: n.videoUrl || '', audioUrl: n.audioUrl || '',
                    model: n.model || '', size: n.size || '', status: n.status || 'idle',
                    prompt: n.prompt || '', refImageId: n.refImageId || '', refAudioId: n.refAudioId || '',
                    frames: n.frames || '', seconds: n.seconds || 5
                })),
                links: canvasModule.links,
                scale: canvasModule.scale,
                viewX: canvasModule.viewX,
                viewY: canvasModule.viewY
            };
            const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = 'canvas-' + new Date().toISOString().slice(0, 10) + '.json';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
            showToast('画布已导出', 'success');
        }

        function canvasImportJSON() {
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = 'application/json,.json';
            input.addEventListener('change', (e) => {
                const file = e.target.files[0];
                if (!file) return;
                const reader = new FileReader();
                reader.onload = (ev) => {
                    try {
                        const data = JSON.parse(ev.target.result);
                        if (!data || !Array.isArray(data.nodes)) { showToast('无效的画布文件', 'error'); return; }
                        if (canvasModule.nodes.length && !confirm('导入将替换当前画布（可用撤销恢复），确定吗？')) return;
                        canvasPushHistory();
                        canvasModule.nodes = data.nodes.map(n => ({
                            id: n.id, type: n.type, x: n.x, y: n.y, w: n.w || 220, h: n.h || 120,
                            title: n.title || canvasTypeLabel(n.type), content: n.content || '',
                            imageUrl: n.imageUrl || '', imageUrls: n.imageUrls || [],
                            videoUrl: n.videoUrl || '', audioUrl: n.audioUrl || '',
                            model: n.model || '', size: n.size || '', status: n.status || 'idle',
                            prompt: n.prompt || '', refImageId: n.refImageId || '', refAudioId: n.refAudioId || '',
                            frames: n.frames || '', seconds: n.seconds || 5,
                            videoTaskId: n.videoTaskId || '', videoStatus: n.videoStatus || '',
                            error: n.error || ''
                        }));
                        canvasModule.nodes.forEach(n => {
                            if (n.type === 'image' && (!n.imageUrls || !n.imageUrls.length) && n.imageUrl) {
                                n.imageUrls = [n.imageUrl];
                            }
                        });
                        canvasModule.links = data.links || [];
                        canvasModule.scale = data.scale || 1;
                        canvasModule.viewX = data.viewX || 0;
                        canvasModule.viewY = data.viewY || 0;
                        canvasModule.nextId = Math.max(1, ...canvasModule.nodes.map(n => parseInt(n.id.replace(/\D/g, '')) || 0)) + 1;
                        canvasModule.selectedId = null;
                        canvasModule.connectFromId = null;
                        canvasUpdateConnectUI();
                        canvasRenderAll();
                        // V1.8.244：导入同样可能带进「生成中」的节点，一并接回轮询
                        canvasResumePolls();
                        canvasSave();
                        showToast('画布已导入', 'success');
                    } catch (err) {
                        showToast('导入失败: ' + err.message, 'error');
                    }
                };
                reader.onerror = () => showToast('读取文件失败', 'error');
                reader.readAsText(file);
            });
            input.click();
        }

        // 痛点：全站每个生成动作都要等几十秒到几分钟，界面上只有一句「⏳ 正在生成…」，
        // 用户对着不动的界面不知道还要多久。这里统一给「生成窗口」挂一条百分比进度条。
        //
        // 机制（一次包装 fetch，全站自动生效，不必逐个模块改）：
        //   ① 起条：POST 打向生成类接口 → 以「触发那一刻所在的卡片」为锚点，在该卡片末尾插条；
        //   ② 计程：没有真实进度数据时按模块 ETA 平滑估算，**封顶 95%**，绝不到 100% 骗人；
        //   ③ 真实进度：模块自己的 /status 轮询经过这里时，解析 done/total、progress、stage 等
        //      字段覆盖估算值 —— 有真数据就一律用真数据（真实值不再显示「~」）；
        //   ④ 收条：接口返回终态（或 /status 报完成/失败）→ 100% 后淡出（成功绿 / 失败红）。
        //
        // ⚠️ 只对「小响应」做 JSON 嗅探：生图接口会把整张图作为 data URL 塞进 JSON（可达 7MB），
        //    对它 clone().json() 会把主线程与内存都拖垮 —— 所以先看 content-length 再决定。
        const GENPROG_PREFIXES = [
            ['/api/dramapro/', '短剧流水线 Pro', 150],
            ['/api/shortline/', '短剧线', 150],
            ['/api/drama/', '短剧生成', 150],
            ['/api/video/', '视频生成', 180],
            ['/api/mv/', 'MTV 生成', 180],
            ['/api/image/', '图片生成', 30],
            ['/api/cover/', '封面生成', 30],
            ['/api/comic/', '漫画生成', 150],
            ['/api/mcomic/', '漫画生成', 150],
            ['/api/iugn/', '手绘风格库', 60],
            ['/api/anchor/', 'AI 口播', 60],
            ['/api/df/', 'AI 口播', 60],
            ['/api/cyberverse/', '数字人', 40],
            ['/api/precheck/', '发布预检', 25],
            ['/api/tts/', '语音合成', 30],
            ['/api/novel/', '小说写作', 30],
            ['/api/wechat/', '营销写作', 30],
            ['/api/unicut/', '导入剪辑打包', 60],
            ['/api/ai/', 'AI 对话', 20],
            ['/api/chat', 'AI 对话', 20],
            ['/api/search/', '联网搜索', 25],
            ['/api/inkos/', '写作台', 60],
            ['/api/asset/', '资产生图', 30],
            ['/api/seedance/', '提示词库', 10],
            ['/api/kuwo/', '曲库', 10],
            ['/api/tunetank/', '曲库', 20],
        ];
        // 命中这些片段的 POST 是「轻动作」（保存/停止/配置/上传…），不弹进度条
        const GENPROG_SKIP = ['/stop', '/delete', '/clear', '/save', '/settings', '/confirm',
            '/config', '/models', '/keys', '/test', '/probe', '/login', '/logout', '/upload',
            '/terms', '/platforms', '/catalog', '/presets', '/lanes', '/overview', '/select',
            '/status', '/result', '/list', '/preview'];
        const GENPROG_TERMINAL = ['done', 'success', 'succeeded', 'completed', 'complete',
            'finished', 'failed', 'error', 'stopped', 'cancelled', 'canceled'];
        const GENPROG_FAIL = ['failed', 'error', 'stopped', 'cancelled', 'canceled'];
        let genProgBars = {};          // prefix -> 进度条状态
        let genProgWrapped = false;
        let genProgTimer = null;
        let genProgLastClickEl = null;

        function genProgPath(url) {
            const s = String(url || '');
            const m = s.match(/^(?:https?:\/\/[^/]+)?(\/[^?#]*)/);
            return m ? m[1] : s;
        }

        function genProgMatch(path) {
            for (const row of GENPROG_PREFIXES) {
                if (path.indexOf(row[0]) === 0) return { prefix: row[0], label: row[1], eta: row[2] };
            }
            return null;
        }

        function genProgIsSkip(path) {
            for (const s of GENPROG_SKIP) { if (path.indexOf(s) >= 0) return true; }
            return false;
        }

        function genProgIsStatus(path) {
            return path.indexOf('/status') >= 0 || path.indexOf('/result/') >= 0;
        }

        // 只有「小响应」才允许 clone 出来看 JSON —— 别去碰 7MB 的图片 data URL
        function genProgSmallEnough(resp) {
            try {
                const h = resp && resp.headers;
                if (!h || typeof h.get !== 'function') return false;
                const cl = h.get('content-length');
                if (cl == null) return false;
                const n = parseInt(cl, 10);
                return isFinite(n) && n > 1 && n <= 262144;
            } catch (e) { return false; }
        }

        function genProgAnchorCard() {
            try {
                let el = genProgLastClickEl;
                if (el && typeof el.closest === 'function') {
                    const c = el.closest('.card');
                    if (c) return c;
                }
                return document.querySelector('.tab-content.active') || null;
            } catch (e) { return null; }
        }

        function genProgEnsureBar(rule) {
            let st = genProgBars[rule.prefix];
            if (st && st.el && st.el.isConnected) return st;
            const el = document.createElement('div');
            el.className = 'genprog';
            el.setAttribute('data-genprog', rule.prefix);
            el.innerHTML = '<div class="genprog-head"><span class="genprog-label"></span>'
                + '<span class="genprog-pct">0%</span></div>'
                + '<div class="genprog-track"><div class="genprog-fill"></div></div>'
                + '<div class="genprog-note"></div>';
            const lbl = el.querySelector('.genprog-label');
            if (lbl) lbl.textContent = rule.label;
            const card = genProgAnchorCard();
            if (card) card.appendChild(el);
            else { el.classList.add('fixed'); document.body.appendChild(el); }
            st = { el: el, key: rule.prefix, label: rule.label, start: Date.now(),
                   real: null, pct: null, eta: rule.eta || 30, done: false };
            genProgBars[rule.prefix] = st;
            return st;
        }

        function genProgPaint(st) {
            if (!st || !st.el || !st.el.isConnected) return;
            const el = st.el;
            const elapsed = (Date.now() - st.start) / 1000;
            if (!st.done && elapsed > 1800) {
                genProgFinish(st.key, null, '超过 30 分钟没收到完成信号，已自动收条（任务可能仍在后台跑）');
                return;
            }
            let pct, isReal = false;
            if (st.pct != null) { pct = st.pct; }
            else if (st.real != null) { pct = st.real; isReal = true; }
            else { pct = 95 * (1 - Math.exp(-elapsed / Math.max(3, (st.eta || 30) / 2))); }
            pct = Math.max(0, Math.min(100, pct));
            const fill = el.querySelector('.genprog-fill');
            if (fill) fill.style.width = pct.toFixed(1) + '%';
            const pctEl = el.querySelector('.genprog-pct');
            if (pctEl) {
                const txt = (isReal ? '' : '~') + pct.toFixed(0) + '%';
                if (pctEl.textContent !== txt) pctEl.textContent = txt;
            }
            const noteEl = el.querySelector('.genprog-note');
            if (noteEl) {
                const secs = elapsed.toFixed(0);
                let note = '已用 ' + secs + ' 秒';
                if (isReal) note += ' · 已收到任务真实进度';
                else {
                    const left = Math.max(0, (st.eta || 30) - elapsed);
                    note += left > 0 ? (' · 预计还需约 ' + left.toFixed(0) + ' 秒（估算）')
                                     : ' · 仍在处理，快好了（估算已到顶，等完成信号）';
                }
                if (noteEl.textContent !== note) noteEl.textContent = note;
            }
        }

        function genProgTickAll() {
            let alive = 0;
            for (const k in genProgBars) {
                const st = genProgBars[k];
                if (!st.el || !st.el.isConnected) { delete genProgBars[k]; continue; }
                alive++;
                if (st.pct == null) genProgPaint(st);
            }
            if (!alive && genProgTimer) { clearInterval(genProgTimer); genProgTimer = null; }
        }

        function genProgEnsureTimer() {
            if (genProgTimer) return;
            genProgTimer = setInterval(genProgTickAll, 400);
        }

        function genProgStart(rule) {
            const st = genProgEnsureBar(rule);
            st.start = Date.now(); st.real = null; st.pct = null; st.done = false;
            st.eta = rule.eta || 30;
            st.el.classList.remove('done', 'err');
            st.el.style.opacity = '1';
            genProgPaint(st);
            genProgEnsureTimer();
            return st.key;
        }

        function genProgLooksAsync(j) {
            if (!j || typeof j !== 'object') return false;
            if (j.async === true || j.queued != null || j.job_id || j.task_id || j.jobId) return true;
            if (j.success === true && !j.image_url && !j.video_url && !j.local_file && !j.result) return true;
            return false;
        }

        function genProgExtractPct(j, depth) {
            if (!j || typeof j !== 'object') return null;
            if ((depth || 0) > 3) return null;
            const num = (v) => (typeof v === 'number' && isFinite(v)) ? v : null;
            const pairs = [[j.done, j.total], [j.finished, j.total], [j.completed, j.total],
                [j.steps_done, j.steps_total], [j.current, j.total], [j.stage, j.stage_total],
                [j.index, j.count], [j.videos_done, j.videos_total], [j.frames_done, j.frames_total],
                [j.images_done, j.images_total], [j.assets_done, j.assets_total]];
            for (const p of pairs) {
                const a = num(p[0]), b = num(p[1]);
                if (a != null && b != null && b > 0) return Math.max(0, Math.min(100, a / b * 100));
            }
            for (const k of ['progress', 'video_queue', 'stat', 'stats', 'steps']) {
                const r = genProgExtractPct(j[k], (depth || 0) + 1);
                if (r != null) return r;
            }
            const p = num(j.progress);
            if (p != null) return p <= 1 ? p * 100 : Math.max(0, Math.min(100, p));
            const pc = num(j.percent);
            if (pc != null) return Math.max(0, Math.min(100, pc));
            return null;
        }

        function genProgStatusOf(j) {
            if (!j || typeof j !== 'object') return '';
            return String(j.status || j.state || '').toLowerCase();
        }

        function genProgIsTerminal(j) {
            if (!j || typeof j !== 'object') return false;
            if (GENPROG_TERMINAL.indexOf(genProgStatusOf(j)) >= 0) return true;
            return j.done === true || j.finished === true;
        }

        function genProgIsFailure(j) {
            if (!j || typeof j !== 'object') return false;
            if (GENPROG_FAIL.indexOf(genProgStatusOf(j)) >= 0) return true;
            return j.success === false;
        }

        function genProgFinish(key, ok, note) {
            const st = genProgBars[key];
            if (!st || !st.el) return;
            st.done = true; st.pct = 100;
            const el = st.el;
            el.classList.toggle('done', ok !== false);
            el.classList.toggle('err', ok === false);
            const fill = el.querySelector('.genprog-fill');
            if (fill) fill.style.width = '100%';
            const pctEl = el.querySelector('.genprog-pct');
            if (pctEl) pctEl.textContent = ok === false ? '失败' : '100%';
            const noteEl = el.querySelector('.genprog-note');
            if (noteEl) {
                const secs = ((Date.now() - st.start) / 1000).toFixed(0);
                noteEl.textContent = (note || (ok === false ? '生成失败' : '完成')) + ' · 共 ' + secs + ' 秒';
            }
            const stashed = st;
            setTimeout(function () {
                try {
                    if (!stashed.el || !stashed.el.isConnected) return;
                    stashed.el.style.transition = 'opacity .45s';
                    stashed.el.style.opacity = '0';
                    setTimeout(function () {
                        try { if (stashed.el && stashed.el.parentNode) stashed.el.parentNode.removeChild(stashed.el); } catch (e) {}
                        delete genProgBars[stashed.key];
                    }, 480);
                } catch (e) {}
            }, ok === false ? 8000 : 1600);
        }

        function genProgFeedStatus(key, j) {
            const st = genProgBars[key];
            if (!st) return;
            if (genProgIsTerminal(j)) { genProgFinish(key, !genProgIsFailure(j)); return; }
            const pct = genProgExtractPct(j, 0);
            if (pct != null) st.real = pct;
            genProgPaint(st);
        }

        function genProgKeepTracking(key, j) {
            const st = genProgBars[key];
            if (!st) return;
            const msg = j.message || j.status_text || j.stage_name || '';
            if (msg) {
                const noteEl = st.el && st.el.querySelector('.genprog-note');
                if (noteEl) noteEl.textContent = String(msg).slice(0, 90);
            }
            st.eta = Math.max(st.eta || 30, 180);   // 异步任务通常更久，别把估算推到头
        }

        function initGenProgress() {
            if (genProgWrapped || !window.fetch) return;
            genProgWrapped = true;
            // 记「最后一次点击的元素」：生成按钮被点后它就是最可靠的锚点来源
            document.addEventListener('click', function (e) { genProgLastClickEl = e.target; }, true);
            const origFetch = window.fetch.bind(window);
            window.fetch = function (input, init) {
                let url = '', method = 'GET';
                try {
                    url = (typeof input === 'string') ? input : ((input && input.url) || '');
                    method = String((init && init.method) || (input && input.method) || 'GET').toUpperCase();
                } catch (e) { /* noop */ }
                const path = genProgPath(url);
                const rule = genProgMatch(path);
                let key = null, isStart = false;
                if (rule) {
                    if (method === 'POST' && !genProgIsSkip(path)) { key = genProgStart(rule); isStart = true; }
                    else if (method === 'GET' && genProgIsStatus(path)) { key = rule.prefix; }
                }
                const p = origFetch(input, init);
                if (!key) return p;
                return p.then(function (resp) {
                    try {
                        if (!genProgBars[key]) return resp;
                        if (!isStart) {                                  // 轮询：喂真实进度
                            if (resp.ok && genProgSmallEnough(resp)) {
                                resp.clone().json().then(function (j) { genProgFeedStatus(key, j); }).catch(function () {});
                            }
                            return resp;
                        }
                        if (!resp.ok) { genProgFinish(key, false, '请求失败 HTTP ' + resp.status); return resp; }
                        if (genProgSmallEnough(resp)) {
                            resp.clone().json().then(function (j) {
                                if (genProgLooksAsync(j)) genProgKeepTracking(key, j);
                                else genProgFinish(key, j && j.success !== false);
                            }).catch(function () { genProgFinish(key, true); });
                        } else {
                            genProgFinish(key, true);                    // 大响应=已带回成品，直接收条
                        }
                    } catch (e) { /* 进度条绝不能影响主流程 */ }
                    return resp;
                }).catch(function (err) {
                    try { if (genProgBars[key]) genProgFinish(key, false, '请求异常：' + ((err && err.message) || err)); } catch (e) {}
                    throw err;
                });
            };
        }

        // 七色聊天背景：V1.8.205 已整体移除（东方小哥：去掉动态背景）

        // 这三个初始化会访问脚本中后段声明的 let/const（queueState / tvImages），
        // 必须等本文件全部声明执行完再跑，否则触发 TDZ 并打断整段脚本。
        // 放在这里（脚本最后一句）可以确保所有声明都已就绪。
        var _lateInitDone = false;
        function _lateInit() {
            if (_lateInitDone) return;
            _lateInitDone = true;
            // 🔴 V1.8.382：腾讯云认证回调失败提示（/api/auth/ciam/callback 302 回来带的）
            try {
                const ce = new URLSearchParams(location.search).get('ciam_error');
                if (ce) {
                    showToast('腾讯云认证：' + decodeURIComponent(ce), 'error');
                    history.replaceState(null, '', location.pathname);
                }
            } catch (e) { /* noop */ }
            const jobs = [
                // 整体搬进首页挂载点（保留全部元素 id，事件与状态不受影响），原面板壳留空隐藏。
                ['首页双板块挂载', function () {
                    const chatMount = document.getElementById('homeChatMount');
                    const galMount = document.getElementById('homeGalleryMount');
                    const chatPane = document.getElementById('tab-chat');
                    const galPane = document.getElementById('tab-gallery');
                    if (chatMount && chatPane) { while (chatPane.firstChild) chatMount.appendChild(chatPane.firstChild); }
                    if (galMount && galPane) { while (galPane.firstChild) galMount.appendChild(galPane.firstChild); }
                }],
                // 🔴 V1.8.280 修复「两个新闻都不行」的真正根因：
                //   这三个版块原先只在 switchTab('home') 里加载，而**首屏不走 switchTab**
                //   （#tab-home 靠 class="active" 静态显示）→ 用户打开页面就停在首页时，
                //   工作墙/新闻热点/全网热榜全卡在「加载中…」，一个请求都不发。
                //   必须显式首屏加载一次；switchTab 里保留（切回来时刷新/复用缓存）。
                ['首页三板块首屏加载', function () {
                    try { galleryLoad(); } catch (e) { /* 单个版块失败不拖累其它 */ }
                    try { newsLoad(false); } catch (e) { /* 同上 */ }
                    try { trendingLoad(false); } catch (e) { /* 同上 */ }
                }],
                ['一词二模模型', initDualModelSelects],
                ['自动排队生图器', initQueueModels],
                ['高清三视生图器', initTriviewModels],
                ['页面锁死', initPageLock],
                ['正文朗读声音表', function () {
                    if (window.speechSynthesis) {
                        speechSynthesis.onvoiceschanged = function () { try { docTtsRefreshVoices(); } catch (e) {} };
                        try { docTtsRefreshVoices(); } catch (e) {}
                    }
                }],
                ['对话语音朗读（MOSS-TTS-Nano）', hcTtsInit],
                ['全局生成进度条', initGenProgress],
                // 视频模型静态兜底 + 仙宫云主机补项：/api/drama/models 被门禁拦或
                // 拉取失败时，5 个视频下拉至少要有原来的模型清单（PROV_VIDEO_MODELS
                // 与后端 VIDEO_MODEL_OPTIONS 同源）；fillSelect 成功时会被动态列表覆盖。
                ['视频模型静态兜底 + 仙宫云主机', function () {
                    if (typeof PROV_VIDEO_MODELS !== 'object') return;
                    XG_MODEL_SELECTS.forEach(function (id) {
                        const sel = document.getElementById(id);
                        if (!sel) return;
                        const realOpts = [...sel.options].filter(function (o) { return o.value !== XG_MODEL_ID; });
                        if (realOpts.length === 0) {
                            for (const [val, label] of Object.entries(PROV_VIDEO_MODELS)) {
                                const op = document.createElement('option');
                                op.value = val;
                                op.textContent = label;
                                sel.appendChild(op);
                            }
                        }
                        xgAppendModelOption(id);
                    });
                }],
                // V1.8.239：给每个视频模型下拉挂常驻入口（已配置也能打开配置窗）
                ['仙宫云主机常驻入口', xgAttachEntryButtons],
                // V1.8.243：白板多线 KEY 输入框按 localStorage 恢复（＋ 号自增的行）
                ['白板多线KEY恢复', function () { try { wbInitKeyRows(); } catch (e) {} }],
                // V1.8.292：三处「输出结果」抽屉的**初始**开合 ——
                // 快照恢复后文本框里可能已经有上次的结果，这种「有工作」的状态要展开；
                // 空着则收拢（东方小哥：「没有工作的时候，折叠收拢」）。
                ['输出结果抽屉初始态', function () { try { pexpertInitOutDrawers(); } catch (e) {} }],
            ];
            for (const [name, fn] of jobs) {
                try { fn(); } catch (e) { console.error('[初始化失败] ' + name + ':', e); }
            }
            try { initBtnLoadingAuto(); } catch (e) { console.error('[初始化失败] 按钮加载态:', e); }
            try { LoadingKit.hidePage(); } catch (e) {}
            // 安全兜底：万一后续脚本异常，最多 5s 后强制收起 Page Loader
            setTimeout(function () { try { LoadingKit.hidePage(); } catch (e) {} }, 5000);
        }
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', _lateInit);
        } else {
            _lateInit();
        }

        function escHtml(str) {
            return String(str == null ? '' : str)
                .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
        }

    

